import { jsPDF } from 'jspdf';
import { Order } from '../types';

/**
 * Generates a production-ready shipping and tax label PDF.
 * Layout mirrors standard Amazon/Flipkart courier manifests.
 * Returns the jsPDF instance for flexible handling (preview/print/save).
 */
export const generateShippingLabelPDF = async (order: Order): Promise<jsPDF> => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const address = order.shippingAddress || order.shipping_address;
  const isCOD = order.payment_mode === 'Cash on Delivery';

  // Financial Math (Back-calculating 18% GST from inclusive total)
  const totalAmount = Number(order.total_amount || order.total || 0);
  const subtotal = totalAmount / 1.18;
  const gstAmount = totalAmount - subtotal;

  const vendorName = order.seller_name || order.items[0]?.vendor_name || 'VexoKart Authorized Vendor';
  const vendorId = order.vendor_id || order.items[0]?.vendor_id || 'VX-001';

  // --- TOP HEADER ---
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(24);
  doc.text('VexoKart', 20, 20);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('LOGISTICS HUB', 20, 24);

  // Payment Badge (Right)
  doc.setFillColor(0, 0, 0);
  doc.rect(140, 12, 50, 12, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text(isCOD ? 'COD' : 'PAID', 165, 20, { align: 'center' });

  doc.setTextColor(0, 0, 0);
  doc.setFontSize(10);
  doc.text(`Order #${order.id}`, 190, 28, { align: 'right' });

  // Divider
  doc.setLineWidth(0.8);
  doc.line(20, 32, 190, 32);

  // --- ADDRESS SECTION (2 COLUMN) ---
  doc.setFontSize(8);
  doc.setTextColor(120, 120, 120);
  doc.text('SHIP FROM', 20, 40);
  doc.text('DELIVER TO', 110, 40);

  doc.setTextColor(0, 0, 0);
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text(vendorName, 20, 46); // Vendor
  doc.text(address?.fullName || 'Verified Customer', 110, 46); // Customer

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(60, 60, 60);

  // Vendor Block
  doc.text(['VexoKart Warehouse Node-A1', 'Fulfillment Park, Industrial Zone', 'India', `Vendor ID: ${vendorId}`, 'Ph: 1800-VEXO-KART'], 20, 52);

  // Customer Block
  const customerAddr = [
    address?.street || '',
    `${address?.city || ''}, ${address?.state || ''}`,
    `Phone: ${address?.phone || ''}`
  ];
  doc.text(customerAddr, 110, 52);

  // Pincode Highlight Box
  doc.setFillColor(245, 245, 245);
  doc.rect(110, 68, 40, 10, 'F');
  doc.setDrawColor(0, 0, 0);
  doc.rect(110, 68, 40, 10, 'S');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.text(address?.zip || '000000', 130, 75, { align: 'center' });

  // --- BARCODE / QR IDENTIFICATION ---
  doc.setLineWidth(0.3);
  doc.line(20, 85, 190, 85);

  // High Fidelity Barcode Generation using Rects
  doc.setFillColor(0, 0, 0);
  let startX = 25;
  const barWidths = [0.5, 1, 0.5, 1.5, 0.5, 2, 0.5, 1, 0.5, 1, 0.5, 2, 0.5, 1, 0.5, 1.5];
  for (let i = 0; i < 6; i++) {
    barWidths.forEach(w => {
        doc.rect(startX, 90, w, 15, 'F');
        startX += w + 0.8;
    });
  }

  doc.setTextColor(0, 0, 0);
  doc.setFontSize(9);
  doc.text(`ID: ${order.id}`, 105, 112, { align: 'center' });

  // QR Node (Simulated)
  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(0.5);
  doc.rect(160, 90, 25, 25, 'S');
  doc.setFontSize(6);
  doc.text('SECURE QR', 172.5, 103, { align: 'center' });
  doc.rect(162, 92, 5, 5, 'F');
  doc.rect(178, 92, 5, 5, 'F');
  doc.rect(162, 108, 5, 5, 'F');

  // --- ITEM SUMMARY ---
  doc.setLineWidth(0.5);
  doc.line(20, 125, 190, 125);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.text('ITEM DESCRIPTION', 20, 131);
  doc.text('QTY', 180, 131, { align: 'right' });
  doc.line(20, 133, 190, 133);

  doc.setFont('helvetica', 'normal');
  let y = 140;
  order.items.forEach((item) => {
    const itemName = item.name.length > 60 ? item.name.substring(0, 57) + '...' : item.name;
    doc.text(itemName, 20, y);
    doc.text(String(item.quantity), 180, y, { align: 'right' });
    y += 8;
  });

  // --- PRICE & TAX ---
  doc.line(130, y + 5, 190, y + 5);
  y += 12;
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('SUBTOTAL', 130, y);
  doc.setTextColor(0, 0, 0);
  doc.text(`INR ${subtotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`, 190, y, { align: 'right' });

  y += 6;
  doc.setTextColor(100, 100, 100);
  doc.text('GST (18%)', 130, y);
  doc.setTextColor(0, 0, 0);
  doc.text(`INR ${gstAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`, 190, y, { align: 'right' });

  y += 10;
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('TOTAL PAYABLE', 130, y);
  doc.text(`INR ${totalAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`, 190, y, { align: 'right' });

  // --- FOOTER ---
  doc.setFontSize(7);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(180, 180, 180);
  doc.text('THIS IS A COMPUTER GENERATED SHIPPING LABEL • VERIFIED BY VEXOKART PROTOCOL V.5.0', 105, 280, { align: 'center' });
  doc.text('VexoKart Fulfillment System • Secure Logistics Node', 105, 284, { align: 'center' });

  return doc;
};

import React, { useState, useRef } from 'react';
import { useOrders } from '../context/OrderContext';
import Barcode from 'react-barcode';
import QRCode from 'react-qr-code';
import { generateShippingLabelPDF } from '../utils/pdfGenerator';

const ShippingLabelPreviewModal: React.FC = () => {
    const { activeOrderForLabel, closeLabelPreview } = useOrders();
    const [isDownloading, setIsDownloading] = useState(false);
    const [pdfBlobUrl, setPdfBlobUrl] = useState<string | null>(null);
    const [showPdfPreview, setShowPdfPreview] = useState(false);
    const iframeRef = useRef<HTMLIFrameElement>(null);

    if (!activeOrderForLabel) return null;

    const order = activeOrderForLabel;
    const address = order.shippingAddress || order.shipping_address;
    const isCOD = order.payment_mode === 'Cash on Delivery';

    const vendorName = order.seller_name || order.items[0]?.vendor_name || 'VexoKart Authorized Vendor';
    const vendorId = order.vendor_id || order.items[0]?.vendor_id || 'VX-001';

    const totalAmount = Number(order.total_amount || order.total || 0);
    const subtotal = totalAmount / 1.18;
    const gstAmount = totalAmount - subtotal;

    const handlePrintLocal = () => {
        window.print();
    };

    const handleDownloadAndPreview = async () => {
        setIsDownloading(true);
        try {
            const doc = await generateShippingLabelPDF(order);
            const blob = doc.output('blob');
            const url = URL.createObjectURL(blob);

            setPdfBlobUrl(url);
            setShowPdfPreview(true);

            // On Mobile: Attempt to open in a new tab which usually triggers the native viewer
            const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
            if (isMobile) {
                window.open(url, '_blank');
            }
        } catch (err) {
            console.error("PDF generation failed:", err);
            alert("Failed to generate PDF. Please use the Print option.");
        } finally {
            setIsDownloading(false);
        }
    };

    const handlePrintPdf = () => {
        if (iframeRef.current) {
            iframeRef.current.contentWindow?.print();
        } else {
            window.open(pdfBlobUrl || '', '_blank');
        }
    };

    const handleCloseAll = () => {
        if (pdfBlobUrl) URL.revokeObjectURL(pdfBlobUrl);
        setPdfBlobUrl(null);
        setShowPdfPreview(false);
        closeLabelPreview();
    };

    const handleBackToHtml = () => {
        setShowPdfPreview(false);
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-10 bg-black/90 backdrop-blur-md animate-in fade-in duration-300 no-print">

            {/* PDF PREVIEW OVERLAY */}
            {showPdfPreview && pdfBlobUrl && (
                <div className="absolute inset-0 z-[110] flex flex-col bg-text-main animate-in zoom-in duration-300">
                    <div className="p-4 md:p-6 bg-white border-b flex justify-between items-center shadow-xl">
                        <div>
                            <h2 className="text-sm font-black uppercase tracking-widest text-text-main italic">PDF Visual Manifest</h2>
                            <p className="text-[10px] font-bold text-text-muted uppercase tracking-tighter mt-0.5">Secure Logistics Preview Mode</p>
                        </div>
                        <div className="flex gap-3">
                            <button 
                                onClick={handlePrintPdf}
                                className="px-6 py-2.5 bg-accent text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all flex items-center gap-2"
                            >
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                                Print Now
                            </button>
                            <button 
                                onClick={handleBackToHtml}
                                className="px-6 py-2.5 bg-surface text-text-muted rounded-xl text-[10px] font-black uppercase tracking-widest border border-border transition-all active:scale-95"
                            >
                                Close Preview
                            </button>
