import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
import { NotificationLog, NotificationSettings, Order, User, AppNotification } from '../types.ts';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface NotificationContextType {
  settings: NotificationSettings;
  logs: NotificationLog[];
  inbox: AppNotification[];
  unreadCount: number;
  updateSettings: (settings: Partial<NotificationSettings>) => void;
  notifyOrderUpdate: (order: Order, user: User) => Promise<void>;
  notifyLogin: (user: User) => Promise<void>;
  createAppNotification: (notif: Omit<AppNotification, 'id' | 'created_at' | 'is_read'>) => Promise<void>;
  markAsRead: (logId: number) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  clearLogs: () => void;
  fetchInbox: (user?: User) => Promise<void>;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

const getEnvKey = (key: string) => {
  try {
    return (process as any).env[key];
  } catch {
    return undefined;
  }
};

const DEFAULT_SETTINGS: NotificationSettings = {
  emailEnabled: true,
  smsEnabled: true,
  smtpHost: 'api.sendgrid.com',
  smtpUser: '',
  smtpPass: '',
  emailFrom: 'BICT Computer Education – VexoKart <bictcomputereducation1@gmail.com>',
  smsApiKey: getEnvKey('FAST2SMS_API_KEY') || 'DEMO_KEY_FSTSMS_LIVE',
  smsSenderId: 'VXKART',
  smsTemplateId: '',
  testMode: false,
};

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<NotificationSettings>(() => {
    const local = localStorage.getItem('vexokart-notification-settings');
    const saved = local ? JSON.parse(local) : DEFAULT_SETTINGS;
    return { ...saved, smsApiKey: getEnvKey('FAST2SMS_API_KEY') || saved.smsApiKey };
  });

  const [logs, setLogs] = useState<NotificationLog[]>([]);
  const [inbox, setInbox] = useState<AppNotification[]>([]);

  const unreadCount = inbox.filter(m => !m.is_read).length;

  useEffect(() => {
    localStorage.setItem('vexokart-notification-settings', JSON.stringify(settings));
  }, [settings]);

  const fetchInbox = async (user?: User) => {
    if (!user) return;
    try {
      let query = `role=eq.${user.role}&order=created_at.desc`;

      if (user.role === 'user') {
        query += `&user_id=eq.${user.id}`;
      } else if (user.role === 'vendor') {
        query += `&vendor_id=not.is.null`; 
      }

      const res = await fetch(`${BASE_API_URL}/notifications?${query}`, {
        headers: API_HEADERS
      });

      if (!res.ok) return;
      const data = await res.json();
      if (Array.isArray(data)) {
        setInbox(data);
      }
    } catch (e) {
      console.warn("[Inbox Sync] Failed to fetch notifications from DB.");
    }
  };

  const createAppNotification = async (notif: Omit<AppNotification, 'id' | 'created_at' | 'is_read'>) => {
    try {
      const payload = {
        ...notif,
        is_read: false,
        created_at: new Date().toISOString()
      };

      const res = await fetch(`${BASE_API_URL}/notifications`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        console.error("Failed to insert notification row");
      }
    } catch (e) {
      console.error("Notification DB Write Error:", e);
    }
  };

  const updateSettings = (newSettings: Partial<NotificationSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
  };

  const markAsRead = async (id: number) => {
    try {
      await fetch(`${BASE_API_URL}/notifications?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify({ is_read: true })
      });
      setInbox(prev => prev.map(m => m.id === id ? { ...m, is_read: true } : m));
    } catch (e) {
      console.error("Failed to mark as read", e);
    }
  };

  const markAllAsRead = async () => {
    const unreadIds = inbox.filter(m => !m.is_read).map(m => m.id);
    if (unreadIds.length === 0) return;

    try {
      for (const id of unreadIds) {
        await fetch(`${BASE_API_URL}/notifications?id=eq.${id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ is_read: true })
        });
      }
      setInbox(prev => prev.map(m => ({ ...m, is_read: true })));
    } catch (e) {
      console.error("Failed to mark all as read", e);
    }
  };

  const sendQuickSMS = async (number: string, message: string) => {
    if (!settings.smsEnabled || !number) return { success: false, message: 'SMS Disabled or Number missing' };
    const apiKey = getEnvKey('FAST2SMS_API_KEY') || settings.smsApiKey;
    if (!apiKey || apiKey.includes('DEMO_KEY')) return { success: false, message: 'Invalid API Key' };

    try {
        const response = await fetch('https://www.fast2sms.com/dev/bulkV2', {
          method: 'POST',
          headers: {
            'authorization': apiKey,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ route: 'q', message: message, numbers: number })
        });
        const result = await response.json().catch(() => ({ message: 'Invalid response format' }));
        return result;
    } catch (err: any) {
        return { success: false, message: err.message };
    }
  };

  const notifyOrderUpdate = async (order: Order, user: User) => {
      // Internal notification logic handled via OrderContext and createAppNotification
  };

  const notifyLogin = async (user: User) => {
    try {
        const message = `VexoKart: Login successful for ${user.email}. If this wasn't you, secure your account immediately.`;
        if (settings.testMode) return;
        await sendQuickSMS(user.phone, message);
    } catch (err) {}
  };

  const clearLogs = () => {
    setLogs([]);
  };

  return (
    <NotificationContext.Provider value={{ 
      settings, logs, inbox, unreadCount, updateSettings, 
      notifyOrderUpdate, notifyLogin, createAppNotification, markAsRead, markAllAsRead, clearLogs, fetchInbox
    }}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotifications must be used within NotificationProvider');
  return context;
};

import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
import { Order, OrderStatus, Address, PaymentStatus, Vendor } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS } from "../constants.ts";

interface OrderContextType {
  orders: any[];
  isLoading: boolean;
  isLabelGenerating: boolean;
  activeOrderForLabel: any | null;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  createShipment: (orderId: string, vendorData: any) => Promise<void>;
  generateShippingLabel: (orderId: string) => void;
  closeLabelPreview: () => void;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { fetchInbox } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLabelGenerating, setIsLabelGenerating] = useState(false);

  // IN-APP REACT COMPONENT PREVIEW STATE
  const [activeOrderForLabel, setActiveOrderForLabel] = useState<any | null>(null);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      let selectString = `*,vendor:vendors!vendor_id(*)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) throw new Error("Vendor profile unreachable");
        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
            headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
        });
        if (fallbackRes.ok) {
            const data = await fallbackRes.json();
            processOrders(data);
            return;
        }
        throw new Error("Order fetch failed");
      }

      const data = await res.json();
      processOrders(data);
    } catch (e: any) {
      console.error("[OrderContext] Fetch failed:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => ({
          ...o,
          id: o.id.toString(),
          total: Number(o.total_amount || o.total || 0),
          statusHistory: o.status_history || [],
          qrToken: o.qr_token,
          date: o.created_at,
          seller_name: o.vendor?.store_name || "VexoKart Direct",
          shippingAddress: o.shipping_address || o.shippingaddress || o.address || null,
        }))
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  const generateShippingLabel = (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
      setActiveOrderForLabel(order);
    }
  };

  const closeLabelPreview = () => {
    setActiveOrderForLabel(null);
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required.");
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);
    const addressSnapshot = {
      id: orderData.shippingAddress?.id || Date.now().toString(),
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };
    const rawVendorId = orderData.items[0]?.vendor_id;
    let numericVendorId = null;
    if (rawVendorId && !isNaN(Number(rawVendorId))) numericVendorId = Number(rawVendorId);

    const payload = {
      user_id: Number(user.id),
      vendor_id: numericVendorId,
      items: orderData.items,
      total: Number(orderData.total),
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      shipping_address: addressSnapshot,
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{ status: "Placed", timestamp, actor: "User", note: "Order placed" }],
      created_at: timestamp,
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: "POST",
      headers: { ...API_HEADERS, "Prefer": "return=representation" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error("Order placement failed");
    const result = await res.json();
    refreshOrders();
    return result[0].id.toString();
  };

  const createShipment = async (orderId: string, vendor: any) => {};

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    const history = order?.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { status, status_history: newHistory };
    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: "PATCH",
      headers: { ...API_HEADERS },
      body: JSON.stringify(updatePayload),
    });
    if (res.ok) await refreshOrders();
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Status updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        isLabelGenerating,
        activeOrderForLabel,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        closeLabelPreview,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext missing.");
  return context;
