import React, { useState, useEffect, useMemo } from 'react';
import { Order, OrderStatus, OrderItem } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { useVendors } from '../../context/VendorContext';
import { useOrders } from '../../context/OrderContext';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';

interface VendorAugmentedOrder extends Order {
    vendorItems: OrderItem[];
    vendorSubtotal: number;
}

const VendorOrdersPage: React.FC = () => {
    const { user } = useAuth();
    const { currentVendor, fetchCurrentVendor } = useVendors();
    const { orders, isLoading, updateOrderStatus, refreshOrders } = useOrders();

    const [statusFilter, setStatusFilter] = useState<string>('all');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isShippingModalOpen, setShippingModalOpen] = useState(false);

    useEffect(() => {
        refreshOrders();
        if (user?.id && !currentVendor) {
            fetchCurrentVendor(user.id.toString());
        }
    }, [user, currentVendor]);

    const vendorOrders = useMemo(() => {
        if (!currentVendor) return [];

        return orders.filter(order => {
            const matchesVendorId = Number(order.vendor_id) === Number(currentVendor.id);
            const hasVendorItems = Array.isArray(order.items) && order.items.some(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );
            return matchesVendorId || hasVendorItems;
        }).map(order => {
            const matchedItems = order.items.filter(item => 
                Number(item.vendor_id) === Number(currentVendor.id)
            );
            const vendorSubtotal = matchedItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

            return {
                ...order,
                vendorItems: matchedItems,
                vendorSubtotal: vendorSubtotal
            } as VendorAugmentedOrder;
        }).filter((o): o is VendorAugmentedOrder => {
            if (statusFilter === 'all') return true;
            if (statusFilter === 'pending') return ['Placed', 'Confirmed'].includes(o.status);
            return o.status === statusFilter;
        });
    }, [orders, currentVendor, statusFilter]);

    const handleConfirmOrder = async (orderId: string) => {
        await updateOrderStatus(orderId, 'Confirmed', { note: "Consignment confirmed by merchant node." });
    };

    const handlePacked = async (orderId: string) => {
        await updateOrderStatus(orderId, 'Packed', { note: "Items verified and manifest generated." });
    };

    const handleStatusChange = (order: Order, status: OrderStatus) => {
        if (status === 'Shipped') {
            setSelectedOrder(order);
            setShippingModalOpen(true);
        } else {
            updateOrderStatus(order.id, status);
        }
    };

    const handleShippingSubmit = (courierName: string, trackingId: string) => {
        if (selectedOrder) {
            updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
        }
        setShippingModalOpen(false);
        setSelectedOrder(null);
    };

    const handlePrintLabel = (orderId: string) => {
        window.open(`/#/print/label/${orderId}`, '_blank');
    };

    if (isLoading && vendorOrders.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-20">
                <div className="w-10 h-10 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-text-muted font-black uppercase tracking-widest text-[10px]">Loading orders...</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {isShippingModalOpen && (
                <ShippingDetailsModal
                    onClose={() => setShippingModalOpen(false)}
                    onSubmit={handleShippingSubmit}
                />
            )}

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase">Vendor Orders</h1>
                  <p className="text-text-muted mt-1 text-sm font-medium">Automated fulfillment lifecycle.</p>
                </div>

                <div className="flex bg-surface p-1 rounded-xl border border-border">
                    {['all', 'pending', 'Packed', 'Shipped', 'Delivered'].map(f => (
                        <button
                            key={f}
                            onClick={() => setStatusFilter(f)}
                            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-accent text-white shadow-lg' : 'text-text-muted hover:text-text-secondary'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <GlassmorphicCard>
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-white/5 text-text-muted text-[10px] uppercase font-black tracking-widest">
                                <th className="p-6">Order Reference</th>
                                <th className="p-6 text-center">Settlement</th>
                                <th className="p-6 text-center">Status</th>
                                <th className="p-6 text-right">Workflow Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {vendorOrders.map(order => (
                                <tr key={order.id} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-6">
                                        <p className="text-text-main font-mono font-bold text-base">#{order.id}</p>
                                        <p className="text-[10px] text-text-muted font-bold mt-1 uppercase tracking-tighter">{order.shippingAddress?.fullName || 'Buyer'}</p>
                                    </td>
                                    <td className="p-6 text-center">
                                        <span className="text-text-main font-black text-sm italic">₹{order.vendorSubtotal.toLocaleString()}</span>
                                    </td>
                                    <td className="p-6 text-center">
                                        <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-md border ${
                                            order.status === 'Delivered' ? 'text-green-500 border-green-500/20 bg-green-500/5' : 
                                            order.status === 'Cancelled' ? 'text-red-500 border-red-500/20 bg-red-500/5' : 
                                            'text-blue-400 border-blue-400/20 bg-blue-400/5'
                                        }`}>
                                            {order.status}
                                        </span>
                                    </td>
                                    <td className="p-6 text-right space-x-2 whitespace-nowrap">
                                        {order.status === 'Placed' && (
                                            <button onClick={() => handleConfirmOrder(order.id)} className="bg-accent text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg transition-all hover:scale-105 active:scale-95">Accept Order</button>
                                        )}
                                        {order.status === 'Confirmed' && (
                                            <button 
                                                onClick={() => handlePacked(order.id)} 
                                                className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg transition-all hover:scale-105 active:scale-95"
                                            >
                                                Generate Manifest
                                            </button>
                                        )}
                                        {['Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(order.status) && (
                                            <button 
                                                onClick={() => handlePrintLabel(order.id)}
                                                className="bg-white border border-border text-text-main px-4 py-2 rounded-xl text-[10px] font-black uppercase hover:border-accent transition-all shadow-sm inline-flex items-center gap-2 group"
                                            >
                                                <svg className="w-3.5 h-3.5 text-accent group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                                                Print Label
                                            </button>
                                        )}
                                        {order.status === 'Packed' && (
                                            <button onClick={() => handleStatusChange(order, 'Shipped')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg transition-all hover:scale-105 active:scale-95">Dispatch</button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {vendorOrders.length === 0 && !isLoading && (
                        <div className="p-20 text-center text-text-muted italic font-medium uppercase text-[10px] tracking-widest">
                            Market Node Manifest Empty
                        </div>
                    )}
                </div>
            </GlassmorphicCard>
        </div>
    );
};

export default VendorOrdersPage;

import React, { useState } from 'react';
import { useOrders } from '../../context/OrderContext';
import { Order, OrderStatus } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import OrderStatusHistoryModal from '../../components/admin/OrderStatusHistoryModal';

const ALL_STATUSES: OrderStatus[] = ['Placed', 'Confirmed', 'Packed', 'Shipped', 'Out for Delivery', 'Delivered', 'Cancelled'];

const AdminOrdersPage: React.FC = () => {
  const { orders, updateOrderStatus } = useOrders();
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [isShippingModalOpen, setShippingModalOpen] = useState(false);
  const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

  const handleStatusChange = (order: Order, status: OrderStatus) => {
    if (status === 'Shipped' && !order.awb_code && !order.tracking_id) {
      setSelectedOrder(order);
      setShippingModalOpen(true);
    } else {
      updateOrderStatus(order.id, status);
    }
  };

  const handleShippingSubmit = (courierName: string, trackingId: string) => {
    if (selectedOrder) {
      updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
    }
    setShippingModalOpen(false);
    setSelectedOrder(null);
  };

  const openHistoryModal = (order: Order) => {
    setSelectedOrder(order);
    setHistoryModalOpen(true);
  }

  const handlePrintLabel = (orderId: string) => {
      window.open(`/#/print/label/${orderId}`, '_blank');
  };

  const getStatusColor = (status: OrderStatus) => {
      switch(status) {
          case 'Placed': return 'text-gray-300 bg-gray-700/50 border-gray-600/50';
          case 'Confirmed': return 'text-cyan-400 bg-cyan-900/50 border-cyan-600/50';
          case 'Packed': return 'text-indigo-400 bg-indigo-900/50 border-indigo-600/50';
          case 'Shipped': return 'text-blue-400 bg-blue-900/50 border-blue-600/50';
          case 'Out for Delivery': return 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50';
          case 'Delivered': return 'text-green-400 bg-green-900/50 border-green-600/50';
          case 'Cancelled': return 'text-red-400 bg-red-900/50 border-red-600/50';
          default: return 'text-gray-400 bg-gray-700/50 border-gray-600/50';
      }
  }

  return (
    <div>
      {isShippingModalOpen && selectedOrder && (
        <ShippingDetailsModal
          onClose={() => setShippingModalOpen(false)}
          onSubmit={handleShippingSubmit}
        />
      )}
      {isHistoryModalOpen && selectedOrder && (
        <OrderStatusHistoryModal
          history={selectedOrder.statusHistory || selectedOrder.status_history || []}
          onClose={() => setHistoryModalOpen(false)}
        />
      )}
      <h1 className="text-3xl font-bold text-text-main mb-6">Manage Orders</h1>
      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-gray-700 text-text-muted">
                <th className="p-4 font-semibold">Order ID</th>
                <th className="p-4 font-semibold">Date</th>
                <th className="p-4 font-semibold">Customer</th>
                <th className="p-4 font-semibold">Total</th>
                <th className="p-4 font-semibold">Status</th>
                <th className="p-4 font-semibold">Update Status</th>
                <th className="p-4 font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(order => (
                <tr key={order.id} className="border-b border-gray-800 hover:bg-surface/50">
                  <td className="p-4 text-text-main font-mono">#{order.id}</td>
                  <td className="p-4">{new Date(order.created_at).toLocaleDateString()}</td>
                  <td className="p-4">{order.shippingAddress?.fullName || order.user_id}</td>
                  <td className="p-4 font-semibold">₹{(order.total_amount || order.total || 0).toFixed(2)}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${getStatusColor(order.status)}`}>
                        {order.status}
                    </span>
                  </td>
                  <td className="p-4">
                     <select 
                        value={order.status} 
                        onChange={(e) => handleStatusChange(order, e.target.value as OrderStatus)}
                        className="bg-surface border border-gray-600 rounded-md p-1.5 text-text-main focus:ring-accent focus:border-accent text-xs"
                     >
                        {ALL_STATUSES.map(status => (
                            <option key={status} value={status}>{status}</option>
                        ))}
                    </select>
                  </td>
                   <td className="p-4 space-x-3 whitespace-nowrap">
                    <button onClick={() => openHistoryModal(order)} className="text-accent hover:underline text-xs font-semibold">
                      History
                    </button>
                    {['Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(order.status) && (
                        <button 
                            onClick={() => handlePrintLabel(order.id)}
                            className="text-white bg-indigo-600 px-3 py-1 rounded-md text-xs font-bold hover:bg-indigo-700 transition-colors"
                        >
                            Print Label
                        </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <p className="text-center p-8 text-text-muted">No orders have been placed yet.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminOrdersPage;

