        <div className="flex items-baseline gap-2">
          <span className="text-2xl font-bold text-gray-900 tracking-tight">₹{sellingPrice}</span>
          {discountPercent > 0 && (
            <span className="text-sm text-gray-400 line-through">₹{mrp}</span>
          )}
          <span className="text-sm font-bold text-[#34BE82]">{discountPercent}% off</span>
        </div>

        <div className="flex items-center gap-2">
          <div className="bg-[#E7F7F0] text-[#34BE82] text-[10px] font-bold px-2 py-1 rounded flex items-center gap-1">
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
            {product.rating || '4.0'}
          </div>
          <span className="text-xs text-gray-400 font-medium">{product.review_count || '25'} Reviews</span>
        </div>

        <div className="pt-3 mt-1 border-t border-gray-100">
           <div className="flex items-center gap-2 cursor-pointer active:opacity-60" onClick={() => navigate('/addresses')}>
              <svg className="w-4 h-4 text-[#F43397]" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              <p className="text-[11px] font-bold text-gray-700">
                {defaultAddress 
                   ? `Delivering to ${defaultAddress.city} - ${defaultAddress.zip}` 
                   : 'Add delivery address'}
              </p>
              <svg className="w-3 h-3 text-gray-400 ml-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
           </div>
        </div>

        <div className="pt-2">
          <div className="bg-[#F3FFF9] border border-[#D1F7E6] p-3 rounded-lg flex items-center justify-between">
             <div className="flex items-center gap-2">
                <div className="bg-[#34BE82] p-1 rounded-full"><svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg></div>
                <p className="text-[11px] font-bold text-gray-700">₹{upiPrice} with UPI offer</p>
             </div>
             <p className="text-[10px] font-bold text-[#34BE82]">Applied</p>
          </div>
          <p className="text-[10px] text-gray-400 mt-2 font-medium">Free Delivery • 7-day Easy Returns</p>
        </div>
      </div>

      {/* COLOR SELECTION SECTION */}
      {needsColor && (
        <div id="color-selection" className="mt-2 bg-white p-4 space-y-4 shadow-sm">
          <h3 className="text-sm font-bold text-gray-800">Select Color</h3>
          <div className="flex flex-wrap gap-4">
            {availableColors.map((color, i) => (
              <button
                key={i}
                onClick={() => setSelectedColor(color.value)}
                className={`flex flex-col items-center gap-1 p-1 rounded-xl border-2 transition-all duration-200 ${
                  selectedColor === color.value ? 'border-[#F43397] bg-[#FFF0F7]' : 'border-transparent'
                }`}
              >
                <div className="w-12 h-12 rounded-lg overflow-hidden bg-gray-100">
                  <img src={color.image || 'https://placehold.co/100x100?text=Color'} className="w-full h-full object-cover" alt={color.value} />
                </div>
                <span className="text-[10px] font-bold text-gray-600 uppercase tracking-tighter">{color.value}</span>
              </button>
            ))}
          </div>
          {!selectedColor && (
            <p className="text-[10px] text-[#F43397] font-bold italic animate-pulse">! Please select a color to continue</p>
          )}
        </div>
      )}

      {/* SIZE SELECTION SECTION */}
      {needsSize && (
        <div id="size-selection" className="mt-2 bg-white p-4 space-y-4 shadow-sm">
          <div className="flex justify-between items-center">
            <h3 className="text-sm font-bold text-gray-800">Select Size</h3>
            <button className="text-[#F43397] text-xs font-bold active:opacity-60">Size Chart</button>
          </div>
          <div className="flex flex-wrap gap-3">
            {availableSizes.map((size) => (
              <button
                key={size}
                onClick={() => setSelectedSize(size)}
                className={`min-w-[56px] py-2 px-3 rounded-full text-sm font-bold border transition-all duration-200 ${
                  selectedSize === size
                    ? 'border-[#F43397] bg-[#FFF0F7] text-[#F43397]'
                    : 'border-gray-200 text-gray-600 hover:border-gray-400'
                }`}
              >
                {size}
              </button>
            ))}
          </div>
          {!selectedSize && (
              <p className="text-[10px] text-[#F43397] font-bold italic animate-pulse">! Please select a size to continue</p>
          )}
        </div>
      )}

      {/* QUANTITY SELECTOR */}
      <div className="mt-2 bg-white p-4 flex items-center justify-between shadow-sm">
        <h3 className="text-sm font-bold text-gray-800">Quantity</h3>
        <div className="flex items-center border border-gray-200 rounded-lg overflow-hidden">
          <button 
            onClick={() => setQuantity(q => Math.max(1, q - 1))}
            className="px-4 py-2 bg-gray-50 text-gray-600 font-bold active:bg-gray-200"
          >-</button>
          <span className="px-4 py-2 text-sm font-bold text-gray-800 min-w-[40px] text-center">{quantity}</span>
          <button 
            onClick={() => setQuantity(q => Math.min(product.stock, q + 1))}
            className="px-4 py-2 bg-gray-50 text-gray-600 font-bold active:bg-gray-200"
          >+</button>
        </div>
      </div>

      {/* PRODUCT DETAILS (ACCORDION) */}
      <div className="mt-2 bg-white p-4 shadow-sm">
        <h3 className="text-sm font-bold text-gray-800 mb-4">Product Details</h3>
        <div className="space-y-3">
          {(product.highlights || []).length > 0 ? product.highlights?.map((h, i) => {
            const [label, ...valParts] = h.includes(':') ? h.split(':') : ['Highlight', h];
            const value = valParts.join(':').trim();
            return (
              <div key={i} className="flex text-xs leading-relaxed border-b border-gray-50 pb-2 last:border-0">
                <span className="w-1/3 text-gray-400 font-medium uppercase tracking-tighter">{label.trim()}</span>
                <span className="w-2/3 text-gray-700 font-semibold">{value}</span>
              </div>
            );
          }) : (
            <p className="text-xs text-text-muted italic">No specific highlights provided.</p>
          )}
        </div>

        <div className="mt-4 relative">
          <div 
            className={`text-xs text-gray-500 leading-relaxed whitespace-pre-line overflow-hidden transition-all duration-500 ease-in-out will-change-[max-height] ${
              isDescriptionExpanded ? 'max-h-[2000px]' : 'max-h-[4.8rem]'
            }`}
          >
            {product.description}
          </div>
          {product.description && product.description.length > 120 && (
            <button 
              onClick={() => setIsDescriptionExpanded(!isDescriptionExpanded)}
              className="text-[#F43397] text-xs font-bold mt-2 hover:opacity-80 transition-opacity p-1 -ml-1 active:scale-95"
            >
              {isDescriptionExpanded ? 'Read Less ▲' : 'See More ▼'}
            </button>
          )}
        </div>
      </div>

      {/* SOLD BY SECTION */}
      <div className="mt-2 bg-white p-4 shadow-sm">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-sm font-bold text-gray-800">Shop Information</h3>
          <button className="text-[#F43397] text-xs font-bold active:opacity-60">View Shop</button>
        </div>
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-[#F43397] rounded-full flex items-center justify-center text-white font-black text-xl italic shadow-inner">
            {vendor?.store_name?.[0] || 'V'}
          </div>
          <div className="flex-grow">
            <p className="text-sm font-bold text-gray-800">{vendor?.store_name || 'VexoKart Direct'}</p>
            <div className="flex items-center gap-2 mt-1">
               <div className="bg-[#34BE82] text-white text-[10px] font-bold px-1.5 py-0.5 rounded flex items-center gap-0.5">
                 4.2 <svg className="w-2 h-2" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
               </div>
               <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Top Rated Seller</span>
            </div>
          </div>
        </div>
      </div>

      {/* STICKY BOTTOM BAR */}
      <div className="fixed bottom-0 left-0 right-0 p-3 bg-white flex items-center gap-3 z-[110] shadow-[0_-10px_30px_rgba(0,0,0,0.08)] border-t border-gray-100">
        <button 
          onClick={() => handleAction('cart')}
          className="flex-1 border-2 border-gray-900 bg-white text-gray-900 font-bold uppercase tracking-tight text-sm py-3.5 rounded-lg active:scale-95 transition-all flex items-center justify-center gap-2"
        >
          <CartIcon className="w-4 h-4" />
          Add to Cart
        </button>
        <button 
          onClick={() => handleAction('buy')}
          disabled={isBuyDisabled}
          className={`flex-[1.2] py-4 rounded-lg font-bold uppercase tracking-tight text-sm shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 ${
            !isBuyDisabled 
            ? 'bg-[#F43397] text-white shadow-[#F43397]/20' 
            : 'bg-gray-200 text-gray-400 cursor-not-allowed opacity-80'
          }`}
        >
          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path fillRule="evenodd" d="M10 2a4 4 0 00-4 4v1H5a1 1 0 00-.994.89l-1 9A1 1 0 004 18h12a1 1 0 00.994-1.11l-1-9A1 1 0 0015 7h-1V6a4 4 0 00-4-4zm2 5V6a2 2 0 10-4 0v1h4zm-6 3a1 1 0 112 0 1 1 0 01-2 0zm7-1a1 1 0 100 2 1 1 0 000-2z" clipRule="evenodd" /></svg>
          Buy Now
        </button>
      </div>
    </div>
  );
};

export default ProductDetailPage;

import React, { useEffect, useState } from 'react';
import { useOrders } from '../context/OrderContext.tsx';
import Barcode from 'react-barcode';
import QRCode from 'react-qr-code';
import { generateShippingLabelPDF } from '../utils/pdfGenerator.ts';

const ShippingLabelPreviewModal: React.FC = () => {
    const { activeOrderForLabel, closeLabelPreview } = useOrders();
    const [isDownloading, setIsDownloading] = useState(false);
    const [pdfUrl, setPdfUrl] = useState<string | null>(null);

    // Lock body scroll when modal is open
    useEffect(() => {
        if (activeOrderForLabel) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = '';
        }
        return () => { document.body.style.overflow = ''; };
    }, [activeOrderForLabel]);

    if (!activeOrderForLabel) return null;

    const order = activeOrderForLabel;
    const address = order.shippingAddress || order.shipping_address;
    const isCOD = order.payment_mode === 'Cash on Delivery';

    const vendorName = order.seller_name || order.items[0]?.vendor_name || 'VexoKart Authorized Vendor';

    const totalAmount = Number(order.total_amount || order.total || 0);
    const subtotal = totalAmount / 1.18;
    const gstAmount = totalAmount - subtotal;

    const handleClose = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (pdfUrl) {
            URL.revokeObjectURL(pdfUrl);
            setPdfUrl(null);
        } else {
            closeLabelPreview();
        }
    };

    const handleDownload = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDownloading(true);
        try {
            const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
            const doc = await generateShippingLabelPDF(order);
            const blob = doc.output('blob');
            const url = URL.createObjectURL(blob);

            if (isMobile) {
                // On Mobile: Show PDF in secure internal viewer to avoid permission errors
                setPdfUrl(url);
            } else {
                // On Desktop: Direct download
                const link = document.createElement('a');
                link.href = url;
                link.download = `manifest_order_${order.id}.pdf`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                URL.revokeObjectURL(url);
            }
        } catch (err) {
            console.error("PDF generation failed:", err);
            alert("Failed to generate PDF. Please try printing instead.");
        } finally {
            setIsDownloading(false);
        }
    };

    const handlePrint = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        window.print();
    };

    return (
        <div 
            className="fixed inset-0 z-[200] flex flex-col bg-white animate-in slide-in-from-bottom duration-300"
            onClick={(e) => e.stopPropagation()}
        >
            {/* Header Control Bar */}
            <div className="flex items-center justify-between p-4 border-b border-gray-200 bg-white sticky top-0 z-[210]">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-black rounded-lg flex items-center justify-center text-white">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                    </div>
                    <div>
                        <h2 className="text-sm font-black uppercase tracking-tight italic">
                            {pdfUrl ? 'PDF Preview' : 'Consignment Manifest'}
                        </h2>
                        <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Order #{order.id}</p>
                    </div>
                </div>
                <button 
                    onClick={handleClose}
                    className="p-2 bg-gray-100 rounded-full text-gray-800 hover:bg-gray-200 transition-colors"
                >
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>

            {/* Scrollable Content Area */}
            <div className="flex-grow overflow-y-auto p-4 bg-gray-100 flex flex-col items-center relative">
                {pdfUrl ? (
                    <div className="w-full h-full animate-in fade-in duration-500">
                        <iframe 
                            src={pdfUrl} 
                            className="w-full h-full rounded-xl border-none shadow-inner"
                            title="Label PDF Viewer"
                        />
                    </div>
                ) : (
                    /* The Manifest Visual (Paper Style) */
                    <div className="bg-white w-full max-w-[210mm] shadow-2xl p-6 md:p-10 text-black font-sans border border-gray-300">

                        {/* 1. BRAND HEADER */}
                        <div className="flex justify-between items-start border-b-[2px] border-black pb-4 mb-4">
                            <div>
                                <h1 className="text-3xl font-black italic tracking-tighter leading-none">VexoKart</h1>
                                <p className="text-[9px] font-black uppercase tracking-[0.2em] mt-1 opacity-60">Logistics Hub • Secure Node</p>
                            </div>
                            <div className="text-right">
                                <div className="bg-black text-white px-4 py-1 font-black text-xs uppercase italic inline-block mb-1">
                                    {isCOD ? 'C O D' : 'PREPAID'}
                                </div>
                                <p className="text-[10px] font-black uppercase block">ID: #{order.id}</p>
                            </div>
                        </div>

                        {/* 2. PRIMARY SCANNABLE */}
                        <div className="flex flex-col items-center py-4 border-b border-gray-200 mb-6">
                            <Barcode 
                                value={order.id.toString()} 
                                width={2.5} 
                                height={60} 
                                displayValue={false}
                                margin={0}
                            />
                            <p className="text-xs font-black tracking-[0.5em] mt-2">*{order.id}*</p>
                        </div>

                        {/* 3. ADDRESS GRID */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-0 border-2 border-black mb-6">
                            <div className="border-b-2 md:border-b-0 md:border-r-2 border-black p-4 bg-gray-50/30">
                                <p className="text-[9px] font-black uppercase mb-2 text-gray-400">SHIP FROM (SELLER)</p>
                                <p className="font-black text-sm uppercase italic">{vendorName}</p>
                                <p className="text-[10px] mt-1 font-bold text-gray-700 leading-tight uppercase">
                                    Warehouse Node-A1<br/>
                                    Industrial Estate<br/>
                                    Support: 1800-VEXO-KART
                                </p>
                            </div>
                            <div className="p-4">
                                <p className="text-[9px] font-black uppercase mb-2 text-gray-400">DELIVER TO (CONSIGNEE)</p>
                                <p className="font-black text-base uppercase italic mb-1">{address?.fullName}</p>
                                <p className="text-[11px] font-bold text-gray-800 uppercase leading-snug">
                                    {address?.street}<br/>
                                    {address?.city}, {address?.state}
                                </p>
                                <p className="mt-2 font-black text-sm">PH: {address?.phone}</p>

                                <div className="mt-4 flex justify-center">
                                    <div className="border-2 border-black px-6 py-1 inline-block">
                                        <p className="font-black text-2xl tracking-[0.1em]">{address?.zip}</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* 4. ITEMS LIST */}
                        <div className="border-2 border-black p-3 mb-6">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="text-[9px] font-black uppercase border-b border-black">
                                        <th className="pb-1">DESCRIPTION</th>
                                        <th className="pb-1 text-right w-12">QTY</th>
                                    </tr>
                                </thead>
                                <tbody className="text-[10px] font-bold uppercase">
                                    {order.items.map((item: any, i: number) => (
                                        <tr key={i} className="border-b border-gray-100 last:border-0">
                                            <td className="py-2">
                                                <p className="font-black text-[11px]">{item.name}</p>
                                                <p className="text-[8px] text-gray-400 mt-0.5">SKU: VXK-{item.id}</p>
                                            </td>
                                            <td className="py-2 text-right font-black">{item.quantity}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        {/* 5. PRICING & QR */}
                        <div className="flex flex-col md:flex-row justify-between items-end gap-6 pt-4 border-t border-dashed border-gray-300">
                            <div className="flex flex-col items-center p-2 border border-gray-100 rounded-lg">
                                <QRCode 
                                    size={60}
                                    value={JSON.stringify({ oid: order.id, ph: address?.phone })}
                                    viewBox={`0 0 256 256`}
                                />
                                <p className="text-[7px] font-black uppercase mt-1">Digital Auth</p>
                            </div>

                            <div className="w-full md:w-64">
                                <div className="space-y-1 mb-2">
                                    <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase">
                                        <span>Subtotal</span>
                                        <span>₹{subtotal.toFixed(2)}</span>
                                    </div>
                                    <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase">
                                        <span>GST (18%)</span>
                                        <span>₹{gstAmount.toFixed(2)}</span>
                                    </div>
                                </div>
                                <div className="border-t border-black pt-2 text-right">
                                    <p className="text-[8px] font-black uppercase text-gray-400">Total Payable</p>
                                    <p className="text-3xl font-black italic tracking-tighter leading-none mt-1">
                                        ₹{totalAmount.toLocaleString()}
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* 6. MANIFEST FOOTER */}
                        <div className="mt-8 text-center opacity-30">
                            <p className="text-[7px] font-black uppercase tracking-[0.3em]">
                                VexoKart Systems • Electronic Manifest v5.0 • Verified Protocol
                            </p>
                        </div>
                    </div>
                )}

                {/* Secure Protocol Tip */}
                <div className="mt-10 p-6 text-center text-gray-400 space-y-2 no-print">
                    <p className="text-[9px] font-black uppercase tracking-widest italic">Self-Contained Secure Node</p>
                    <p className="text-[8px] uppercase font-bold max-w-[250px] mx-auto leading-relaxed">
                        This document is rendered locally for protection against unauthorized redirection.
                    </p>
                </div>
            </div>

            {/* Bottom Safe Area Footer */}
            <div className="p-4 bg-white border-t border-gray-200 pb-safe shadow-inner no-print grid grid-cols-2 gap-4">
                <button 
                    onClick={handleDownload}
                    disabled={isDownloading}
                    className="bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                    {isDownloading ? (
                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    ) : (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                    )}
                    Download Label
                </button>
                <button 
                    onClick={handlePrint}
