import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product, Review, Category } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (productData: any) => Promise<void>;
  updateProduct: (productData: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  refreshProducts: (vendorId?: number) => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

const PRODUCT_COLUMNS = '*,category_data:categories(name)';

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshProducts = async (vendorId?: number) => {
    try {
      setIsLoading(true);

      let url = `${BASE_API_URL}/products?select=${PRODUCT_COLUMNS}&order=created_at.desc`;
      if (vendorId && !isNaN(Number(vendorId))) {
          url += `&vendor_id=eq.${vendorId}`;
      }

      const response = await fetch(url, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      if (!response.ok) {
        const errBody = await response.json().catch(() => ({}));
        throw new Error(`Supabase Sync Error: ${errBody.message || response.statusText}`);
      }

      const data = await response.json();

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          // Extra logic to extract metadata from specifications if columns were missing
          const meta = item.specifications || {};
          return {
            ...item,
            id: Number(item.id),
            price: Number(item.price || 0),
            original_price: Number(item.original_price || item.price || 0),
            category: item.category_data?.name || 'General',
            category_id: Number(item.category_id),
            vendor_id: String(item.vendor_id),
            status: item.status || 'approved',
            // Load from meta if not in direct columns
            product_type: meta.vxk_product_type || item.product_type || 'simple',
            allow_cod: meta.vxk_allow_cod !== undefined ? meta.vxk_allow_cod : (item.allow_cod !== undefined ? item.allow_cod : true),
            allow_online: meta.vxk_allow_online !== undefined ? meta.vxk_allow_online : (item.allow_online !== undefined ? item.allow_online : true),
            cash_on_delivery: meta.vxk_allow_cod !== undefined ? meta.vxk_allow_cod : true,
            variants: item.variants || [],
            highlights: item.highlights || [],
            specifications: item.specifications || {}
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error: any) {
      console.error("[ProductSync] Fatal Error:", error.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    const { 
      id, 
      category, 
      category_data, 
      variants, 
      cash_on_delivery, 
      payment_modes, 
      product_type,
      allow_cod,
      allow_online,
      specifications,
      ...dbPayload 
    } = productData;

    // Embed metadata into specifications to bypass schema cache missing columns
    const finalSpecs = {
      ...(specifications || {}),
      vxk_product_type: product_type,
      vxk_allow_cod: allow_cod,
      vxk_allow_online: allow_online
    };

    const finalPayload = {
      ...dbPayload,
      vendor_id: Number(productData.vendor_id),
      category_id: Number(dbPayload.category_id),
      images: Array.isArray(dbPayload.images) ? dbPayload.images : [],
      created_at: new Date().toISOString(),
      status: dbPayload.status || 'approved',
      specifications: finalSpecs,
      variants: variants || []
    };

    try {
      const res = await fetch(`${BASE_API_URL}/products`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(finalPayload)
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || `Database save failed`);
      }

      await refreshProducts(finalPayload.vendor_id);
    } catch (err: any) {
      console.error("[ProductSync] Submission Error:", err);
      throw err;
    }
  };

  const updateProduct = async (product: Product) => {
    const { 
      id, 
      category, 
      category_data, 
      variants, 
      cash_on_delivery, 
      payment_modes, 
      product_type,
      allow_cod,
      allow_online,
      specifications,
      ...dbPayload 
    } = product as any;

    const finalSpecs = {
      ...(specifications || {}),
      vxk_product_type: product_type,
      vxk_allow_cod: allow_cod,
      vxk_allow_online: allow_online
    };

    const finalPayload = {
      ...dbPayload,
      vendor_id: Number(dbPayload.vendor_id),
      category_id: Number(dbPayload.category_id),
      specifications: finalSpecs,
      variants: variants || []
    };

    try {
      const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(finalPayload)
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || "Update failed");
      }
      await refreshProducts(finalPayload.vendor_id);
    } catch (err) {
      console.error("[ProductSync] Update Error:", err);
      throw err;
    }
  };

  const toggleProductStatus = async (id: number) => {
    const product = getProduct(id);
    if (!product) return;
    const newStatus = product.status === 'approved' ? 'disabled' : 'approved';

    try {
      await fetch(`${BASE_API_URL}/products?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS },
        body: JSON.stringify({ status: newStatus })
      });
      await refreshProducts(Number(product.vendor_id));
    } catch (err) {
      console.error("[ProductSync] Status Toggle Error:", err);
    }
  };

  const deleteProduct = async (id: number) => {
    try {
      const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, { 
        method: 'DELETE', 
        headers: API_HEADERS 
      });
      if (res.ok) {
          setProducts(prev => prev.filter(p => p.id !== id));
      }
    } catch (err) {
      console.error("[ProductSync] Delete Error:", err);
    }
  };

  return (
    <ProductContext.Provider value={{ 
      products, isLoading, getProduct, addProduct, updateProduct, deleteProduct, toggleProductStatus, refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts missing provider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import { Product, ProductVariant } from '../../types';
import { useVendors } from '../../context/VendorContext';
import Toast from '../../components/Toast';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import ImageCropperModal from '../../components/ImageCropperModal';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { currentVendor } = useVendors();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'info' });

  const [formData, setFormData] = useState<any>({
    name: '',
    category_id: '', 
    price: 0,
    original_price: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    specifications: {},
    product_type: 'simple',
    allow_cod: true,
    allow_online: true,
    variants: [] as ProductVariant[]
  });

  const [enableSize, setEnableSize] = useState(false);
  const [enableColor, setEnableColor] = useState(false);
  const [highlightsText, setHighlightsText] = useState('');

  const [newVarName, setNewVarName] = useState('');
  const [newVarImage, setNewVarImage] = useState('');
  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [isAddingToVariant, setIsAddingToVariant] = useState(false);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-border rounded-2xl p-4 transition focus:outline-none focus:border-accent focus:ring-4 focus:ring-accent/5 disabled:opacity-50 text-sm font-medium";

  useEffect(() => {
    if (isEditing) {
      const p = getProduct(parseInt(id));
      if (p) {
        setFormData({ 
            ...p, 
            category_id: p.category_id.toString(),
            variants: p.variants || [],
            product_type: p.product_type || 'simple',
            allow_cod: p.allow_cod !== undefined ? p.allow_cod : true,
            allow_online: p.allow_online !== undefined ? p.allow_online : true
        });
        setHighlightsText((p.highlights || []).join('\n'));
        setEnableSize(p.variants?.some(v => v.type === 'size') || false);
        setEnableColor(p.variants?.some(v => v.type === 'color') || false);
      }
    } else if (categories.length > 0) {
      setFormData((prev: any) => ({...prev, category_id: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        const checked = (e.target as any).checked;
        setFormData((prev: any) => {
            const next = { ...prev, [name]: checked };
            // Validation: Must have at least one payment method
            if (!next.allow_cod && !next.allow_online) {
                return prev;
            }
            return next;
        });
    } else {
        setFormData((prev: any) => ({ ...prev, [name]: ['price', 'original_price', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>, forVariant = false) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const urls = files.map(file => URL.createObjectURL(file));
      setIsAddingToVariant(forVariant);
      setCropQueue(urls);
      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    if (isAddingToVariant) {
        setNewVarImage(croppedBase64);
    } else {
        setFormData((prev: any) => ({ 
            ...prev, 
            images: Array.isArray(prev.images) ? [...prev.images, croppedBase64] : [croppedBase64] 
        }));
    }

    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
        setIsAddingToVariant(false);
    }
  };

  const addVariant = (type: 'size' | 'color') => {
    if (!newVarName) return;
    const variant: ProductVariant = {
        type,
        name: type === 'size' ? 'Size' : 'Color',
        value: newVarName,
        image: type === 'color' ? (newVarImage || undefined) : undefined
    };
    setFormData((prev: any) => ({ ...prev, variants: [...(prev.variants || []), variant] }));
    setNewVarName('');
    setNewVarImage('');
  };

  const removeVariant = (idx: number) => {
    setFormData((prev: any) => ({ ...prev, variants: prev.variants.filter((_: any, i: number) => i !== idx) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentVendor) { alert("Auth sync error"); return; }
    if (formData.images.length === 0) { alert("Add at least one image"); return; }

    setIsSubmitting(true);
    try {
        const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);

        // Filter variants based on current toggles if Variant Product
        let finalVariants = formData.variants;
        if (formData.product_type === 'simple') {
            finalVariants = [];
        } else {
            finalVariants = formData.variants.filter((v: ProductVariant) => 
                (v.type === 'size' && enableSize) || (v.type === 'color' && enableColor)
            );
        }

        const payload = { 
            ...formData,
            highlights: finalHighlights,
            variants: finalVariants,
            vendor_id: String(currentVendor.id), 
            status: 'approved',
        };

        if (isEditing) {
            await updateProduct({ ...payload, id: parseInt(id) } as any);
        } else {
            await addProduct(payload);
        }

        setToast({ show: true, message: 'Saved Successfully', type: 'success' });
        setTimeout(() => navigate('/vendor/products'), 1000);
    } catch (err: any) {
        alert(`Fail: ${err.message}`);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="pb-24 animate-in fade-in duration-300">
      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            onCropComplete={handleCropComplete}
            onCancel={() => { setCropQueue([]); setIsAddingToVariant(false); }}
            title={isAddingToVariant ? "Variant Photo" : "Product Vision"}
          />
      )}

      <div className="sticky top-0 z-40 bg-[#F8F9FA]/80 backdrop-blur-md pb-4 pt-1 mb-6">
          <div className="flex items-center gap-3">
              <button onClick={() => navigate('/vendor/products')} className="p-2 -ml-2">
                  <ChevronLeftIcon className="w-6 h-6 text-gray-800" />
              </button>
              <h1 className="text-xl font-black text-gray-900 italic uppercase tracking-tighter">
                {isEditing ? 'Edit Listing' : 'Add Product'}
              </h1>
          </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 px-1">
        {/* Core Info */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-5">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Listing Intelligence</h2>
            <div>
              <label className="text-[9px] font-black uppercase text-gray-500 ml-2">Product Title</label>
              <input type="text" name="name" value={formData.name} onChange={handleChange} required placeholder="What are you selling?" className={inputClasses} />
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[9px] font-black uppercase text-gray-500 ml-2">Category</label>
                  <select name="category_id" value={formData.category_id} onChange={handleChange} className={inputClasses}>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[9px] font-black uppercase text-gray-500 ml-2">Available Stock</label>
                  <input type="number" name="stock" value={formData.stock} onChange={handleChange} required className={inputClasses} />
                </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[9px] font-black uppercase text-accent ml-2">Selling Price (₹)</label>
                  <input type="number" name="price" value={formData.price} onChange={handleChange} required className={`${inputClasses} border-accent/20 bg-accent/5`} />
                </div>
                <div>
                  <label className="text-[9px] font-black uppercase text-gray-500 ml-2">MRP / Market Price</label>
                  <input type="number" name="original_price" value={formData.original_price} onChange={handleChange} className={inputClasses} />
                </div>
            </div>
        </div>

        {/* Product Type Selection */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Product Architecture</h2>
            <div className="grid grid-cols-2 gap-3">
                <button 
                    type="button"
                    onClick={() => setFormData((p:any) => ({...p, product_type: 'simple'}))}
                    className={`py-4 rounded-2xl border-2 flex flex-col items-center justify-center transition-all ${formData.product_type === 'simple' ? 'border-accent bg-accent/5 text-accent' : 'border-gray-100 text-gray-400'}`}
                >
                    <svg className="w-6 h-6 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
                    <span className="text-[10px] font-black uppercase">Simple Product</span>
                </button>
                <button 
                    type="button"
                    onClick={() => setFormData((p:any) => ({...p, product_type: 'variant'}))}
                    className={`py-4 rounded-2xl border-2 flex flex-col items-center justify-center transition-all ${formData.product_type === 'variant' ? 'border-accent bg-accent/5 text-accent' : 'border-gray-100 text-gray-400'}`}
                >
                    <svg className="w-6 h-6 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                    <span className="text-[10px] font-black uppercase">Variant Product</span>
                </button>
            </div>

            {formData.product_type === 'variant' && (
                <div className="pt-4 space-y-6 animate-in slide-in-from-top-2 duration-300">
                    <div className="flex gap-4">
                        <label className="flex items-center gap-2 cursor-pointer group">
                            <input type="checkbox" checked={enableSize} onChange={(e) => setEnableSize(e.target.checked)} className="w-5 h-5 rounded text-[#F43397] focus:ring-[#F43397] border-gray-200" />
                            <span className="text-[10px] font-black uppercase text-gray-600">Enable Sizes</span>
                        </label>
                        <label className="flex items-center gap-2 cursor-pointer group">
                            <input type="checkbox" checked={enableColor} onChange={(e) => setEnableColor(e.target.checked)} className="w-5 h-5 rounded text-[#F43397] focus:ring-[#F43397] border-gray-200" />
                            <span className="text-[10px] font-black uppercase text-gray-600">Enable Colors</span>
                        </label>
                    </div>

                    {(enableSize || enableColor) && (
                        <div className="space-y-4">
                            <div className="flex gap-2">
                                <input 
                                    type="text" 
                                    value={newVarName} 
                                    onChange={(e) => setNewVarName(e.target.value)}
                                    placeholder={enableSize && !enableColor ? "Size (XL, 42)" : "Color Name (Red, Blue)"}
                                    className="flex-grow bg-surface border border-gray-100 rounded-xl p-3 text-xs font-bold uppercase"
                                />
                                <button 
                                    type="button" 
                                    onClick={() => addVariant(enableSize ? 'size' : 'color')}
                                    className="bg-gray-900 text-white px-4 rounded-xl text-[9px] font-black uppercase"
                                >Add</button>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                {formData.variants.map((v: ProductVariant, idx: number) => (
                                    <div key={idx} className="bg-gray-50 border border-gray-100 px-3 py-1.5 rounded-full flex items-center gap-2">
                                        <span className="text-[8px] font-black uppercase text-gray-400">{v.type}:</span>
                                        <span className="text-[10px] font-black uppercase text-gray-900">{v.value}</span>
                                        <button type="button" onClick={() => removeVariant(idx)} className="text-red-400 hover:text-red-600 font-bold">&times;</button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>

        {/* Media */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Visual Discovery</h2>
            <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
                {formData.images.map((img: string, i: number) => (
                    <div key={i} className="w-24 h-24 rounded-2xl overflow-hidden border border-gray-100 shrink-0 relative group">
                        <img src={img} className="w-full h-full object-cover" alt="" />
                        <button type="button" onClick={() => setFormData((p: any) => ({ ...p, images: p.images.filter((_: any, idx: number) => idx !== i) }))} className="absolute top-1 right-1 bg-red-500 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs opacity-0 group-hover:opacity-100 transition-opacity font-bold shadow-md">&times;</button>
                    </div>
                ))}
                <label className="w-24 h-24 rounded-2xl border-2 border-dashed border-gray-100 flex flex-col items-center justify-center shrink-0 cursor-pointer bg-gray-50 hover:border-accent/30 transition-all">
                    <input type="file" multiple accept="image/*" onChange={(e) => handleImageChange(e, false)} className="hidden" />
                    <svg className="w-6 h-6 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                    <span className="text-[8px] font-black text-gray-400 uppercase mt-1">Add Media</span>
                </label>
            </div>
        </div>

        {/* Narrative */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Narrative & Highlights</h2>
            <textarea name="description" value={formData.description} onChange={handleChange} rows={4} placeholder="Tell your customers about the magic of this product..." className={inputClasses}></textarea>
            <textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} rows={3} placeholder="Premium Quality (New Line per highlight)" className={inputClasses}></textarea>
        </div>

        {/* Logistics & Payment Control */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Financial Protocol</h2>

            <div className="space-y-3">
                <div className={`p-4 rounded-3xl border flex items-center justify-between transition-colors ${formData.allow_cod ? 'bg-green-50 border-green-100' : 'bg-gray-50 border-gray-100 grayscale'}`}>
                    <div>
                        <p className="text-xs font-black text-gray-800 uppercase italic">Cash on Delivery</p>
                        <p className="text-[9px] text-gray-500 font-bold uppercase mt-1 tracking-tighter">Allow buyers to pay at doorstep</p>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" name="allow_cod" checked={formData.allow_cod} onChange={handleChange} className="sr-only peer" />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-accent"></div>
                    </label>
                </div>

                <div className={`p-4 rounded-3xl border flex items-center justify-between transition-colors ${formData.allow_online ? 'bg-blue-50 border-blue-100' : 'bg-gray-50 border-gray-100 grayscale'}`}>
                    <div>
                        <p className="text-xs font-black text-gray-800 uppercase italic">Online Payment</p>
                        <p className="text-[9px] text-gray-500 font-bold uppercase mt-1 tracking-tighter">Enable UPI, Cards & Netbanking</p>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" name="allow_online" checked={formData.allow_online} onChange={handleChange} className="sr-only peer" />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-accent"></div>
                    </label>
                </div>
            </div>
            <p className="text-[8px] text-gray-400 text-center uppercase font-bold">* At least one payment method must remain active</p>
        </div>

        <button 
          type="submit" 
          disabled={isSubmitting} 
          className="w-full bg-[#F43397] text-white py-5 rounded-[2rem] font-black uppercase tracking-widest text-sm shadow-xl shadow-[#F43397]/30 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSubmitting ? 'ESTABLISHING CONNECTION...' : (isEditing ? 'UPDATE MANIFEST' : 'PUBLISH TO MARKET')}
        </button>
      </form>
    </div>
  );
};

export default VendorProductFormPage;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useProducts } from '../hooks/useProducts';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useRecentlyViewed } from '../context/RecentlyViewedContext';
import { useVendors } from '../context/VendorContext';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { HeartIcon } from '../components/icons/HeartIcon';
import { SearchIcon } from '../components/icons/SearchIcon';
import { CartIcon } from '../components/icons/CartIcon';
import Toast from '../components/Toast';

const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { getProduct } = useProducts();
  const { addToCart, cartCount } = useCart();
  const { isAuthenticated, user, addToWishlist, removeFromWishlist, isInWishlist } = useAuth();
  const { addRecentlyViewed } = useRecentlyViewed();
  const { getVendorById } = useVendors();

  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [selectedSize, setSelectedSize] = useState<string>('');
  const [selectedColor, setSelectedColor] = useState<string>('');
  const [quantity, setQuantity] = useState(1);
  const [showAddedToast, setShowAddedToast] = useState(false);
  const [isWishlistAnimating, setIsWishlistAnimating] = useState(false);
  const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);

  // Swipe logic states
  const [touchStart, setTouchStart] = useState({ x: 0, y: 0 });
  const [touchEnd, setTouchEnd] = useState({ x: 0, y: 0 });
  const [isSwiping, setIsSwiping] = useState(false);
  const [swipeOffset, setSwipeOffset] = useState(0);
  const sliderRef = useRef<HTMLDivElement>(null);

  const productId = parseInt(id || '');
  const product = getProduct(productId);
  const vendor = product ? getVendorById(product.vendor_id) : null;

  const defaultAddress = user?.addresses?.[0];

  const availableSizes = useMemo(() => 
    product?.variants?.filter(v => v.type === 'size').map(v => v.value) || [], 
    [product]
  );

  const availableColors = useMemo(() => 
    product?.variants?.filter(v => v.type === 'color') || [], 
    [product]
  );

  // STRICT RULE: Only show if vendor enabled and items exist
  const showSizeSelector = product?.product_type === 'variant' && availableSizes.length > 0;
  const showColorSelector = product?.product_type === 'variant' && availableColors.length > 0;

  const needsSize = showSizeSelector;
  const needsColor = showColorSelector;

  useEffect(() => {
    if (product && isAuthenticated) {
      addRecentlyViewed(product.id);
    }
  }, [product?.id, isAuthenticated]);

  const displayImages = useMemo(() => {
    if (!product) return ['https://placehold.co/600x600/F8F9FA/A0A0A0?text=VexoKart'];
    return product.images.length > 0 ? product.images : ['https://placehold.co/600x600/F8F9FA/A0A0A0?text=VexoKart'];
  }, [product]);

  if (!product) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-white">
        <div className="w-10 h-10 border-4 border-accent border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  const isWishlisted = isInWishlist(product.id);
  const mrp = Number(product.original_price || product.price);
  const sellingPrice = Number(product.price);
  const discountPercent = mrp > sellingPrice ? Math.round(((mrp - sellingPrice) / mrp) * 100) : 0;
  const upiPrice = Math.floor(sellingPrice * 0.98);

  const allowCod = product.allow_cod !== undefined ? product.allow_cod : true;
  const allowOnline = product.allow_online !== undefined ? product.allow_online : true;

  // Swipe Handlers
  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchStart({ x: e.targetTouches[0].clientX, y: e.targetTouches[0].clientY });
    setTouchEnd({ x: e.targetTouches[0].clientX, y: e.targetTouches[0].clientY });
    setIsSwiping(true);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    const currentX = e.targetTouches[0].clientX;
    const currentY = e.targetTouches[0].clientY;

    const diffX = touchStart.x - currentX;
    const diffY = touchStart.y - currentY;

    if (Math.abs(diffX) > Math.abs(diffY)) {
      if (e.cancelable) e.preventDefault();
      setSwipeOffset(diffX);
    }

    setTouchEnd({ x: currentX, y: currentY });
  };

  const handleTouchEnd = () => {
    setIsSwiping(false);
    const minSwipeDistance = 50;
    const diffX = touchStart.x - touchEnd.x;
    const diffY = touchStart.y - touchEnd.y;

    if (Math.abs(diffX) > Math.abs(diffY)) {
      if (diffX > minSwipeDistance && currentImageIndex < displayImages.length - 1) {
        setCurrentImageIndex(prev => prev + 1);
      } else if (diffX < -minSwipeDistance && currentImageIndex > 0) {
        setCurrentImageIndex(prev => prev - 1);
      }
    }
    setSwipeOffset(0);
  };

  const handleToggleWishlist = (e: React.MouseEvent) => {
    e.preventDefault();
    if (!isAuthenticated) return navigate('/login');
    setIsWishlistAnimating(true);
    isWishlisted ? removeFromWishlist(product.id) : addToWishlist(product.id);
    setTimeout(() => setIsWishlistAnimating(false), 500);
  };

  const handleAction = (type: 'cart' | 'buy') => {
    if (needsSize && !selectedSize) {
      const el = document.getElementById('size-selection');
      el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    if (needsColor && !selectedColor) {
      const el = document.getElementById('color-selection');
      el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }

    addToCart({ 
      ...product, 
      selectedSize: needsSize ? selectedSize : undefined, 
      selectedColor: needsColor ? selectedColor : undefined,
      quantity 
    } as any);

    if (type === 'cart') {
      setShowAddedToast(true);
    } else {
      navigate('/checkout');
    }
  };

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    (e.target as HTMLImageElement).src = 'https://placehold.co/600x600/F8F9FA/A0A0A0?text=Product+Image';
  };

  const isBuyDisabled = (needsSize && !selectedSize) || (needsColor && !selectedColor);

  return (
    <div className="min-h-screen bg-[#F9F9F9] pb-32 font-sans select-none overflow-x-hidden touch-pan-y">
      <Toast message="Added to Cart" isVisible={showAddedToast} onClose={() => setShowAddedToast(false)} />

      {/* HEADER */}
      <div className="sticky top-0 z-[100] bg-white border-b border-gray-100 px-4 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate(-1)} className="p-1 active:scale-90 transition-transform">
            <ChevronLeftIcon className="w-6 h-6 text-gray-800" />
          </button>
        </div>
        <div className="flex items-center gap-5">
          <SearchIcon className="w-6 h-6 text-gray-700" onClick={() => navigate('/products')} />
          <div className="relative cursor-pointer" onClick={handleToggleWishlist}>
            <HeartIcon 
              className={`w-6 h-6 transition-all duration-300 ${isWishlisted ? 'text-[#F43397] fill-[#F43397]' : 'text-gray-700'} ${isWishlistAnimating ? 'scale-125' : ''}`} 
            />
          </div>
          <Link to="/cart" className="relative p-1">
            <CartIcon className="w-6 h-6 text-gray-700" />
            {cartCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-[#F43397] text-white text-[9px] font-bold px-1.5 rounded-full border border-white">
                {cartCount}
              </span>
            )}
          </Link>
        </div>
      </div>

      {/* MOBILE-FIRST IMAGE SLIDER */}
      <div 
        className="relative w-full bg-white aspect-[4/5] overflow-hidden touch-pan-y"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        <div 
          ref={sliderRef}
          className={`flex h-full will-change-transform ${!isSwiping ? 'transition-transform duration-300 ease-out' : ''}`}
          style={{ 
            transform: `translateX(calc(-${currentImageIndex * 100}% - ${swipeOffset}px))`,
          }}
        >
          {displayImages.map((img, idx) => (
            <div key={idx} className="w-full h-full flex-shrink-0 flex items-center justify-center">
              <img 
                src={img} 
                className="w-full h-full object-contain pointer-events-none" 
                alt={`${product.name} view ${idx + 1}`} 
                onError={handleImageError}
                loading={idx === 0 ? "eager" : "lazy"}
              />
            </div>
          ))}
        </div>

        <div className="absolute bottom-4 right-4 bg-black/60 text-white text-[10px] font-black px-3 py-1 rounded-full backdrop-blur-sm tracking-widest">
          {currentImageIndex + 1}/{displayImages.length}
        </div>

        <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-1.5 pointer-events-none">
          {displayImages.map((_, i) => (
            <div 
              key={i} 
              className={`h-1.5 rounded-full transition-all duration-300 ${currentImageIndex === i ? 'w-5 bg-[#F43397]' : 'w-1.5 bg-gray-300/80'}`}
            />
          ))}
        </div>
      </div>

      {/* PRODUCT CORE INFO */}
      <div className="bg-white p-4 space-y-3 shadow-sm">
        <div className="flex justify-between items-start gap-4">
          <h1 className="text-base font-medium text-gray-600 leading-snug line-clamp-2">
            {product.name}
          </h1>
          <button onClick={() => navigator.share?.({ title: product.name, url: window.location.href })} className="p-2 bg-gray-50 rounded-full active:bg-gray-100">
             <svg className="w-5 h-5 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
          </button>
        </div>

        <div className="flex items-baseline gap-2">
          <span className="text-2xl font-bold text-gray-900 tracking-tight">₹{sellingPrice}</span>
          {discountPercent > 0 && (
            <span className="text-sm text-gray-400 line-through">₹{mrp}</span>
          )}
          <span className="text-sm font-bold text-[#34BE82]">{discountPercent}% off</span>
        </div>

        <div className="flex items-center gap-2">
          <div className="bg-[#E7F7F0] text-[#34BE82] text-[10px] font-bold px-2 py-1 rounded flex items-center gap-1">
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
            {product.rating || '4.0'}
          </div>
          <span className="text-xs text-gray-400 font-medium">{product.review_count || '25'} Reviews</span>
        </div>

        {/* PAYMENT BADGES */}
        <div className="flex flex-wrap gap-2 pt-1">
            {allowCod && allowOnline && (
                <div className="bg-gray-100 px-2 py-1 rounded flex items-center gap-1.5 border border-gray-200">
                    <span className="text-[9px] font-black text-gray-600 uppercase tracking-tighter">COD Available</span>
                </div>
            )}
            {!allowCod && (
                <div className="bg-blue-50 px-2 py-1 rounded flex items-center gap-1.5 border border-blue-100">
                    <svg className="w-3 h-3 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" /></svg>
                    <span className="text-[9px] font-black text-blue-600 uppercase tracking-tighter">Online Payment Only</span>
                </div>
            )}
            {!allowOnline && (
                <div className="bg-orange-50 px-2 py-1 rounded flex items-center gap-1.5 border border-orange-100">
                    <svg className="w-3 h-3 text-orange-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
                    <span className="text-[9px] font-black text-orange-600 uppercase tracking-tighter">Pay at Doorstep Only</span>
                </div>
            )}
        </div>

        <div className="pt-3 mt-1 border-t border-gray-100">
           <div className="flex items-center gap-2 cursor-pointer active:opacity-60" onClick={() => navigate('/addresses')}>
              <svg className="w-4 h-4 text-[#F43397]" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              <p className="text-[11px] font-bold text-gray-700 truncate max-w-[250px]">
                {defaultAddress 
                   ? `Delivering to ${defaultAddress.city} - ${defaultAddress.zip}` 
                   : 'Add delivery address'}
              </p>
              <svg className="w-3 h-3 text-gray-400 ml-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
           </div>
        </div>

        {allowOnline && (
            <div className="pt-2">
                <div className="bg-[#F3FFF9] border border-[#D1F7E6] p-3 rounded-lg flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="bg-[#34BE82] p-1 rounded-full"><svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg></div>
                        <p className="text-[11px] font-bold text-gray-700">₹{upiPrice} with UPI offer</p>
                    </div>
                    <p className="text-[10px] font-bold text-[#34BE82]">Applied</p>
                </div>
            </div>
        )}
      </div>

      {/* COLOR SELECTION SECTION */}
      {showColorSelector && (
        <div id="color-selection" className="mt-2 bg-white p-4 space-y-4 shadow-sm animate-in slide-in-from-top-2 duration-300">
          <h3 className="text-sm font-bold text-gray-800">Select Color</h3>
          <div className="flex flex-wrap gap-4">
            {availableColors.map((color, i) => (
              <button
                key={i}
                onClick={() => setSelectedColor(color.value)}
                className={`flex flex-col items-center gap-1 p-1 rounded-xl border-2 transition-all duration-200 ${
                  selectedColor === color.value ? 'border-[#F43397] bg-[#FFF0F7]' : 'border-transparent'
                }`}
              >
                <div className="w-12 h-12 rounded-lg overflow-hidden bg-gray-100">
                  <img src={color.image || 'https://placehold.co/100x100?text=Color'} className="w-full h-full object-cover" alt={color.value} />
                </div>
                <span className="text-[10px] font-bold text-gray-600 uppercase tracking-tighter">{color.value}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* SIZE SELECTION SECTION */}
      {showSizeSelector && (
        <div id="size-selection" className="mt-2 bg-white p-4 space-y-4 shadow-sm animate-in slide-in-from-top-2 duration-300">
          <div className="flex justify-between items-center">
            <h3 className="text-sm font-bold text-gray-800">Select Size</h3>
            <button className="text-[#F43397] text-xs font-bold active:opacity-60">Size Chart</button>
          </div>
          <div className="flex flex-wrap gap-3">
            {availableSizes.map((size) => (
              <button
                key={size}
                onClick={() => setSelectedSize(size)}
                className={`min-w-[56px] py-2 px-3 rounded-full text-sm font-bold border transition-all duration-200 ${
                  selectedSize === size
                    ? 'border-[#F43397] bg-[#FFF0F7] text-[#F43397]'
                    : 'border-gray-200 text-gray-600 hover:border-gray-400'
                }`}
              >
                {size}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* QUANTITY SELECTOR */}
      <div className="mt-2 bg-white p-4 flex items-center justify-between shadow-sm">
        <h3 className="text-sm font-bold text-gray-800">Quantity</h3>
        <div className="flex items-center border border-gray-200 rounded-lg overflow-hidden">
          <button 
            onClick={() => setQuantity(q => Math.max(1, q - 1))}
            className="px-4 py-2 bg-gray-50 text-gray-600 font-bold active:bg-gray-200"
          >-</button>
          <span className="px-4 py-2 text-sm font-bold text-gray-800 min-w-[40px] text-center">{quantity}</span>
          <button 
            onClick={() => setQuantity(q => Math.min(product.stock, q + 1))}
            className="px-4 py-2 bg-gray-50 text-gray-600 font-bold active:bg-gray-200"
          >+</button>
        </div>
      </div>

      {/* PRODUCT DETAILS */}
      <div className="mt-2 bg-white p-4 shadow-sm">
        <h3 className="text-sm font-bold text-gray-800 mb-4">Product Details</h3>
        <div className="space-y-3">
          {(product.highlights || []).length > 0 ? product.highlights?.map((h, i) => {
            const [label, ...valParts] = h.includes(':') ? h.split(':') : ['Highlight', h];
            const value = valParts.join(':').trim();
