            </div>
            <div className="w-full h-2 bg-gray-50 rounded-full overflow-hidden">
                <div 
                    className={`h-full ${color} transition-all duration-1000 ease-out`} 
                    style={{ width: `${(value / max) * 100}%` }}
                ></div>
            </div>
        </div>
