                        </div>
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-500 mb-2">Average Order Value</p>
                        <h4 className="text-4xl font-black italic tracking-tighter">₹{metrics.aov.toLocaleString()}</h4>
