import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import { ProductVariant } from '../../types';
import { useVendors } from '../../context/VendorContext';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import ImageCropperModal from '../../components/ImageCropperModal';

const VendorProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { currentVendor } = useVendors();

  const isEditing = Boolean(id);

  const [isInitialized, setIsInitialized] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [enableSize, setEnableSize] = useState(false);
  const [enableColor, setEnableColor] = useState(false);

  const [highlightsText, setHighlightsText] = useState('');
  const [newVarName, setNewVarName] = useState('');
  const [newVarImage, setNewVarImage] = useState('');

  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [cropIndex, setCropIndex] = useState(0);
  const [isVariantCrop, setIsVariantCrop] = useState(false);

  const [formData, setFormData] = useState<any>({
    name: '',
    category_id: '',
    price: 0,
    original_price: 0,
    images: [],
    description: '',
    highlights: [],
    stock: 10,
    product_type: 'simple',
    is_cod_enabled: false,
    is_online_enabled: false,
    variants: []
  });

  /* ================= INITIAL LOAD ================= */
  useEffect(() => {
    if (isInitialized) return;

    if (isEditing) {
      const p = getProduct(Number(id));
      if (p) {
        setFormData({
          ...p,
          category_id: String(p.category_id),
          is_cod_enabled: Boolean(p.is_cod_enabled),
          is_online_enabled: Boolean(p.is_online_enabled),
          variants: p.variants || []
        });
        setHighlightsText((p.highlights || []).join('\n'));
        setEnableSize(p.variants?.some((v: ProductVariant) => v.type === 'size') || false);
        setEnableColor(p.variants?.some((v: ProductVariant) => v.type === 'color') || false);
        setIsInitialized(true);
      }
    } else if (categories.length > 0) {
      setFormData((prev: any) => ({
        ...prev,
        category_id: String(categories[0].id)
      }));
      setIsInitialized(true);
    }
  }, [id, isEditing, categories, getProduct, isInitialized]);

  /* ================= CLEAN VARIANTS WHEN TOGGLED ================= */
  useEffect(() => {
    setFormData((prev: any) => ({
      ...prev,
      variants: prev.variants.filter((v: ProductVariant) => {
        if (v.type === 'size' && !enableSize) return false;
        if (v.type === 'color' && !enableColor) return false;
        return true;
      })
    }));
  }, [enableSize, enableColor]);

  /* ================= SIMPLE PRODUCT RESET ================= */
  useEffect(() => {
    if (formData.product_type === 'simple') {
      setEnableSize(false);
      setEnableColor(false);
      setFormData((prev: any) => ({ ...prev, variants: [] }));
    }
  }, [formData.product_type]);

  /* ================= HANDLERS ================= */
  const handleChange = (e: any) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev: any) => ({
      ...prev,
      [name]:
        type === 'checkbox'
          ? checked
          : ['price', 'original_price', 'stock'].includes(name)
          ? Number(value)
          : value
    }));
  };

  const handleImageChange = (e: any, variant = false) => {
    const files = Array.from(e.target.files || []);
    if (!files.length) return;
    setIsVariantCrop(variant);
    setCropQueue(files.map((f: any) => URL.createObjectURL(f)));
    setCropIndex(0);
  };

  const handleCropComplete = (base64: string) => {
    if (isVariantCrop) {
      setNewVarImage(base64);
    } else {
      setFormData((prev: any) => ({
        ...prev,
        images: [...prev.images, base64]
      }));
    }
    if (cropIndex < cropQueue.length - 1) {
      setCropIndex(cropIndex + 1);
    } else {
      setCropQueue([]);
      setIsVariantCrop(false);
    }
  };

  const addVariant = (type: 'size' | 'color') => {
    if (!newVarName) return;
    setFormData((prev: any) => ({
      ...prev,
      variants: [
        ...prev.variants,
        {
          type,
          name: type === 'size' ? 'Size' : 'Color',
          value: newVarName,
          image: type === 'color' ? newVarImage : undefined
        }
      ]
    }));
    setNewVarName('');
    setNewVarImage('');
  };

  const removeVariant = (i: number) => {
    setFormData((prev: any) => ({
      ...prev,
      variants: prev.variants.filter((_: any, idx: number) => idx !== i)
    }));
  };

  /* ================= SUBMIT ================= */
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!currentVendor) return alert('Vendor not found');
    if (!formData.images.length) return alert('Add at least one image');
    if (!formData.is_cod_enabled && !formData.is_online_enabled)
      return alert('Select at least one payment method');

    setIsSubmitting(true);

    const payload = {
      ...formData,
      vendor_id: currentVendor.id,
      highlights: highlightsText.split('\n').filter(Boolean),
      status: 'approved'
    };

    try {
      if (isEditing) {
        await updateProduct({ ...payload, id: Number(id) });
      } else {
        await addProduct(payload);
      }
      navigate('/vendor/products');
    } catch (err: any) {
      alert(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  /* ================= UI ================= */
  return (
    <div className="pb-24">
      {cropQueue.length > 0 && (
        <ImageCropperModal
          image={cropQueue[cropIndex]}
          onCropComplete={handleCropComplete}
          onCancel={() => setCropQueue([])}
          title="Crop Image"
        />
      )}

      <div className="flex items-center gap-3 mb-6">
        <button onClick={() => navigate('/vendor/products')}>
          <ChevronLeftIcon />
        </button>
        <h1 className="text-xl font-bold">
          {isEditing ? 'Edit Product' : 'Add Product'}
        </h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <input name="name" value={formData.name} onChange={handleChange} placeholder="Product name" />
        <textarea name="description" value={formData.description} onChange={handleChange} />
        <textarea value={highlightsText} onChange={(e) => setHighlightsText(e.target.value)} />

        <label>
          <input type="checkbox" name="is_cod_enabled" checked={formData.is_cod_enabled} onChange={handleChange} />
          Cash on Delivery
        </label>

        <label>
          <input type="checkbox" name="is_online_enabled" checked={formData.is_online_enabled} onChange={handleChange} />
          Online Payment
        </label>

        <button disabled={isSubmitting} type="submit">
          {isSubmitting ? 'Saving...' : 'Save Product'}
        </button>
      </form>
    </div>
  );
};

export default VendorProductFormPage;

