                        </div>
                        <div className="p-2">
                            <p className="text-[10px] font-black text-gray-900 truncate">₹{p.price}</p>
                        </div>
                    </div>
                ))}
            </div>
        </section>
      )}

      {/* 4. PRODUCT FEED */}
