}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { fetchInbox, createAppNotification } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [activeOrderForLabel, setActiveOrderForLabel] = useState<any | null>(null);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      // Simplified join syntax for better compatibility
      let selectString = `*,vendor:vendors(*)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        filter += `&user_id=eq.${user.id}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) {
           const errText = await vRes.text();
           console.error("[OrderContext] Vendor profile fetch failed:", errText);
           throw new Error("Vendor profile unreachable");
        }
        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({ message: res.statusText }));
        console.warn("[OrderContext] Primary fetch failed, trying fallback. Error:", errData.message);

        const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
            headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
        });

        if (fallbackRes.ok) {
            const data = await fallbackRes.json();
            processOrders(data);
            return;
        } else {
            const fallbackErr = await fallbackRes.json().catch(() => ({ message: fallbackRes.statusText }));
            console.error("[OrderContext] Fallback fetch failed:", fallbackErr.message);
            throw new Error(`Order fetch failed: ${fallbackErr.message}`);
        }
      }

      const data = await res.json();
      processOrders(data);
    } catch (e: any) {
      console.error("[OrderContext] Fatal Sync Error:", e.message);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => {
          /**
           * Robust Address Extraction:
           * Retrieve the snapshot from the status_history entry where it was saved.
           */
          const addressSource = (o.status_history?.[0]?.address_snapshot) ||
                                (typeof o.metadata === 'object' && o.metadata?.address ? o.metadata.address : null) ||
                                (typeof o.address === 'object' ? o.address : null) || 
                                (typeof o.shipping_address === 'object' ? o.shipping_address : null) || 
                                null;

          return {
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || o.total || 0),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            seller_name: o.vendor?.store_name || "VexoKart Direct",
            shippingAddress: addressSource,
          };
        })
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        fetchInbox(user);
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  const generateShippingLabel = (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
      setActiveOrderForLabel(order);
    }
  };

  const closeLabelPreview = () => {
    setActiveOrderForLabel(null);
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required.");
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot = {
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    const rawVendorId = orderData.items[0]?.vendor_id;
    let vendorIdValue: any = null;
    if (rawVendorId) {
      vendorIdValue = isNaN(Number(rawVendorId)) ? rawVendorId : Number(rawVendorId);
    }

    const payload: any = {
      user_id: user.id,
      vendor_id: vendorIdValue,
      items: orderData.items,
      total_amount: Number(orderData.total),
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{ 
        status: "Placed", 
        timestamp, 
        actor: "User", 
        note: "Order placed",
        address_snapshot: addressSnapshot 
      }],
      created_at: timestamp
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: "POST",
      headers: { ...API_HEADERS, "Prefer": "return=representation" },
      body: JSON.stringify(payload),
    });

    if (!res.ok) {
      const errorBody = await res.json().catch(() => ({}));
      console.error("[OrderContext] Database Rejection Details:", res.status, JSON.stringify(errorBody));
      throw new Error(errorBody.message || `Order placement failed (Status: ${res.status})`);
    }

    const result = await res.json();
    const orderId = result[0].id.toString();

    try {
        await createAppNotification({
            user_id: user.id,
            role: 'user',
            title: 'Order Confirmed',
            message: 'Your order has been placed successfully.',
            type: 'order_status'
        });

        if (vendorIdValue) {
            await createAppNotification({
                vendor_id: vendorIdValue,
                role: 'vendor',
                title: 'New Order Received',
                message: `You have received a new order (#${orderId.slice(-6)}). Please pack it.`,
                type: 'order_alert'
            });
        }
    } catch (notifErr) {
        console.warn("Background notification trigger failed", notifErr);
    }

    refreshOrders();
    fetchInbox(user);
    return orderId;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { status, status_history: newHistory };
    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: "PATCH",
      headers: { ...API_HEADERS },
      body: JSON.stringify(updatePayload),
    });

    if (res.ok) {
        try {
            if (status === 'Packed') {
                await createAppNotification({
                    user_id: order.user_id,
                    role: 'user',
                    title: 'Order Packed',
                    message: 'Your order has been packed and will be shipped soon.',
                    type: 'order_status'
                });
            } else if (status === 'Shipped') {
                await createAppNotification({
                    user_id: order.user_id,
                    role: 'user',
                    title: 'Order Shipped',
                    message: 'Your order is on the way. Tracking updates will be available soon.',
                    type: 'order_status'
                });
            } else if (status === 'Delivered') {
                await createAppNotification({
                    user_id: order.user_id,
                    role: 'user',
                    title: 'Order Delivered',
                    message: 'Your order has been delivered successfully. Please rate the product.',
                    type: 'order_status'
                });
                if (order.vendor_id) {
                    await createAppNotification({
                        vendor_id: order.vendor_id,
                        role: 'vendor',
                        title: 'Payment Credited',
                        message: `Order #${orderId.slice(-6)} has been delivered. Amount has been added to your wallet.`,
                        type: 'wallet_update'
                    });
                }
            }
        } catch (notifErr) {
            console.warn("Status notification trigger failed", notifErr);
        }

        await refreshOrders();
        if (user) await fetchInbox(user);
    }
  };

  const createShipment = async (orderId: string, vendorData: any) => {
    await updateOrderStatus(orderId, 'Confirmed', { note: 'Shipment manifest processing started.' });
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Status updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        isLabelGenerating: false,
        activeOrderForLabel,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        closeLabelPreview,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext missing.");
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { VendorContext } from './VendorContext.tsx';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, phone: string, pass: string) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
  logout: () => void;
  addUser: (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : []
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const vendorContext = useContext(VendorContext);
  const { notifyLogin, fetchInbox } = useNotifications();

  const fetchUsers = async () => {
    try {
      const response = await fetch(`${BASE_API_URL}/users?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });
      if (!response.ok) return;
      const data = await response.json();
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  useEffect(() => {
    const init = async () => {
      setIsLoading(true);
      await fetchUsers();

      const sessionUser = localStorage.getItem('vexokart-user');
      if (sessionUser) {
        try {
          const parsed = JSON.parse(sessionUser);
          const res = await fetch(`${BASE_API_URL}/users?email=ilike.${encodeURIComponent(parsed.email)}&select=*`, { headers: API_HEADERS });
          if (res.ok) {
              const userData = await res.json();
              if (Array.isArray(userData) && userData.length > 0) {
                const foundUser = sanitizeUser(userData[0]);
                setUser(foundUser);
                await fetchInbox(foundUser);
              }
          }
        } catch (e) {
          console.error("Session restoration failed:", e);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  const updateUserSession = (userData: User) => {
    const safeUser = sanitizeUser(userData);
    setUser(safeUser);
    localStorage.setItem('vexokart-user', JSON.stringify(safeUser));
  };

  const login = async (email: string, pass: string) => {
    const cleanEmail = email.trim().toLowerCase();
    const cleanPass = pass.trim();

    try {
      const query = `email=ilike.${encodeURIComponent(cleanEmail)}&select=*`;
      const res = await fetch(`${BASE_API_URL}/users?${query}`, { headers: API_HEADERS });

      if (!res.ok) {
        throw new Error("Authentication service connection error.");
      }

      const data = await res.json();

      if (Array.isArray(data) && data.length > 0) {
        const dbUser = data[0];

        if (dbUser.password === cleanPass) {
          const loggedUser = sanitizeUser(dbUser);
          updateUserSession(loggedUser);
          await notifyLogin(loggedUser);
          await fetchInbox(loggedUser);
          return;
        } else {
          throw new Error('Incorrect password. Please try again.');
        }
      }

      throw new Error('No account found with this email. Please sign up.');
    } catch (err: any) {
      console.error("Login Error:", err);
      throw new Error(err.message || 'Identity verification failed.');
    }
  };

  const signup = async (name: string, email: string, phone: string, pass: string) => {
    const cleanEmail = email.trim().toLowerCase();
    try {
        const checkRes = await fetch(`${BASE_API_URL}/users?email=ilike.${encodeURIComponent(cleanEmail)}&select=email`, { headers: API_HEADERS });
        const existing = await checkRes.json().catch(() => []);
        if (Array.isArray(existing) && existing.length > 0) throw new Error('This email is already registered.');

        const newUser = {
          name: name.trim(), 
          email: cleanEmail, 
          phone: phone.trim(), 
          password: pass.trim(), 
          role: 'user',
          addresses: [], 
          wishlist: [], 
          recentlyViewed: [], 
          created_at: new Date().toISOString()
        };

        const res = await fetch(`${BASE_API_URL}/users`, {
          method: 'POST',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify(newUser)
        });

        if (!res.ok) {
          const errBody = await res.json().catch(() => ({}));
          throw new Error(errBody.message || 'Account creation rejected by server.');
        }

        await fetchUsers();
    } catch (err: any) {
        console.error("Signup Error:", err);
        throw new Error(err.message || "Connection failed during registration.");
    }
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
     throw new Error("Direct vendor signup is managed via admin panel.");
  };

  const logout = () => {
    localStorage.removeItem('vexokart-user');
    setUser(null);
  };

  const addUser = async (userData: { name: string; email: string; phone: string; pass: string; role: User['role']; storeName?: string }) => {
    try {
        const newUser = {
          name: userData.name.trim(),
          email: userData.email.trim().toLowerCase(),
          phone: userData.phone.trim(),
          password: userData.pass.trim(),
          role: userData.role,
          addresses: [],
          wishlist: [],
          recentlyViewed: [],
          created_at: new Date().toISOString()
        };

        const res = await fetch(`${BASE_API_URL}/users`, {
          method: 'POST',
          headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
          body: JSON.stringify(newUser)
        });

        if (!res.ok) throw new Error('Identity creation failed');

        const createdUsers = await res.json();
        const createdUser = sanitizeUser(createdUsers[0]);

        if (userData.role === 'vendor' && vendorContext) {
            await vendorContext.addVendorRecord({
                user_id: createdUser.id.toString(),
                store_name: userData.storeName || `${userData.name}'s Store`,
                owner_name: userData.name,
                email: userData.email.toLowerCase(),
                phone: userData.phone,
                profile_image: `https://ui-avatars.com/api/?name=${encodeURIComponent(userData.storeName || userData.name)}&background=FF8A00&color=fff`,
                status: 'pending'
            });
            await vendorContext.refreshVendors();
        }

        await fetchUsers();
    } catch (err: any) {
        console.error("AddUser Error:", err);
        throw err;
    }
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = [...currentAddresses, newAddress];

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.map(a => a.id === address.id ? address : a);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.filter(a => a.id !== addressId);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ addresses: updatedAddresses })
        });
        setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address deletion failed:", e);
    }
  };

  const deleteUser = async (email: string) => {
    if (email === 'admin@vexokart.com') return;
    try {
        await fetch(`${BASE_API_URL}/users?email=eq.${encodeURIComponent(email)}`, { 
            method: 'DELETE', 
            headers: { ...API_HEADERS, 'Prefer': 'return=minimal' } 
        });
        await fetchUsers();
    } catch (e) {
        console.error("User deletion failed:", e);
    }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    if (currentWishlist.includes(productId)) return;

    try {
        const updated = [...currentWishlist, productId];
        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ wishlist: updated })
        });
        setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
        const updated = currentWishlist.filter(id => id !== productId);

        await fetch(`${BASE_API_URL}/users?id=eq.${user.id}`, {
          method: 'PATCH',
          headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
          body: JSON.stringify({ wishlist: updated })
        });
        setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const isInWishlist = (productId: number) => {
    if (!user) return false;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    return currentWishlist.includes(productId);
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, signupAsVendor, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { createContext, useState, useContext, ReactNode } from 'react';
import { Review } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';
import { useAuth } from './AuthContext';

interface ReviewContextType {
  getReviewsByProduct: (productId: number) => Promise<Review[]>;
  addReview: (reviewData: Partial<Review>) => Promise<void>;
  hasUserReviewedOrder: (orderId: string) => Promise<boolean>;
  isSubmitting: boolean;
}

const ReviewContext = createContext<ReviewContextType | undefined>(undefined);

/**
 * Internal helper to ensure the user_id satisfies Postgres UUID requirements
 * specifically for the product_reviews table.
 */
const formatAsUUID = (id: string): string => {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (uuidRegex.test(id)) return id;
  if (/^\d+$/.test(id)) {
    const padded = id.padStart(12, '0');
    return `00000000-0000-0000-0000-${padded}`;
  }
  return id;
};

export const ReviewProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const getReviewsByProduct = async (productId: number): Promise<Review[]> => {
    try {
      // Use select join to fetch the reviewer's name dynamically from the users table
      const res = await fetch(`${BASE_API_URL}/product_reviews?select=*,user:users(name)&product_id=eq.${productId}&order=created_at.desc`, {
        headers: API_HEADERS
      });
      if (!res.ok) return [];
      const data = await res.json();
      return Array.isArray(data) ? data : [];
    } catch (e) {
      console.error("Failed to fetch reviews", e);
      return [];
    }
  };

  const hasUserReviewedOrder = async (orderId: string): Promise<boolean> => {
    if (!user) return false;
    try {
      const uuid = formatAsUUID(user.id);
      const res = await fetch(`${BASE_API_URL}/product_reviews?order_id=eq.${orderId}&user_id=eq.${uuid}&select=id`, {
        headers: API_HEADERS
      });
      const data = await res.json();
      return Array.isArray(data) && data.length > 0;
    } catch (e) {
      return false;
    }
  };

  const addReview = async (reviewData: Partial<Review>) => {
    if (!user || !user.id) {
      throw new Error("You must be logged in to submit a review.");
    }

    setIsSubmitting(true);
    try {
      const payload = {
        product_id: Number(reviewData.product_id),
        order_id: Number(reviewData.order_id), 
        rating: Number(reviewData.rating),
        review_text: reviewData.review_text || '',
        images: Array.isArray(reviewData.images) ? reviewData.images : [],
        video_url: reviewData.video_url || null, 
        user_id: formatAsUUID(user.id), 
        created_at: new Date().toISOString()
      };

      const res = await fetch(`${BASE_API_URL}/product_reviews`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({ message: "Unknown Database Error" }));
        throw new Error(err.message || "Failed to submit review. Please try again.");
      }
    } catch (err: any) {
        console.error("[ReviewContext] Submit Fail:", err.message);
        throw err;
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <ReviewContext.Provider value={{ getReviewsByProduct, addReview, hasUserReviewedOrder, isSubmitting }}>
      {children}
    </ReviewContext.Provider>
  );
};

