        @keyframes wheel-spin {
          0% { transform: scale(1); }
          50% { transform: scale(1.1); }
          100% { transform: scale(1); }
        }
        @keyframes loading-bar {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes trail-1 {
          0%, 100% { opacity: 0.3; transform: translateX(0); }
          50% { opacity: 0.8; transform: translateX(-5px); }
        }
        @keyframes trail-2 {
          0%, 100% { opacity: 0.2; transform: translateX(0); }
          50% { opacity: 0.6; transform: translateX(-8px); }
        }
        @keyframes trail-3 {
          0%, 100% { opacity: 0.1; transform: translateX(0); }
          50% { opacity: 0.4; transform: translateX(-3px); }
        }
        .animate-draw-path { animation: draw-path 2s ease-out forwards; }
        .animate-wheel-spin { animation: wheel-spin 1s infinite ease-in-out; }
        .animate-loading-bar { animation: loading-bar 2s infinite ease-in-out; }
        .animate-trail-1 { animation: trail-1 1.5s infinite ease-in-out; }
        .animate-trail-2 { animation: trail-2 1.5s 0.2s infinite ease-in-out; }
        .animate-trail-3 { animation: trail-3 1.5s 0.4s infinite ease-in-out; }
      `}} />
    </div>
  );
};

