        </div>

        {/* Financial Flow */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase text-gray-400 tracking-widest italic border-b border-gray-50 pb-2">Payment Protocol</h2>

            <div className="space-y-3">
                <div 
                    onClick={() => togglePayment('is_cod_enabled')}
                    className={`p-4 rounded-3xl border flex items-center justify-between transition-colors cursor-pointer ${formData.is_cod_enabled ? 'bg-green-50 border-green-100' : 'bg-gray-50 border-gray-100 grayscale opacity-70'}`}
                >
                    <div>
                        <p className="text-xs font-black text-gray-800 uppercase italic">Cash on Delivery</p>
                        <p className="text-[9px] text-gray-500 font-bold uppercase mt-1">Authorize doorstep settlement</p>
                    </div>
                    <div className="relative inline-flex items-center">
                        <div className={`w-11 h-6 rounded-full transition-all ${formData.is_cod_enabled ? 'bg-accent' : 'bg-gray-200'}`}>
                            <div className={`absolute top-[2px] left-[2px] bg-white border border-gray-300 rounded-full h-5 w-5 transition-all ${formData.is_cod_enabled ? 'translate-x-full border-white' : ''}`}></div>
                        </div>
                    </div>
                </div>

                <div 
                    onClick={() => togglePayment('is_online_enabled')}
                    className={`p-4 rounded-3xl border flex items-center justify-between transition-colors cursor-pointer ${formData.is_online_enabled ? 'bg-blue-50 border-blue-100' : 'bg-gray-50 border-gray-100 grayscale opacity-70'}`}
                >
                    <div>
                        <p className="text-xs font-black text-gray-800 uppercase italic">Digital Settlement</p>
                        <p className="text-[9px] text-gray-500 font-bold uppercase mt-1">Enable Cards, UPI & Wallets</p>
                    </div>
                    <div className="relative inline-flex items-center">
                        <div className={`w-11 h-6 rounded-full transition-all ${formData.is_online_enabled ? 'bg-accent' : 'bg-gray-200'}`}>
                            <div className={`absolute top-[2px] left-[2px] bg-white border border-gray-300 rounded-full h-5 w-5 transition-all ${formData.is_online_enabled ? 'translate-x-full border-white' : ''}`}></div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <button 
          type="submit" 
          disabled={isSubmitting} 
          className="w-full bg-[#F43397] text-white py-5 rounded-[2rem] font-black uppercase tracking-widest text-sm shadow-xl shadow-[#F43397]/30 active:scale-95 transition-all disabled:opacity-50"
        >
          {isSubmitting ? 'ESTABLISHING HANDSHAKE...' : (isEditing ? 'SYNC CHANGES' : 'DEPLOY LISTING')}
        </button>
      </form>
    </div>
  );
};

export default VendorProductFormPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useProducts } from '../../hooks/useProducts';
import { useCategories } from '../../hooks/useCategories';
import { useAuth } from '../../context/AuthContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { Product } from '../../types';
import ImageCropperModal from '../../components/ImageCropperModal';

const AdminProductFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getProduct, addProduct, updateProduct } = useProducts();
  const { categories } = useCategories();
  const { user } = useAuth();

  const isEditing = id !== undefined;

  const [formData, setFormData] = useState<any>({
    name: '',
    category_id: '', 
    price: 0,
    original_price: 0,
    images: [],
    description: '',
    vendor_id: '',
    status: 'approved',
    highlights: [],
    stock: 10,
    specifications: {},
    is_cod_enabled: true, // Default ON
    is_online_enabled: true // Default ON
  });

  const [highlightsText, setHighlightsText] = useState('');
  const [specsText, setSpecsText] = useState('');

  const [cropQueue, setCropQueue] = useState<string[]>([]);
  const [currentCropIndex, setCurrentCropIndex] = useState(0);
  const [totalInQueue, setTotalInQueue] = useState(0);

  const [isSubmitting, setIsSubmitting] = useState(false);

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  useEffect(() => {
    if (user && !isEditing && !formData.vendor_id) {
      setFormData((prev: any) => ({ ...prev, vendor_id: String(user.id) }));
    }
  }, [user, isEditing]);

  useEffect(() => {
    if (isEditing) {
      const productToEdit = getProduct(parseInt(id));
      if (productToEdit) {
        setFormData({
            ...productToEdit,
            category_id: productToEdit.category_id.toString(),
            // HYDRATE STRICTLY
            is_cod_enabled: productToEdit.is_cod_enabled === true,
            is_online_enabled: productToEdit.is_online_enabled === true
        });
        setHighlightsText((productToEdit.highlights || []).join('\n'));
        setSpecsText(Object.entries(productToEdit.specifications || {}).map(([k, v]) => `${k}: ${v}`).join('\n'));
      }
    } else if (categories.length > 0 && !formData.category_id) {
        setFormData((prev: any) => ({...prev, category_id: categories[0].id.toString()}));
    }
  }, [id, isEditing, getProduct, categories]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    if (type === 'checkbox') {
        setFormData((prev: any) => ({ ...prev, [name]: (e.target as any).checked }));
    } else {
        setFormData((prev: any) => ({ ...prev, [name]: ['price', 'original_price', 'stock'].includes(name) ? parseFloat(value) || 0 : value }));
    }
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      const urls = files.map(f => URL.createObjectURL(f));
      if (urls.length > 0) {
        setTotalInQueue(urls.length);
        setCurrentCropIndex(0);
        setCropQueue(urls);
      }
      e.target.value = '';
    }
  };

  const handleCropComplete = (croppedBase64: string) => {
    setFormData((prev: any) => ({ ...prev, images: [...prev.images, croppedBase64] }));
    if (currentCropIndex < cropQueue.length - 1) {
        setCurrentCropIndex(prev => prev + 1);
    } else {
        setCropQueue([]);
    }
  };

  const removeImage = (index: number) => {
    setFormData((prev: any) => ({ ...prev, images: prev.images.filter((_: any, i: number) => i !== index) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if(formData.images.length === 0) { alert("Please upload at least one image."); return; }
    if (!formData.vendor_id) { alert("System error: Admin ID missing."); return; }

    setIsSubmitting(true);
    try {
      const finalHighlights = highlightsText.split('\n').map(s => s.trim()).filter(Boolean);
      const finalSpecs: { [key: string]: string } = {};
      specsText.split('\n').forEach(line => {
        const parts = line.split(':');
        if (parts.length === 2) finalSpecs[parts[0].trim()] = parts[1].trim();
      });

      const finalData = { 
        ...formData, 
        highlights: finalHighlights, 
        specifications: finalSpecs,
        category_id: Number(formData.category_id),
        // FORCE BOOLEANS
        is_cod_enabled: formData.is_cod_enabled === true,
        is_online_enabled: formData.is_online_enabled === true
      };

      if (isEditing) {
        await updateProduct({ ...finalData, id: parseInt(id) } as Product);
      } else {
        await addProduct(finalData);
      }
      navigate('/admin/products');
    } catch (err: any) {
      alert(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div>
      {cropQueue.length > 0 && (
          <ImageCropperModal 
            image={cropQueue[currentCropIndex]} 
            queueCount={currentCropIndex + 1}
            totalInQueue={totalInQueue}
            title="Standardize Product Image"
            onCropComplete={handleCropComplete}
            onCancel={() => setCropQueue([])}
          />
      )}

      <h1 className="text-3xl font-black text-text-main uppercase italic mb-6">{isEditing ? 'Edit Catalog Entry' : 'Create New Inventory'}</h1>
      <GlassmorphicCard className="p-6">
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Product Name</label><input type="text" name="name" value={formData.name} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
                <div>
                  <label className="block text-[10px] font-black uppercase text-text-muted">Category</label>
                  <select name="category_id" value={formData.category_id} onChange={handleChange} disabled={isSubmitting} className={inputClasses}>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Price (₹)</label><input type="number" name="price" value={formData.price} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
                <div><label className="block text-[10px] font-black uppercase text-text-muted">Original (₹)</label><input type="number" name="original_price" value={formData.original_price} onChange={handleChange} disabled={isSubmitting} className={inputClasses} /></div>
                 <div><label className="block text-[10px] font-black uppercase text-text-muted">Stock Level</label><input type="number" name="stock" value={formData.stock} onChange={handleChange} required disabled={isSubmitting} className={inputClasses} /></div>
            </div>

            <div><label className="block text-[10px] font-black uppercase text-text-muted">Description</label><textarea name="description" value={formData.description} onChange={handleChange} required rows={4} disabled={isSubmitting} className={inputClasses}></textarea></div>

            <div className="p-4 bg-surface rounded-2xl border border-border">
                <label className="block text-[10px] font-black uppercase text-text-muted mb-3">Product Gallery</label>
                <div className="flex flex-wrap gap-4">
                    {formData.images.map((image: string, index: number) => (
                        <div key={index} className="relative group">
                            <img src={image} alt={`preview ${index}`} className="w-24 h-24 object-cover rounded-xl border-2 border-white shadow-md"/>
                            {!isSubmitting && <button type="button" onClick={() => removeImage(index)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold shadow-lg hover:scale-110 transition-transform">&times;</button>}
                        </div>
                    ))}
                    {!isSubmitting && (
                        <div className="relative">
                            <input type="file" id="imageUpload" multiple accept="image/*" onChange={handleImageChange} className="hidden" />
                            <label htmlFor="imageUpload" className="w-24 h-24 cursor-pointer bg-white border-2 border-dashed border-accent/30 rounded-xl flex flex-col items-center justify-center text-accent hover:bg-accent/5 transition-all group">
                                <svg className="w-6 h-6 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
                                <span className="text-[8px] font-black uppercase mt-1">Add Visuals</span>
                            </label>
                        </div>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-1 gap-6">
                <div>
                    <label className="block text-[10px] font-black uppercase text-text-muted mb-4 border-b border-border pb-1">Payment Controls</label>
                    <div className="flex gap-6">
                         <div className="p-4 bg-surface rounded-2xl border border-border">
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <input 
                                        type="checkbox" 
                                        name="is_cod_enabled" 
                                        checked={formData.is_cod_enabled} 
                                        onChange={handleChange} 
                                        className="w-5 h-5 rounded text-accent focus:ring-accent border-border" 
                                    />
                                    <div>
                                        <span className="text-xs font-black uppercase text-text-secondary group-hover:text-text-main transition-colors">Cash on Delivery</span>
                                        <p className="text-[8px] text-text-muted font-bold mt-0.5">ALLOW COD SETTLEMENT</p>
                                    </div>
                                </label>
                            </div>
                            <div className="p-4 bg-surface rounded-2xl border border-border">
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <input 
                                        type="checkbox" 
                                        name="is_online_enabled" 
                                        checked={formData.is_online_enabled} 
                                        onChange={handleChange} 
                                        className="w-5 h-5 rounded text-accent focus:ring-accent border-border" 
                                    />
                                    <div>
                                        <span className="text-xs font-black uppercase text-text-secondary group-hover:text-text-main transition-colors">Online Payment</span>
                                        <p className="text-[8px] text-text-muted font-bold mt-0.5">CARDS / UPI / NETBANKING</p>
                                    </div>
                                </label>
                            </div>
                    </div>
                </div>
            </div>

            <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => navigate('/admin/products')} disabled={isSubmitting} className="px-6 py-2 rounded-xl text-[10px] font-black uppercase text-text-secondary hover:bg-surface">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="bg-accent text-white px-8 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/20 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50">
                    {isSubmitting ? 'Synchronizing...' : (isEditing ? 'Sync Changes' : 'Go Live')}
                </button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminProductFormPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../context/AuthContext';
import { useOrders } from '../context/OrderContext';
import { useVendors } from '../context/VendorContext';
import { useProducts } from '../hooks/useProducts';
import GlassmorphicCard from '../components/GlassmorphicCard';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { Address, OrderItem } from '../types';

/* 🔐 Razorpay Live Key */
const RAZORPAY_LIVE_KEY_ID = 'rzp_live_RxmIholkGEOYaL';

/* 🇮🇳 GST Rate */
const GST_RATE = 0.18;

const CheckoutPage: React.FC = () => {
  const { cartItems, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const { addOrder } = useOrders();
  const { vendors, refreshVendors } = useVendors();
  const { products } = useProducts(); // Fetch fresh product data
  const navigate = useNavigate();

  const [paymentMethod, setPaymentMethod] = useState<'card' | 'cod'>('card');
  const [isProcessing, setIsProcessing] = useState(false);
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);

  /* 🚫 PAYMENT RESTRICTION LOGIC */
  const validatedCartItems = useMemo(() => {
    return cartItems.map(item => {
        // Hydrate with fresh product data to avoid stale cart state
        const freshProduct = products.find(p => p.id === item.id);
        return {
            ...item,
            // Fallback to item property if product not found (e.g. deleted), but prefer fresh data
            // Treat undefined/null as TRUE (Allow) to prevent false positives
            is_cod_enabled: freshProduct ? (freshProduct.is_cod_enabled !== false) : (item.is_cod_enabled !== false),
            is_online_enabled: freshProduct ? (freshProduct.is_online_enabled !== false) : (item.is_online_enabled !== false)
        };
    });
  }, [cartItems, products]);

  const allowCodForCart = useMemo(() => {
    // 1. Check if any item explicitly disables COD
    const hasItemRestriction = validatedCartItems.some(item => item.is_cod_enabled === false);
    if (hasItemRestriction) return false;

    return true;
  }, [validatedCartItems]);

  const allowOnlineForCart = useMemo(() => {
    return validatedCartItems.every(item => item.is_online_enabled !== false);
  }, [validatedCartItems]);

  // Adjust selection if current becomes invalid
  useEffect(() => {
    if (paymentMethod === 'cod' && !allowCodForCart) {
      setPaymentMethod('card');
    } else if (paymentMethod === 'card' && !allowOnlineForCart && allowCodForCart) {
      setPaymentMethod('cod');
    }
  }, [allowCodForCart, allowOnlineForCart, paymentMethod]);

  /* ✅ Precise Calculations */
  const gstAmount = Number((cartTotal * GST_RATE).toFixed(2));
  const finalPayable = Number((cartTotal + gstAmount).toFixed(2));

  useEffect(() => {
    if (user?.addresses?.length) {
      setSelectedAddress(user.addresses[0]);
    }
    if (vendors.length === 0) {
      refreshVendors();
    }
  }, [user, vendors.length, refreshVendors]);

  const handlePlaceOrder = async () => {
    if (!user || !selectedAddress) {
      alert('Please select delivery address');
      return;
    }

    if (finalPayable <= 0) {
      alert('Invalid order amount');
      return;
    }

    if (!allowCodForCart && !allowOnlineForCart) {
        alert("Checkout is currently restricted for these items.");
        return;
    }

    setIsProcessing(true);

    const orderItems: OrderItem[] = cartItems.map(item => {
      const vendor = vendors.find(v => String(v.id) === String(item.vendor_id));
      return {
        id: item.id,
        name: item.name,
        price: item.price,
        quantity: item.quantity,
        image: item.images[0],
        vendor_id: String(item.vendor_id),
        vendor_name: vendor?.store_name || (item.vendor_id === 'vexokart_direct' ? 'VexoKart Direct' : 'Unknown Seller'),
        color: item.selectedColor,
        size: item.selectedSize,
      };
    });

    try {
      /* 🟢 CASH ON DELIVERY FLOW - CRITICAL: Skip Razorpay */
      if (paymentMethod === 'cod') {
        const orderIdString = await addOrder({
          items: orderItems,
          subtotal: cartTotal,
          gst_amount: gstAmount,
          total: finalPayable,
          shippingAddress: selectedAddress,
          payment_method: 'Cash on Delivery',
        });

        clearCart();
        navigate('/order-success', {
          state: { 
            orderId: String(orderIdString), 
            address: selectedAddress,
            paymentMethod: 'Cash on Delivery',
            totalAmount: finalPayable
          },
          replace: true
        });
        return;
      }

      /* 🟢 ONLINE PAYMENT FLOW */
      if (!(window as any).Razorpay) {
        alert('Payment gateway not loaded. Please check your connection.');
        setIsProcessing(false);
        return;
      }

      const razorpayAmountPaise = Math.round(finalPayable * 100);

      const options = {
        key: RAZORPAY_LIVE_KEY_ID,
        amount: razorpayAmountPaise,
        currency: 'INR',
        name: 'VexoKart',
        description: 'Secured Checkout Payment',
        image: 'https://ghzadiplpazekzgjbdxu.supabase.co/storage/v1/object/public/assets/logo.png',
        handler: async (response: any) => {
          const orderIdString = await addOrder({
            items: orderItems,
            subtotal: cartTotal,
            gst_amount: gstAmount,
            total: finalPayable,
            shippingAddress: selectedAddress,
            payment_method: 'Online Payment',
            payment_id: response.razorpay_payment_id
          });

          clearCart();
          navigate('/order-success', {
            state: { 
              orderId: String(orderIdString), 
              address: selectedAddress,
              paymentMethod: 'Online Payment',
              totalAmount: finalPayable
            },
            replace: true
          });
        },
        prefill: {
          name: user.name,
          email: user.email,
          contact: selectedAddress.phone,
        },
        method: {
          upi: true,
          card: true,
          netbanking: true,
          wallet: false,
        },
        config: {
          display: {
            blocks: {
              banks: {
                name: 'All Secure Methods',
                instruments: [
                  { method: 'upi' },
                  { method: 'card' },
                  { method: 'netbanking' }
                ],
              },
            },
            sequence: ['block.banks'],
            preferences: {
              show_default_blocks: true,
            },
          },
        },
        modal: {
          ondismiss: () => setIsProcessing(false),
          escape: false,
          backdropclose: false
        },
        retry: {
          enabled: true,
          max_count: 3
        },
        timeout: 300,
        theme: { color: '#FF8A00' },
      };

      const rzp = new (window as any).Razorpay(options);
      rzp.on('payment.failed', (err: any) => {
        console.error('[Razorpay Failed]', err);
        alert(err.error?.description || 'Payment failed or declined. Please try another card or UPI.');
        setIsProcessing(false);
      });

      rzp.open();

    } catch (err) {
      console.error('[Checkout Critical Error]', err);
      alert('Order placement encountered a problem. Please contact support.');
      setIsProcessing(false);
    }
  };

  const isCheckoutDisabled = isProcessing || !selectedAddress || (!allowCodForCart && !allowOnlineForCart);

  return (
    <div className="bg-surface min-h-screen">
      {/* Header */}
      <div className="sticky top-0 z-10 p-4 bg-white flex items-center border-b shadow-sm">
        <button onClick={() => navigate('/cart')} className="p-2 -ml-2 mr-2">
          <ChevronLeftIcon className="h-6 w-6" />
        </button>
        <h1 className="text-xl font-black uppercase italic tracking-tighter">Checkout Hub</h1>
      </div>

      <div className="p-4 pb-32 max-w-2xl mx-auto space-y-6">
        {/* Address Selector */}
        <GlassmorphicCard className="p-6 bg-white border-none shadow-premium">
          <h2 className="text-[10px] font-black uppercase mb-4 text-text-muted tracking-[0.2em] italic">
            Fulfillment Destination
          </h2>
          {user?.addresses?.length ? (
             user.addresses.map(address => (
                <div
                  key={address.id}
                  onClick={() => setSelectedAddress(address)}
                  className={`p-4 rounded-2xl border-2 cursor-pointer mb-3 transition-all ${
                    selectedAddress?.id === address.id
                      ? 'border-accent bg-accent/5'
                      : 'border-border hover:border-accent/30'
                  }`}
                >
                  <div className="flex justify-between items-start">
                      <div>
                        <p className="font-black text-xs uppercase italic">{address.fullName}</p>
                        <p className="text-[10px] mt-1 text-text-secondary leading-relaxed uppercase tracking-tighter">
                            {address.street}<br/>
                            {address.city}, {address.state} — {address.zip}
                        </p>
                      </div>
                      {selectedAddress?.id === address.id && (
                          <div className="w-5 h-5 bg-accent rounded-full flex items-center justify-center shadow-lg shadow-accent/20">
                              <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                          </div>
                      )}
                  </div>
                  <p className="text-[10px] font-black text-accent mt-2">
                    PH: {address.phone}
                  </p>
                </div>
              ))
          ) : (
            <button onClick={() => navigate('/addresses/new')} className="w-full py-5 border-2 border-dashed border-border rounded-2xl text-[10px] font-black text-text-muted uppercase tracking-widest hover:border-accent/50 transition-all">Add Shipping Manifest</button>
          )}
        </GlassmorphicCard>

        {/* Payment Logic */}
        <GlassmorphicCard className="p-6 bg-white border-none shadow-premium">
          <h2 className="text-[10px] font-black uppercase mb-4 text-text-muted tracking-[0.2em] italic">
            Settlement Method
          </h2>

          <div className="space-y-3">
            {!allowOnlineForCart && !allowCodForCart ? (
                <div className="p-6 bg-red-50 rounded-2xl border border-red-100 flex flex-col items-center justify-center text-center">
                    <svg className="w-8 h-8 text-red-400 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    <p className="text-xs font-black text-red-600 uppercase italic">Payment Restricted</p>
                    <p className="text-[10px] font-medium text-red-400 mt-1 max-w-xs">The items in your cart are not eligible for COD or Online Payment at this time. Please contact support.</p>
                </div>
            ) : (
                <>
                    {allowOnlineForCart ? (
                        <div
                            onClick={() => setPaymentMethod('card')}
                            className={`p-5 rounded-2xl border-2 cursor-pointer flex items-center justify-between transition-all ${
                                paymentMethod === 'card'
                                ? 'border-accent bg-accent/5 shadow-sm'
                                : 'border-border hover:border-accent/20'
                            }`}
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center">
