                      ))}
                    </div>
                  )}

                  <div className="mt-3 flex items-center gap-1 text-[#34BE82]">
                     <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                     <span className="text-[10px] font-black uppercase tracking-widest">Verified Purchase</span>
                  </div>
                </div>
              );
            })}
            {reviews.length > 5 && (
              <button className="w-full py-3 bg-gray-50 text-gray-500 text-[10px] font-black uppercase tracking-widest rounded-xl active:bg-gray-100">View all {reviews.length} reviews</button>
            )}
