  const getVendorByUserId = (uid: string) => vendors.find(v => String(v.user_id) === String(uid));
  const getVendorById = (id: string) => vendors.find(v => String(v.id) === String(id));

  return (
    <VendorContext.Provider value={{ 
      vendors, currentVendor, isVendorLoading, vendorError,
      addVendorRecord, updateVendorStatus, updateVendorProfile,
      getVendorByUserId, getVendorById, getVendorByEmailDirect,
      fetchCurrentVendor, refreshVendors: fetchVendors 
    }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (!context) throw new Error('useVendors missing');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Vendor } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface VendorContextType {
  vendors: Vendor[];
  currentVendor: Vendor | null;
  isVendorLoading: boolean;
  vendorError: string | null;
  addVendorRecord: (vendorData: Omit<Vendor, 'id' | 'created_at'>) => Promise<void>;
  updateVendorStatus: (vendorId: number, status: Vendor['status'], reason?: string) => Promise<void>;
  updateVendorProfile: (vendorId: number, updates: Partial<Vendor>) => Promise<void>;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
  getVendorByEmailDirect: (email: string) => Promise<Vendor | null>;
  fetchCurrentVendor: (userId: string, force?: boolean) => Promise<void>;
  refreshVendors: () => Promise<void>;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

// FIXED: Removed 'rejection_reason', 'wallet_balance', 'store_address', 'pending_balance' to match DB schema
const VENDOR_COLUMNS = 'id,user_id,store_name,status,owner_name,email,phone,profile_image';

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [currentVendor, setCurrentVendor] = useState<Vendor | null>(() => {
    const cached = sessionStorage.getItem('vxk_vendor_cache');
    return cached ? JSON.parse(cached) : null;
  });
  const [isVendorLoading, setIsVendorLoading] = useState(false);
  const [vendorError, setVendorError] = useState<string | null>(null);

  const fetchVendors = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.message || `Fetch failed (${res.status})`);
      }

      if (Array.isArray(data)) {
          setVendors(data);
      } else {
          console.error("[VendorSync] Response not an array:", data);
      }
    } catch (error: any) {
      console.error("[VendorSync] List Error:", error.message);
    }
  };

  const fetchCurrentVendor = async (userId: string, force = false) => {
    if (!userId) return;

    if (!currentVendor || force) {
        setIsVendorLoading(true);
    }
    setVendorError(null);

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${userId}&select=${VENDOR_COLUMNS}`, {
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.message || "Connection to vendor service failed.");
      }

      if (Array.isArray(data) && data.length > 0) {
        const profile = data[0];
        if (JSON.stringify(profile) !== JSON.stringify(currentVendor)) {
            setCurrentVendor(profile);
            sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(profile));
        }
      } else {
        setCurrentVendor(null);
        setVendorError("Vendor profile not found. Access denied.");
        sessionStorage.removeItem('vxk_vendor_cache');
      }
    } catch (error: any) {
      console.error("[VendorSync] Profile Fetch Error:", error.message);
      setVendorError(error.message || "Failed to sync vendor profile.");
    } finally {
      setIsVendorLoading(false);
    }
  };

  useEffect(() => {
    let intervalId: any;
    if (currentVendor) {
        const pollStatus = async () => {
            try {
                const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${currentVendor.id}&select=${VENDOR_COLUMNS}`, {
                    headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' }
                });
                if (res.ok) {
                    const data = await res.json();
                    if (Array.isArray(data) && data.length > 0) {
                        const fresh = data[0];
                        if (JSON.stringify(fresh) !== JSON.stringify(currentVendor)) {
                            setCurrentVendor(fresh);
                            sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(fresh));
                        }
                    }
                }
            } catch (e) {
                // Silent failure on poll
            }
        };
        const interval = currentVendor.status === 'pending' ? 4000 : 15000;
        intervalId = setInterval(pollStatus, interval);
    }
    return () => { if (intervalId) clearInterval(intervalId); };
  }, [currentVendor]);

  useEffect(() => {
    fetchVendors();
  }, []);

  const updateVendorProfile = async (id: number, updates: Partial<Vendor>) => {
    const safeUpdates: any = {};
    if (updates.store_name) safeUpdates.store_name = updates.store_name;
    if (updates.status) safeUpdates.status = updates.status;
    if (updates.profile_image) safeUpdates.profile_image = updates.profile_image;
    if (updates.phone) safeUpdates.phone = updates.phone;

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(safeUpdates)
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || 'Update failed');
      }

      const updatedData = await res.json();
      if (Array.isArray(updatedData) && updatedData.length > 0) {
          const updatedVendor = updatedData[0];
          if (currentVendor && currentVendor.id === id) {
            setCurrentVendor(updatedVendor);
            sessionStorage.setItem('vxk_vendor_cache', JSON.stringify(updatedVendor));
          }
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Update Error:", err.message);
      throw err;
    }
  };

  const addVendorRecord = async (data: Omit<Vendor, 'id' | 'created_at'>) => {
    try {
      const payload = {
        user_id: data.user_id,
        store_name: data.store_name,
        status: data.status || 'pending',
        owner_name: data.owner_name,
        email: data.email,
        phone: data.phone,
        profile_image: data.profile_image
      };

      const res = await fetch(`${BASE_API_URL}/vendors`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          throw new Error(err.message || 'Record creation failed');
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Create Error:", err.message);
      throw err;
    }
  };

  const updateVendorStatus = async (id: number, status: Vendor['status'], reason?: string) => {
    try {
      const payload: any = { status };
      // 'rejection_reason' column is missing in DB, skipping to avoid error
      const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: API_HEADERS,
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          console.error("Status update failed:", err?.message);
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Status Error:", err.message);
    }
  };

  const getVendorByEmailDirect = async (email: string): Promise<Vendor | null> => null;
  const getVendorByUserId = (uid: string) => vendors.find(v => String(v.user_id) === String(uid));
  const getVendorById = (id: string) => vendors.find(v => String(v.id) === String(id));

  return (
    <VendorContext.Provider value={{ 
      vendors, currentVendor, isVendorLoading, vendorError,
      addVendorRecord, updateVendorStatus, updateVendorProfile,
      getVendorByUserId, getVendorById, getVendorByEmailDirect,
      fetchCurrentVendor, refreshVendors: fetchVendors 
    }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (!context) throw new Error('useVendors missing');
  return context;
};

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { Product } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface ProductContextType {
  products: Product[];
  isLoading: boolean;
  getProduct: (id: number) => Product | undefined;
  addProduct: (productData: any) => Promise<void>;
  updateProduct: (productData: Product) => Promise<void>;
  deleteProduct: (productId: number) => Promise<void>;
  toggleProductStatus: (productId: number) => Promise<void>;
  refreshProducts: (vendorId?: number) => Promise<void>;
}

export const ProductContext = createContext<ProductContextType | undefined>(undefined);

const PRODUCT_COLUMNS = '*,category_data:categories(name)';

export const ProductProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshProducts = async (vendorId?: number) => {
    try {
      setIsLoading(true);

      let url = `${BASE_API_URL}/products?select=${PRODUCT_COLUMNS}&order=created_at.desc`;
      if (vendorId && !isNaN(Number(vendorId))) {
          url += `&vendor_id=eq.${vendorId}`;
      }

      const response = await fetch(url, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      const data = await response.json();
      if (!response.ok) {
        throw new Error(data?.message || response.statusText);
      }

      if (Array.isArray(data)) {
        const mappedProducts: Product[] = data.map((item: any) => {
          const basePrice = Number(item.price || 0);

          // Use 'upi_discount_amount' from DB if exists, else calculate default
          const upiDiscount = item.upi_discount_amount 
            ? Number(item.upi_discount_amount) 
            : Math.min(Math.floor(basePrice * 0.05), 100);

          return {
            ...item,
            id: Number(item.id),
            price: basePrice,
            original_price: Number(item.original_price || item.price || 0),
            category: item.category_data?.name || 'General',
            category_id: Number(item.category_id),
            vendor_id: String(item.vendor_id),
            status: item.status || 'approved',

            // Map Database 'allow_cod' / 'allow_online' to UI flags 'is_cod_enabled' / 'is_online_enabled'
            is_cod_enabled: item.allow_cod !== false, // Default true if null/undefined
            is_online_enabled: item.allow_online !== false, // Default true if null/undefined

            product_type: item.product_type || 'simple',

            upi_discount: upiDiscount,
            upi_price: basePrice - upiDiscount,

            variants: item.variants || [], 
            highlights: item.highlights || [],
            specifications: item.specifications || {} 
          };
        });
        setProducts(mappedProducts);
      }
    } catch (error: any) {
      console.error("[ProductSync] Fatal Error:", error.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshProducts();
  }, []);

  const getProduct = (id: number) => products.find(p => p.id === id);

  const addProduct = async (productData: any) => {
    // Separate UI flags from DB payload
    const { 
      is_cod_enabled,
      is_online_enabled,
      payment_modes, 
      cash_on_delivery,
      category, 
      category_data, 
      upi_price,
      upi_discount,
      ...payloadData 
    } = productData;

    const finalPayload = {
      ...payloadData,
      vendor_id: Number(productData.vendor_id),
      category_id: Number(productData.category_id),
      images: Array.isArray(productData.images) ? productData.images : [],
      created_at: new Date().toISOString(),
      status: productData.status || 'approved',

      // Save flags to correct DB columns
      allow_cod: is_cod_enabled,
      allow_online: is_online_enabled,
      product_type: productData.product_type || 'simple'
    };

    // Cleanup extra virtual fields
    delete (finalPayload as any).id;
    delete (finalPayload as any).category;
    delete (finalPayload as any).category_data;
    delete (finalPayload as any).upi_price;
    delete (finalPayload as any).upi_discount;

    try {
      const res = await fetch(`${BASE_API_URL}/products`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(finalPayload)
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || `Database save failed`);
      }

      await refreshProducts(finalPayload.vendor_id);
    } catch (err: any) {
      console.error("[ProductSync] Submission Error:", err.message);
      throw err;
    }
  };

  const updateProduct = async (product: Product) => {
    const { 
      is_cod_enabled,
      is_online_enabled,
      payment_modes,
      cash_on_delivery,
      category, 
      category_data, 
      upi_price,
      upi_discount,
      ...payloadData 
    } = product as any;

    const finalPayload = {
      ...payloadData,
      vendor_id: Number(payloadData.vendor_id),
      category_id: Number(payloadData.category_id),

      // Map UI flags back to DB columns
      allow_cod: is_cod_enabled,
      allow_online: is_online_enabled
    };

    delete (finalPayload as any).id;
    delete (finalPayload as any).created_at;
    delete (finalPayload as any).category;
    delete (finalPayload as any).category_data;
    delete (finalPayload as any).upi_price;
    delete (finalPayload as any).upi_discount;

    try {
      const res = await fetch(`${BASE_API_URL}/products?id=eq.${product.id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(finalPayload)
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || "Update failed");
      }
      await refreshProducts(finalPayload.vendor_id);
    } catch (err: any) {
      console.error("[ProductSync] Update Error:", err.message);
      throw err;
    }
  };

  const toggleProductStatus = async (id: number) => {
    const product = getProduct(id);
    if (!product) return;
    const newStatus = product.status === 'approved' ? 'disabled' : 'approved';

    try {
      const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS },
        body: JSON.stringify({ status: newStatus })
      });
      if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          console.error("Status toggle failed:", err?.message);
      }
      await refreshProducts(Number(product.vendor_id));
    } catch (err: any) {
      console.error("[ProductSync] Status Toggle Error:", err.message);
    }
  };

  const deleteProduct = async (id: number) => {
    try {
      const res = await fetch(`${BASE_API_URL}/products?id=eq.${id}`, { 
        method: 'DELETE', 
        headers: API_HEADERS 
      });
      if (res.ok) {
          setProducts(prev => prev.filter(p => p.id !== id));
      } else {
          const err = await res.json().catch(() => ({}));
          console.error("Delete failed:", err?.message);
      }
    } catch (err: any) {
      console.error("[ProductSync] Delete Error:", err.message);
    }
  };

  return (
    <ProductContext.Provider value={{ 
      products, isLoading, getProduct, addProduct, updateProduct, deleteProduct, toggleProductStatus, refreshProducts 
    }}>
      {children}
    </ProductContext.Provider>
  );
};

export const useProducts = () => {
  const context = useContext(ProductContext);
  if (!context) throw new Error("useProducts missing provider");
  return context;
};

