export const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { supabase } from '../supabase.ts';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  loginWithEmail: (email: string) => Promise<{ error: any }>;
  logout: () => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addUser: (userData: any) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : [],
  role: u.role || 'user'
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const { notifyLogin, fetchInbox } = useNotifications();

  // Fetch all profiles (for Admin usage)
  const fetchUsers = async () => {
    try {
      const { data, error } = await supabase.from('profiles').select('*');
      if (error) throw error;
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching profiles:", error);
    }
  };

  useEffect(() => {
    // 1. Check active session on mount
    const checkSession = async () => {
      setIsLoading(true);
      const { data: { session } } = await supabase.auth.getSession();

      if (session?.user) {
        await handleUserProfile(session.user.id, session.user.email!);
      } else {
        setUser(null);
      }
      setIsLoading(false);
    };

    checkSession();

    // 2. Listen for auth changes (Magic Link click, Logout, etc.)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        setIsLoading(true);
        await handleUserProfile(session.user.id, session.user.email!);
        setIsLoading(false);
      } else if (event === 'SIGNED_OUT') {
        setUser(null);
        localStorage.removeItem('vexokart-user');
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const handleUserProfile = async (userId: string, email: string) => {
    try {
      // Try to get existing profile
      let { data: profile, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error && error.code === 'PGRST116') {
        // Profile doesn't exist, create it
        const newProfile = {
          id: userId,
          email: email,
          name: email.split('@')[0], // Default name from email
          role: 'user',
          created_at: new Date().toISOString(),
          addresses: [],
          wishlist: [],
          recentlyViewed: []
        };

        const { data: created, error: createError } = await supabase
          .from('profiles')
          .insert([newProfile])
          .select()
          .single();

        if (createError) throw createError;
        profile = created;
      } else if (error) {
        throw error;
      }

      const appUser = sanitizeUser(profile);
      setUser(appUser);
      localStorage.setItem('vexokart-user', JSON.stringify(appUser));

      // Admin: fetch all users
      if (appUser.role === 'admin') {
        fetchUsers();
      }

      await fetchInbox(appUser);

    } catch (err) {
      console.error("Profile sync error:", err);
      // Fallback: create a temporary session user if DB fails
      setUser({
          id: userId,
          email: email,
          name: email.split('@')[0],
          role: 'user',
          addresses: [],
          wishlist: [],
          recentlyViewed: [],
          created_at: new Date().toISOString()
      } as User);
    }
  };

  const loginWithEmail = async (email: string) => {
    const { error } = await supabase.auth.signInWithOtp({
      email,
      options: {
        emailRedirectTo: window.location.origin, // Redirects back to the app (localhost or deployed URL)
      },
    });
    return { error };
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    localStorage.removeItem('vexokart-user');
  };

  const updateUserSession = (userData: User) => {
    setUser(userData);
    localStorage.setItem('vexokart-user', JSON.stringify(userData));
  };

  // --- Profile Management Helpers ---

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = [...currentAddresses, newAddress];

        const { error } = await supabase
            .from('profiles')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.map(a => a.id === address.id ? address : a);

        const { error } = await supabase
            .from('profiles')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address update failed:", e);
    }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const currentAddresses = Array.isArray(user.addresses) ? user.addresses : [];
        const updatedAddresses = currentAddresses.filter(a => a.id !== addressId);

        const { error } = await supabase
            .from('profiles')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) setUser({ ...user, addresses: updatedAddresses });
    } catch (e) {
        console.error("Address deletion failed:", e);
    }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    if (currentWishlist.includes(productId)) return;

    try {
        const updated = [...currentWishlist, productId];
        const { error } = await supabase
            .from('profiles')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
        const updated = currentWishlist.filter(id => id !== productId);

        const { error } = await supabase
            .from('profiles')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) setUser({ ...user, wishlist: updated });
    } catch (e) {
        console.error("Wishlist sync failed:", e);
    }
  };

  const isInWishlist = (productId: number) => {
    if (!user) return false;
    const currentWishlist = Array.isArray(user.wishlist) ? user.wishlist : [];
    return currentWishlist.includes(productId);
  };

  // Admin function placeholder
  const deleteUser = async (email: string) => {
      // Deleting users from Auth requires Service Role key, usually done on backend.
      // We can only delete the profile row here.
      console.warn("Delete User: Functionality restricted to Supabase Dashboard or Edge Functions for security.");
  };

  const addUser = async (userData: any) => {
      console.warn("Add User: Manual user creation via Admin Panel is deprecated for Magic Link auth. Users must sign up themselves.");
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      loginWithEmail, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

