import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { supabase } from '../supabase.ts';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addUser: (userData: any) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : [],
  role: u.role || 'user'
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const { notifyLogin, fetchInbox } = useNotifications();

  // Fetch all profiles (for Admin usage)
  const fetchUsers = async () => {
    try {
      const { data, error } = await supabase.from('profiles').select('*');
      if (error) throw error;
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching profiles:", error);
    }
  };

  const createGuestUser = () => {
    const guestId = `guest-${Math.random().toString(36).substr(2, 9)}`;
    const guestUser: User = {
        id: guestId,
        name: 'Guest User',
        email: '',
        phone: '',
        role: 'user',
        addresses: [],
        wishlist: [],
        recentlyViewed: [],
        created_at: new Date().toISOString()
    };
    setUser(guestUser);
    localStorage.setItem('vexokart-user', JSON.stringify(guestUser));
    return guestUser;
  };

  useEffect(() => {
    // Initialize Auth State
    const initAuth = async () => {
      setIsLoading(true);
      const stored = localStorage.getItem('vexokart-user');

      if (stored) {
        try {
            const parsed = JSON.parse(stored);
            // Refresh from DB if it's a real user (not guest)
            if (parsed.email) {
                const { data } = await supabase.from('profiles').select('*').eq('id', parsed.id).single();
                if (data) {
                    const refreshedUser = sanitizeUser(data);
                    setUser(refreshedUser);
                    localStorage.setItem('vexokart-user', JSON.stringify(refreshedUser));
                    if (refreshedUser.role === 'admin') fetchUsers();
                    await fetchInbox(refreshedUser);
                } else {
                    // Fallback to stored if DB fail or guest
                    setUser(parsed);
                }
            } else {
                setUser(parsed); // Guest
            }
        } catch (e) {
            createGuestUser();
        }
      } else {
        createGuestUser();
      }
      setIsLoading(false);
    };

    initAuth();
  }, []);

  const login = async (email: string, pass: string) => {
    // Internal Login Logic for Vendor/Admin
    // Since we removed Auth Service, we query profiles directly.
    // NOTE: This assumes profiles exist. For security in a real app, use a proper Auth service.
    try {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('email', email)
            .single();

        if (error || !data) throw new Error('Account not found.');

        // Simple role check restriction
        if (data.role === 'user') {
             throw new Error('Customer login is disabled. Guest mode active.');
        }

        const loggedUser = sanitizeUser(data);
        setUser(loggedUser);
        localStorage.setItem('vexokart-user', JSON.stringify(loggedUser));
        await notifyLogin(loggedUser);

        if (loggedUser.role === 'admin') fetchUsers();
        await fetchInbox(loggedUser);

    } catch (err: any) {
        throw new Error(err.message || 'Login failed.');
    }
  };

  const logout = async () => {
    // Just reset to Guest
    createGuestUser();
  };

  const updateUserSession = (userData: User) => {
    setUser(userData);
    localStorage.setItem('vexokart-user', JSON.stringify(userData));
  };

  // --- Profile Management Helpers ---

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    const newAddress = { ...address, id: Date.now().toString() };
    const updatedAddresses = [...user.addresses, newAddress];

    // Sync if not guest
    if (user.email) {
        await supabase.from('profiles').update({ addresses: updatedAddresses }).eq('id', user.id);
    }
    updateUserSession({ ...user, addresses: updatedAddresses });
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    const updatedAddresses = user.addresses.map(a => a.id === address.id ? address : a);

    if (user.email) {
        await supabase.from('profiles').update({ addresses: updatedAddresses }).eq('id', user.id);
    }
    updateUserSession({ ...user, addresses: updatedAddresses });
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    const updatedAddresses = user.addresses.filter(a => a.id !== addressId);

    if (user.email) {
        await supabase.from('profiles').update({ addresses: updatedAddresses }).eq('id', user.id);
    }
    updateUserSession({ ...user, addresses: updatedAddresses });
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    if (user.wishlist.includes(productId)) return;
    const updated = [...user.wishlist, productId];

    if (user.email) {
        await supabase.from('profiles').update({ wishlist: updated }).eq('id', user.id);
    }
    updateUserSession({ ...user, wishlist: updated });
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    const updated = user.wishlist.filter(id => id !== productId);

    if (user.email) {
        await supabase.from('profiles').update({ wishlist: updated }).eq('id', user.id);
    }
    updateUserSession({ ...user, wishlist: updated });
  };

  const isInWishlist = (productId: number) => {
    return user ? user.wishlist.includes(productId) : false;
  };

  const deleteUser = async (email: string) => {
      console.warn("User deletion disabled in guest mode.");
  };

  const addUser = async (userData: any) => {
      // Create profile directly
      const newId = `user-${Date.now()}`;
      const newProfile = {
          id: newId,
          email: userData.email,
          name: userData.name,
          role: userData.role,
          created_at: new Date().toISOString(),
          phone: userData.phone,
          addresses: [],
          wishlist: [],
          recentlyViewed: []
      };
      await supabase.from('profiles').insert([newProfile]);
      fetchUsers();
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
      // Simulated vendor signup
      const newId = `vnd-${Date.now()}`;
      const newProfile = {
          id: newId,
          email,
          name,
          role: 'vendor',
          created_at: new Date().toISOString(),
          phone: '',
          addresses: [],
          wishlist: [],
          recentlyViewed: []
      };
      // In real scenario, we'd validate Admin Code here.
      const { error } = await supabase.from('profiles').insert([newProfile]);
      if (error) throw error;

      // Also create vendor record
      await supabase.from('vendors').insert([{
          user_id: newId,
          store_name: storeName,
          owner_name: name,
          email: email,
          status: 'pending',
          phone: ''
      }]);

      // Auto login
      setUser(sanitizeUser(newProfile));
      localStorage.setItem('vexokart-user', JSON.stringify(newProfile));
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers, signupAsVendor
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

