        if (!error) {
            const updated = { ...user, has_seen_onboarding: true };
            updateUserSession(updated);
        }
    } catch (e) {
        console.error("Failed to update onboarding status", e);
    }
  };

  // --- Profile Management Helpers (Updated table name to 'users') ---

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const updatedAddresses = [...user.addresses, newAddress];

        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.map(a => a.id === address.id ? address : a);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.filter(a => a.id !== addressId);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    if (user.wishlist.includes(productId)) return;
    try {
        const updated = [...user.wishlist, productId];
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const updated = user.wishlist.filter(id => id !== productId);
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const isInWishlist = (productId: number) => {
    return user ? user.wishlist.includes(productId) : false;
  };

  const deleteUser = async (email: string) => {
      console.warn("User deletion requires admin privileges via backend.");
  };

  const addUser = async (userData: any) => {
      await signup(userData.name, userData.email, userData.pass || '123456');
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
      const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: pass,
        options: { data: { name } }
      });
      if (error) throw error;

      if (data.user) {
          const newProfilePayload = {
              auth_id: data.user.id,
              email: email.trim(),
              name,
              role: 'vendor',
              created_at: new Date().toISOString(),
              addresses: [],
              wishlist: [],
              has_seen_onboarding: false
          };

          // Insert profile into 'users' table
          const { error: profileError } = await supabase.from('users').insert([newProfilePayload]);

          if (!profileError) {
              // Now insert into vendors table. Note: vendors table likely needs numeric ID from users table
              // We need to fetch the created user first to get the ID
              const { data: userData } = await supabase.from('users').select('id').eq('auth_id', data.user.id).single();

              if (userData) {
                  await supabase.from('vendors').insert([{
                      user_id: userData.id, // Linking via numeric ID
                      store_name: storeName,
                      owner_name: name,
                      email: email.trim(),
                      status: 'pending',
                      phone: ''
                  }]);
              }

              await fetchProfile(data.user.id);
          } else {
              console.error("Vendor profile creation failed:", profileError);
              throw new Error("Failed to create vendor profile.");
          }
      }
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers, signupAsVendor,
      completeOnboarding
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { supabase } from '../supabase.ts';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { login, isAuthenticated } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (isAuthenticated) {
        navigate('/home', { replace: true });
    }
  }, [isAuthenticated, navigate]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
        setError("Please fill in all fields");
        return;
    }

    setIsSubmitting(true);
    setError('');

    try {
        await login(email.trim(), password);
        navigate('/home', { replace: true });
    } catch (err: any) {
        console.error(err);
        // Custom logic for "Invalid login credentials"
        if (err.message === "Invalid login credentials") {
            try {
                const { data, error: checkError } = await supabase
                    .from('users')
                    .select('email')
                    .eq('email', email.trim())
                    .single();

                if (data && !checkError) {
                    // Email exists in profiles but auth failed.
                    setError("Account needs reactivation or password reset. Please contact support.");
                } else {
                    // Email doesn't exist anywhere, or DB error. Show original message.
                    setError(err.message);
                }
            } catch (checkError) {
                // If the check itself fails, just show the original error.
                setError(err.message);
            }
        } else {
            setError(err.message || "An unknown error occurred");
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 pt-12 animate-in fade-in duration-300">

      <div className="mb-8">
        <button onClick={() => navigate('/home')} className="mb-4 inline-flex items-center gap-2 text-text-muted text-xs font-bold uppercase tracking-widest hover:text-text-main transition-colors">
            <ChevronLeftIcon className="w-4 h-4" />
            Back to Browse
        </button>
        <h2 className="text-3xl font-black text-text-main italic uppercase tracking-tight mb-2">Welcome Back</h2>
        <p className="text-text-muted text-sm font-medium">Log in to continue shopping</p>
      </div>

      <div className="flex-1 max-w-md mx-auto w-full">
        {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Email Address</label>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="name@example.com"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Password</label>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mt-4"
            >
                {isSubmitting ? 'Verifying...' : 'Secure Login'}
            </button>
        </form>

        <div className="mt-8 text-center">
            <p className="text-gray-400 text-xs font-bold">
                Don't have an account?{' '}
                <Link to="/signup" className="text-accent hover:underline decoration-2 underline-offset-4">
                    Create One
                </Link>
            </p>
        </div>

        <div className="mt-12 border-t border-gray-100 pt-6 text-center">
             <Link to="/vendor/login" className="text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-gray-600 transition-colors">
                Vendor / Admin Portal
             </Link>
        </div>
      </div>
    </div>
  );
};

