import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';
import { supabase } from '../supabase.ts';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { login, isAuthenticated } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (isAuthenticated) {
        navigate('/home', { replace: true });
    }
  }, [isAuthenticated, navigate]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
        setError("Please fill in all fields");
        return;
    }

    setIsSubmitting(true);
    setError('');

    try {
        await login(email.trim(), password);
        navigate('/home', { replace: true });
    } catch (err: any) {
        console.error(err);
        if (err.message === "Invalid login credentials") {
            try {
                const { data, error: checkError } = await supabase
                    .from('users')
                    .select('email')
                    .eq('email', email.trim())
                    .maybeSingle();

                if (data && !checkError) {
                    setError("Account inactive. Please reset password.");
                } else {
                    setError(err.message);
                }
            } catch (checkError) {
                setError(err.message);
            }
        } else {
            setError(err.message || "An unknown error occurred");
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 pt-12 animate-in fade-in duration-300">

      <div className="mb-8">
        <button onClick={() => navigate('/home')} className="mb-4 inline-flex items-center gap-2 text-text-muted text-xs font-bold uppercase tracking-widest hover:text-text-main transition-colors">
            <ChevronLeftIcon className="w-4 h-4" />
            Back to Browse
        </button>
        <h2 className="text-3xl font-black text-text-main italic uppercase tracking-tight mb-2">Welcome Back</h2>
        <p className="text-text-muted text-sm font-medium">Log in to continue shopping</p>
      </div>

      <div className="flex-1 max-w-md mx-auto w-full">
        {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Email Address</label>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="name@example.com"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <div className="space-y-1">
                <div className="flex justify-between items-center">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Password</label>
                    <Link to="/forgot-password" className="text-[10px] font-black text-accent uppercase tracking-widest">Forgot?</Link>
                </div>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mt-4"
            >
                {isSubmitting ? 'Verifying...' : 'Secure Login'}
            </button>
        </form>

        <div className="mt-8 text-center">
            <p className="text-gray-400 text-xs font-bold">
                Don't have an account?{' '}
                <Link to="/signup" className="text-accent hover:underline decoration-2 underline-offset-4">
                    Create One
                </Link>
            </p>
        </div>

        <div className="mt-12 border-t border-gray-100 pt-6 text-center">
             <Link to="/vendor/login" className="text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-gray-600 transition-colors">
                Vendor / Admin Portal
             </Link>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { supabase } from '../supabase';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';

const ForgotPasswordPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();

  const handleReset = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
        setError("Please enter your email address");
        return;
    }

    setIsSubmitting(true);
    setError('');
    setMessage('');

    const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/#/update-password`,
    });

    if (resetError) {
        setError(resetError.message);
    } else {
        setMessage("Password reset link sent! Please check your email inbox and spam folder.");
    }

    setIsSubmitting(false);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 pt-12 animate-in fade-in duration-300">

      <div className="mb-8">
        <button onClick={() => navigate('/login')} className="mb-4 inline-flex items-center gap-2 text-text-muted text-xs font-bold uppercase tracking-widest hover:text-text-main transition-colors">
            <ChevronLeftIcon className="w-4 h-4" />
            Back to Login
        </button>
        <h2 className="text-3xl font-black text-text-main italic uppercase tracking-tight mb-2">Reset Password</h2>
        <p className="text-text-muted text-sm font-medium">Enter your email to receive a recovery link.</p>
      </div>

      <div className="flex-1 max-w-md mx-auto w-full">
        {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
            </div>
        )}

        {message && (
            <div className="mb-6 p-4 bg-green-50 border border-green-100 rounded-xl text-green-600 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {message}
            </div>
        )}

        <form onSubmit={handleReset} className="space-y-6">
            <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">Email Address</label>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="name@example.com"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={isSubmitting || !!message}
                className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mt-4"
            >
                {isSubmitting ? 'Sending...' : 'Send Recovery Link'}
            </button>
        </form>
      </div>
    </div>
  );
};

export default ForgotPasswordPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabase';
import { Session } from '@supabase/supabase-js';

const UpdatePasswordPage: React.FC = () => {
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Supabase password recovery flow redirects with a hash fragment.
    // We listen for the auth state change which will contain the session
    // if the token in the URL is valid.
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        // Now we have a session, we can allow the user to update their password.
        // We don't need to do anything here, the user is now signed in.
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 6) {
        setError("Password must be at least 6 characters long.");
        return;
    }

    setIsSubmitting(true);
    setError('');
    setMessage('');

    const { error: updateError } = await supabase.auth.updateUser({ password });

    if (updateError) {
        setError(updateError.message);
    } else {
        setMessage("Your password has been updated successfully. Redirecting to login...");
        setTimeout(() => {
            supabase.auth.signOut(); // Sign out to force a clean login with the new password
            navigate('/login');
        }, 3000);
    }

    setIsSubmitting(false);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 pt-12 animate-in fade-in duration-300">
      <div className="mb-8">
        <h2 className="text-3xl font-black text-text-main italic uppercase tracking-tight mb-2">Set New Password</h2>
        <p className="text-text-muted text-sm font-medium">Your access token is valid. Please enter a new secure password.</p>
      </div>

      <div className="flex-1 max-w-md mx-auto w-full">
        {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
            </div>
        )}

        {message && (
            <div className="mb-6 p-4 bg-green-50 border border-green-100 rounded-xl text-green-600 text-xs font-bold flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {message}
            </div>
        )}

        <form onSubmit={handleUpdate} className="space-y-6">
            <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-1">New Password</label>
                <div className="bg-gray-50 border border-gray-200 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-4 focus-within:ring-accent/5">
                    <input
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="Min. 6 characters"
                        className="w-full bg-transparent p-3 text-sm font-bold text-text-main placeholder-gray-300 outline-none"
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={isSubmitting || !!message}
                className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mt-4"
            >
                {isSubmitting ? 'Updating...' : 'Update Password & Login'}
            </button>
        </form>
      </div>
    </div>
  );
};

export default UpdatePasswordPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { useAuth } from '../../context/AuthContext';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import { supabase } from '../../supabase.ts';

const VendorLoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();
  const { login, user } = useAuth();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);
    try {
      await login(email.trim(), password);
    } catch (err: any) {
        console.error(err);
        if (err.message === "Invalid login credentials") {
            try {
                const { data, error: checkError } = await supabase
                    .from('users')
                    .select('email, role')
                    .eq('email', email.trim())
                    .maybeSingle();

                if (data && !checkError) {
                    if (data.role === 'vendor' || data.role === 'admin') {
                        setError("Account inactive. Please reset password.");
                    } else {
                        setError("This account does not have vendor/admin privileges.");
                    }
                } else {
                    setError(err.message);
                }
            } catch (checkError) {
                setError(err.message);
            }
        } else {
            setError(err.message || "An unknown error occurred");
        }
    } finally {
      setIsSubmitting(false);
    }
  };

  React.useEffect(() => {
    if (user) {
      if (user.role === 'vendor' || user.role === 'admin') {
          navigate(user.role === 'admin' ? '/admin' : '/vendor');
      } else {
          navigate('/profile'); 
      }
    }
  }, [user, navigate]);

  return (
    <div className="min-h-screen flex flex-col justify-center p-6 bg-gray-900 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-64 h-64 bg-accent/20 rounded-full blur-[100px] -mr-20 -mt-20 pointer-events-none"></div>

      <button onClick={() => navigate('/login')} className="absolute top-6 left-6 text-gray-400 hover:text-white transition-colors flex items-center gap-2">
         <ChevronLeftIcon className="w-5 h-5" />
         <span className="text-[10px] font-bold uppercase tracking-widest">Back</span>
      </button>

      <div className="w-full max-w-md mx-auto relative z-10">
        <div className="text-center mb-10">
            <h1 className="text-3xl font-black text-white italic uppercase tracking-tighter">Partner<span className="text-accent">Console</span></h1>
            <p className="text-gray-500 text-[10px] uppercase tracking-[0.3em] mt-2 font-bold">Authorized Access Only</p>
        </div>

        <GlassmorphicCard className="p-8 border-gray-700/50 bg-gray-800/50">
          {error && <div className="bg-red-500/20 border border-red-500/30 text-red-400 text-xs p-3 rounded-lg mb-6 font-bold">{error}</div>}

