const LoginPage: React.FC = () => {
  const location = useLocation();
  const defaultTab = location.state?.defaultTab === 'signup' ? 'signup' : 'login';
  const [activeTab, setActiveTab] = useState<'login' | 'signup'>(defaultTab);

  const { login, signup, isAuthenticated, user } = useAuth();
  const navigate = useNavigate();

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (isAuthenticated && user) {
      const from = user.role === 'admin' ? '/admin' : user.role === 'vendor' ? '/vendor' : '/home';
      navigate(from, { replace: true });
    }
  }, [isAuthenticated, user, navigate]);

  const resetForm = () => {
    setName('');
    setEmail('');
    setPassword('');
    setError('');
  };

  const handleTabChange = (tab: 'login' | 'signup') => {
    setActiveTab(tab);
    resetForm();
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError("Please fill in all fields.");
      return;
    }
    setIsSubmitting(true);
    setError('');
    try {
      await login(email.trim(), password);
    } catch (err: any) {
      setError("Invalid email or password");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email || !password) {
      setError("All fields are required.");
      return;
    }
    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }
    setIsSubmitting(true);
    setError('');
    try {
      await signup(name.trim(), email.trim(), password);
    } catch (err: any) {
      setError(err.message || "Signup failed. The email might already be in use.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const inputClasses = "w-full mt-1 bg-surface border border-border rounded-xl p-3 text-sm font-bold text-text-main placeholder-text-muted outline-none focus:border-accent focus:ring-2 focus:ring-accent/20 transition-all";

  return (
    <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-md">
        <div className="text-center mb-6">
          <h1 className="text-4xl font-black text-text-main italic uppercase tracking-tighter">
            Vexo<span className="text-accent">Kart</span>
          </h1>
          <p className="text-text-muted text-xs font-bold uppercase tracking-[0.3em] mt-1">Secure Portal</p>
        </div>

        <div className="bg-white rounded-3xl shadow-premium border border-border p-6 md:p-8">
          {/* Tab Switcher */}
          <div className="relative mb-8 bg-surface rounded-full p-1 flex">
            <div
              className="absolute top-1 bottom-1 bg-white rounded-full shadow-md transition-all duration-300 ease-in-out"
              style={{
                width: 'calc(50% - 4px)',
                left: activeTab === 'login' ? '4px' : 'calc(50% + 4px)',
              }}
            />
            <button
              onClick={() => handleTabChange('login')}
              className={`relative z-10 w-1/2 py-2 text-center text-xs font-black uppercase tracking-widest transition-colors duration-300 ${activeTab === 'login' ? 'text-text-main' : 'text-text-muted'}`}
            >
              Login
            </button>
            <button
              onClick={() => handleTabChange('signup')}
              className={`relative z-10 w-1/2 py-2 text-center text-xs font-black uppercase tracking-widest transition-colors duration-300 ${activeTab === 'signup' ? 'text-text-main' : 'text-text-muted'}`}
            >
              Sign Up
            </button>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold text-center">
              {error}
            </div>
          )}

          {activeTab === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-5 animate-in fade-in duration-500">
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Email Address</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required className={inputClasses} />
              </div>
              <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-xl font-black uppercase tracking-widest text-sm shadow-lg shadow-accent/20 active:scale-95 transition-all disabled:opacity-50">
                {isSubmitting ? 'Verifying...' : 'Secure Login'}
              </button>
            </form>
          ) : (
            <form onSubmit={handleSignup} className="space-y-5 animate-in fade-in duration-500">
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Full Name</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Email Address</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required placeholder="Min. 6 characters" className={inputClasses} />
              </div>
              <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-xl font-black uppercase tracking-widest text-sm shadow-lg shadow-accent/20 active:scale-95 transition-all disabled:opacity-50">
                {isSubmitting ? 'Creating Account...' : 'Create Account'}
              </button>
            </form>
          )}
          <div className="text-center mt-6">
            <Link to="/forgot-password" className="text-xs font-bold text-text-muted hover:text-accent transition-colors">Forgot Password?</Link>
          </div>
        </div>
        <div className="text-center mt-6">
          <button onClick={() => navigate('/home')} className="text-xs font-bold text-text-muted hover:text-accent transition-colors">
            Continue as Guest
          </button>
        </div>
      </div>
    </div>
  );
};
