              <p className="text-lg font-medium opacity-90 tracking-wide">
                {slide.subtext}
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Sticky Bottom Actions */}
      <div className="fixed bottom-0 left-0 right-0 p-6 z-50 flex flex-col items-center gap-6">

        {/* Pagination Dots */}
        <div className="flex gap-2">
          {slides.map((_, idx) => (
            <div 
