export interface OrderItem {
    id: number;
    name: string;
    price: number;
    quantity: number;
    image: string;
    vendor_id: string;
    vendor_name?: string;
    color?: string;
    size?: string;
    delivery_type?: 'standard' | 'express';
}

export type OrderStatus = 'Placed' | 'Confirmed' | 'Packed' | 'Shipped' | 'Out for Delivery' | 'Delivered' | 'Cancelled';
export type PaymentStatus = 'paid' | 'cod_pending' | 'failed';

export interface StatusHistory {
    status: OrderStatus;
    timestamp: string;
    note?: string;
    actor?: 'System' | 'User' | 'Vendor' | 'Courier' | 'Admin' | 'Shiprocket';
}

export interface Order {
    id: string;
    user_id: string;
    vendor_id?: string;
    items: OrderItem[];
    total: number; 
    total_amount: number; 
    discount_amount?: number;
    payment_mode: 'Online Payment' | 'Cash on Delivery';
    payment_status: PaymentStatus;
    shippingAddress: Address; 
    shipping_address?: Address;
    status: OrderStatus;
    status_history: StatusHistory[]; 
    created_at: string;
    cancellation_reason?: string;
    qr_token?: string;
    awb_code?: string;
    tracking_id?: string;
    courier_name?: string;
    seller_name?: string;
}

export interface Address {
    id: string;
    fullName: string;
    street: string;
    city: string;
    state: string;
    zip: string;
    phone: string;
}

export interface User {
  id: string;
  auth_id?: string; // For linking to auth.users if primary ID is different
  name: string;
  email: string;
  phone: string;
  role: 'user' | 'vendor' | 'admin';
  addresses: Address[];
  wishlist: number[];
  recentlyViewed: number[];
  created_at: string;
  sms_enabled?: boolean;
}

export interface Vendor {
  id: number;
  user_id: string;
  store_name: string;
  status: 'pending' | 'approved' | 'rejected' | 'suspended';
  owner_name: string;
  email: string;
  phone: string;
  profile_image?: string;
  created_at?: string;
  rejection_reason?: string;
  wallet_balance?: number;
  store_address?: string;
  pending_balance?: number;
}

export interface AdminCode {
  id: string;
  code: string;
  status: 'unused' | 'used' | 'revoked';
  createdAt: string;
  expiresAt: string | null;
  note: string;
  maxUsage: number;
  usageCount: number;
  usedBy?: string;
}

export interface Banner {
  id: number;
  image_url: string;
  title: string;
  status: boolean;
  display_order: number;
  created_at: string;
}

export interface NotificationSettings {
  emailEnabled: boolean;
  smsEnabled: boolean;
  smtpHost: string;
  smtpUser: string;
  smtpPass: string;
  emailFrom: string;
  smsApiKey: string;
  smsSenderId: string;
  smsTemplateId: string;
  testMode: boolean;
}

export interface NotificationLog {
  id: number;
  createdAt: string;
  channel: 'email' | 'sms';
  orderId: string;
  status: 'sent' | 'failed';
  response: string;
}

export interface AppNotification {
  id: number;
  user_id?: string;
  vendor_id?: number;
  role: 'user' | 'vendor' | 'admin';
  title: string;
  message: string;
  type: string;
  is_read: boolean;
  created_at: string;
}

import React, { useState } from 'react';
import { useOrders } from '../../context/OrderContext';
import { Order, OrderStatus } from '../../types';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import ShippingDetailsModal from '../../components/admin/ShippingDetailsModal';
import OrderStatusHistoryModal from '../../components/admin/OrderStatusHistoryModal';

const ALL_STATUSES: OrderStatus[] = ['Placed', 'Confirmed', 'Packed', 'Shipped', 'Out for Delivery', 'Delivered', 'Cancelled'];

const AdminOrdersPage: React.FC = () => {
  const { orders, updateOrderStatus, generateShippingLabel, isLabelGenerating } = useOrders();
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [isShippingModalOpen, setShippingModalOpen] = useState(false);
  const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

  const handleStatusChange = (order: Order, status: OrderStatus) => {
    if (status === 'Shipped' && !order.awb_code && !order.tracking_id) {
      setSelectedOrder(order);
      setShippingModalOpen(true);
    } else {
      updateOrderStatus(order.id, status);
    }
  };

  const handleShippingSubmit = (courierName: string, trackingId: string) => {
    if (selectedOrder) {
      updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
    }
    setShippingModalOpen(false);
    setSelectedOrder(null);
  };

  const openHistoryModal = (order: Order) => {
    setSelectedOrder(order);
    setHistoryModalOpen(true);
  }

  const getStatusColor = (status: OrderStatus) => {
      switch(status) {
          case 'Placed': return 'text-gray-300 bg-gray-700/50 border-gray-600/50';
          case 'Confirmed': return 'text-cyan-400 bg-cyan-900/50 border-cyan-600/50';
          case 'Packed': return 'text-indigo-400 bg-indigo-900/50 border-indigo-600/50';
          case 'Shipped': return 'text-blue-400 bg-blue-900/50 border-blue-600/50';
          case 'Out for Delivery': return 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50';
          case 'Delivered': return 'text-green-400 bg-green-900/50 border-green-600/50';
          case 'Cancelled': return 'text-red-400 bg-red-900/50 border-red-600/50';
          default: return 'text-gray-400 bg-gray-700/50 border-gray-600/50';
      }
  }

  return (
    <div>
      {isShippingModalOpen && selectedOrder && (
        <ShippingDetailsModal
          onClose={() => setShippingModalOpen(false)}
          onSubmit={handleShippingSubmit}
        />
      )}
      {isHistoryModalOpen && selectedOrder && (
        <OrderStatusHistoryModal
          // FIX: The `Order` type uses `status_history`. `statusHistory` is a property added by the context but not reflected in the component's state type.
          history={selectedOrder.status_history || []}
          onClose={() => setHistoryModalOpen(false)}
        />
      )}
      <h1 className="text-3xl font-bold text-text-main mb-6">Manage Orders</h1>
      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-gray-700 text-text-muted">
                <th className="p-4 font-semibold">Order ID</th>
                <th className="p-4 font-semibold">Date</th>
                <th className="p-4 font-semibold">Customer</th>
                <th className="p-4 font-semibold">Total</th>
                <th className="p-4 font-semibold">Status</th>
                <th className="p-4 font-semibold">Update Status</th>
                <th className="p-4 font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(order => (
                <tr key={order.id} className="border-b border-gray-800 hover:bg-surface/50">
                  <td className="p-4 text-text-main font-mono">#{order.id}</td>
                  <td className="p-4">{new Date(order.created_at).toLocaleDateString()}</td>
                  <td className="p-4">{order.shippingAddress?.fullName || order.user_id}</td>
                  <td className="p-4 font-semibold">₹{(order.total_amount || order.total || 0).toFixed(2)}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${getStatusColor(order.status)}`}>
                        {order.status}
                    </span>
                  </td>
                  <td className="p-4">
                     <select 
                        value={order.status} 
                        onChange={(e) => handleStatusChange(order, e.target.value as OrderStatus)}
                        className="bg-surface border border-gray-600 rounded-md p-1.5 text-text-main focus:ring-accent focus:border-accent text-xs"
                     >
                        {ALL_STATUSES.map(status => (
                            <option key={status} value={status}>{status}</option>
                        ))}
                    </select>
                  </td>
                   <td className="p-4 space-x-3 whitespace-nowrap">
                    <button onClick={() => openHistoryModal(order)} className="text-accent hover:underline text-xs font-semibold">
                      History
                    </button>
                    {['Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(order.status) && (
                        <button 
                            onClick={() => generateShippingLabel(order.id)}
                            disabled={isLabelGenerating}
                            className="text-white bg-indigo-600 px-3 py-1 rounded-md text-xs font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50"
                        >
                            {isLabelGenerating ? '...' : 'Label'}
                        </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <p className="text-center p-8 text-text-muted">No orders have been placed yet.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminOrdersPage;

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { supabase } from '../supabase.ts';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addUser: (userData: any) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
  // FIX: Added missing OTP methods to the context type for OtpVerificationPage.
  sendOtp: (phone: string) => Promise<void>;
  verifyOtp: (phone: string, token: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  auth_id: u.auth_id,
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : [],
  role: u.role || 'user',
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const stored = localStorage.getItem('vexokart-user');
      return stored ? JSON.parse(stored) : null;
    } catch (e) {
      return null;
    }
  });

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const { fetchInbox } = useNotifications();

  const fetchUsers = async () => {
    try {
      const { data, error } = await supabase.from('users').select('*');
      if (error) throw error;
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  const fetchProfile = async (authUserId: string) => {
    try {
      const { data: profileData, error: profileError } = await supabase
        .from('users')
        .select('*')
        .eq('auth_id', authUserId)
        .maybeSingle();

      if (profileError) {
        console.error("Error fetching profile:", profileError);
        throw profileError;
      }

      if (profileData) {
        const appUser = sanitizeUser(profileData);
        setUser(appUser);
        localStorage.setItem('vexokart-user', JSON.stringify(appUser));
        if (appUser.role === 'admin') fetchUsers();
        fetchInbox(appUser);
        return;
      }

      console.warn(`Profile for auth user ${authUserId} not found. Auto-provisioning...`);

      const { data: { user: authUser } } = await supabase.auth.getUser();

      if (!authUser) {
        throw new Error("Cannot provision profile: No active auth session found.");
      }

      const newProfilePayload = {
        auth_id: authUser.id,
        email: authUser.email,
        name: authUser.user_metadata?.name || 'VexoKart User',
        role: 'user',
        created_at: new Date().toISOString(),
        addresses: [],
        wishlist: [],
        recentlyViewed: [],
        phone: authUser.phone || ''
      };

      const { data: insertedData, error: insertError } = await supabase
        .from('users')
        .insert([newProfilePayload])
        .select()
        .single();

      if (insertError) {
        console.error("Failed to auto-provision profile:", JSON.stringify(insertError));
        throw new Error(`Profile creation failed: ${insertError.message}`);
      }

      if (insertedData) {
        console.log("Profile auto-provisioned successfully.");
        const appUser = sanitizeUser(insertedData);
        setUser(appUser);
        localStorage.setItem('vexokart-user', JSON.stringify(appUser));
        fetchInbox(appUser);
      }

    } catch (err: any) {
      console.error("Profile sync/provisioning error:", err.message);
      setUser(null);
      localStorage.removeItem('vexokart-user');
      throw err;
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (session?.user) {
          if (mounted) await fetchProfile(session.user.id);
        } else {
          if (mounted) {
            setUser(null);
            localStorage.removeItem('vexokart-user');
          }
        }
      } catch (error) {
        console.error("Auth initialization error:", error);
      } finally {
        if (mounted) setIsLoading(false);
      }
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        await fetchProfile(session.user.id);
      } else if (event === 'SIGNED_OUT') {
        setUser(null);
        localStorage.removeItem('vexokart-user');
        setAllUsers([]);
      }
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, []);

  const login = async (email: string, pass: string) => {
    const { data, error } = await supabase.auth.signInWithPassword({
      email: email.trim(),
      password: pass,
    });
    if (error) throw error;
    if (data.user) {
       await fetchProfile(data.user.id);
    }
  };

  const signup = async (name: string, email: string, pass: string) => {
    const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: pass,
        options: {
            data: { name }
        }
    });
    if (error) throw error;

    if (data.user) {
        const newProfilePayload = {
            auth_id: data.user.id,
            email: email.trim(),
            name: name,
            role: 'user',
            created_at: new Date().toISOString(),
            addresses: [],
            wishlist: [],
            recentlyViewed: [],
        };

        const { error: insertError } = await supabase.from('users').insert([newProfilePayload]);

        if (!insertError) {
            await fetchProfile(data.user.id);
        } else {
            console.error("Error creating profile:", JSON.stringify(insertError));
            if (insertError.code === '23505') {
                 await fetchProfile(data.user.id);
            } else {
                 throw new Error(`Profile creation failed: ${insertError.message}`);
            }
        }
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    localStorage.removeItem('vexokart-user');
  };

  const updateUserSession = (userData: User) => {
    setUser(userData);
    localStorage.setItem('vexokart-user', JSON.stringify(userData));
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const updatedAddresses = [...user.addresses, newAddress];

        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.map(a => a.id === address.id ? address : a);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.filter(a => a.id !== addressId);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    if (user.wishlist.includes(productId)) return;
    try {
        const updated = [...user.wishlist, productId];
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const updated = user.wishlist.filter(id => id !== productId);
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const isInWishlist = (productId: number) => {
    return user ? user.wishlist.includes(productId) : false;
  };

  const deleteUser = async (email: string) => {
      console.warn("User deletion requires admin privileges via backend.");
  };

  const addUser = async (userData: any) => {
      await signup(userData.name, userData.email, userData.pass || '123456');
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
      const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: pass,
        options: { data: { name } }
      });
      if (error) throw error;

      if (data.user) {
          const newProfilePayload = {
              auth_id: data.user.id,
              email: email.trim(),
              name,
              role: 'vendor',
              created_at: new Date().toISOString(),
              addresses: [],
              wishlist: [],
          };

          const { error: profileError } = await supabase.from('users').insert([newProfilePayload]);

          if (!profileError) {
              const { data: userData } = await supabase.from('users').select('id').eq('auth_id', data.user.id).single();

              if (userData) {
                  await supabase.from('vendors').insert([{
                      user_id: userData.id,
                      store_name: storeName,
                      owner_name: name,
                      email: email.trim(),
                      status: 'pending',
                      phone: ''
                  }]);
              }

              await fetchProfile(data.user.id);
          } else {
              console.error("Vendor profile creation failed:", profileError);
              throw new Error("Failed to create vendor profile.");
          }
      }
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers, signupAsVendor,
      // FIX: Provide dummy implementations for OTP methods to resolve type errors.
      sendOtp: async (phone: string) => {
        console.warn("OTP functionality not fully implemented. Simulating sending OTP to:", phone);
        // In a real app, you would use supabase.auth.signInWithOtp({ phone })
      },
      verifyOtp: async (phone: string, token: string) => {
        console.warn("OTP functionality not fully implemented. Simulating verifying OTP for:", phone, token);
        // In a real app, you would use supabase.auth.verifyOtp({ phone, token, type: 'sms' })
      }
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';

const OtpVerificationPage: React.FC = () => {
  const [otp, setOtp] = useState(['', '', '', '']);
  const [timer, setTimer] = useState(30);
  const [isVerifying, setIsVerifying] = useState(false);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const navigate = useNavigate();
  const location = useLocation();
  // FIX: These methods were missing from the context. Added dummy implementations in AuthContext.
  const { verifyOtp, sendOtp } = useAuth();

  const phone = location.state?.phone || '';

  useEffect(() => {
    if (!phone) navigate('/login');
    const interval = setInterval(() => {
        setTimer((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);
    return () => clearInterval(interval);
  }, [phone]);

  const handleChange = (index: number, value: string) => {
    if (isNaN(Number(value))) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    // Auto-focus next input
    if (value && index < 3) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleResend = async () => {
      setTimer(30);
      await sendOtp(phone);
  };

  const handleVerify = async () => {
    const code = otp.join('');
    if (code.length !== 4) return;

    setIsVerifying(true);
    try {
        await verifyOtp(phone, code);
        navigate('/home', { replace: true });
    } catch (err: any) {
        alert(err.message || "Invalid OTP");
        setOtp(['', '', '', '']);
        inputRefs.current[0]?.focus();
    } finally {
        setIsVerifying(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-6 pt-8 flex flex-col">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => navigate('/login')} className="p-2 bg-gray-50 rounded-xl active:bg-gray-100">
            <ChevronLeftIcon className="w-6 h-6 text-gray-800" />
        </button>
        <h1 className="text-xl font-black text-gray-900 uppercase italic tracking-tight">Verification</h1>
      </div>

      <div className="flex-1">
        <p className="text-sm font-medium text-gray-500 mb-8">
            We've sent a verification code to <br/>
            <span className="text-text-main font-black text-lg">+91 {phone}</span>
        </p>

        <div className="flex gap-4 mb-8 justify-center">
            {otp.map((digit, idx) => (
                <input
                    key={idx}
                    // FIX: Wrapped ref callback in braces to prevent it from returning a value, which caused a type error.
                    ref={(el) => { inputRefs.current[idx] = el; }}
                    type="tel"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleChange(idx, e.target.value)}
                    onKeyDown={(e) => handleKeyDown(idx, e)}
                    className="w-16 h-16 rounded-2xl bg-gray-50 border-2 border-gray-100 text-center text-2xl font-black text-text-main focus:border-accent focus:bg-white transition-all outline-none caret-accent"
                />
            ))}
        </div>

        <button
            onClick={handleVerify}
            disabled={otp.join('').length !== 4 || isVerifying}
            className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mb-6"
        >
            {isVerifying ? 'Verifying...' : 'Verify & Proceed'}
        </button>

        <div className="text-center">
            {timer > 0 ? (
                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Resend in 00:{timer < 10 ? `0${timer}` : timer}</p>
            ) : (
                <button 
                    onClick={handleResend}
                    className="text-accent text-xs font-black uppercase tracking-widest border-b border-accent/20 pb-0.5"
                >
                    Resend Code
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

