import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { supabase } from '../supabase.ts';
import { useNotifications } from './NotificationContext.tsx';
import { BASE_API_URL, API_HEADERS } from '../constants.ts';

interface AuthContextType {
  user: User | null;
  users: User[];
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
  fetchUsers: () => Promise<void>;
  deleteUser: (email: string) => Promise<void>;
  addUser: (userData: any) => Promise<void>;
  signupAsVendor: (name: string, email: string, pass: string, storeName: string, code: string) => Promise<void>;
  sendOtp: (phone: string) => Promise<void>;
  verifyOtp: (phone: string, token: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  auth_id: u.auth_id,
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : [],
  role: u.role || 'user',
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const stored = localStorage.getItem('vexokart-user');
      return stored ? JSON.parse(stored) : null;
    } catch (e) {
      return null;
    }
  });

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const { fetchInbox } = useNotifications();

  const fetchUsers = async () => {
    try {
      const { data, error } = await supabase.from('users').select('*');
      if (error) throw error;
      if (Array.isArray(data)) {
        setAllUsers(data.map(sanitizeUser));
      }
    } catch (error) {
      console.error("Error fetching users:", error);
    }
  };

  /**
   * Fetches the user profile from the `public.users` table after a successful Supabase Auth event.
   * This is the single source of truth for app-level user data like role and status.
   * @param authUserId - The UUID from `auth.users.id`.
   */
  const fetchProfile = async (authUserId: string) => {
    try {
      // 1. Fetch the user's profile from the public.users table.
      const { data: profileData, error: profileError } = await supabase
        .from('users')
        .select('*')
        .eq('auth_id', authUserId)
        .single();

      if (profileError && profileError.code !== 'PGRST116') { // Ignore 'PGRST116' (no rows found)
        console.error("Error fetching profile:", profileError);
        throw profileError;
      }

      // 2. If a profile exists, check its status.
      if (profileData) {
        // SECURITY CHECK: If user is marked inactive, log them out immediately and throw an error.
        if (profileData.status === 'inactive') {
          await supabase.auth.signOut();
          throw new Error('Account inactive. Please contact support.');
        }

        const appUser = sanitizeUser(profileData);
        setUser(appUser);
        localStorage.setItem('vexokart-user', JSON.stringify(appUser));
        if (appUser.role === 'admin') fetchUsers();
        fetchInbox(appUser);
        return;
      }

      // 3. RESILIENCE: Auto-provision a profile if one doesn't exist for a valid auth user.
      // This handles cases where a user was created in Auth but the profile insertion failed.
      console.warn(`Profile for auth user ${authUserId} not found. Auto-provisioning...`);
      const { data: { user: authUser } } = await supabase.auth.getUser();
      if (!authUser) throw new Error("Cannot provision profile: No active auth session found.");

      const newProfilePayload = {
        auth_id: authUser.id,
        email: authUser.email,
        name: authUser.user_metadata?.name || 'VexoKart User',
        role: 'user',
        status: 'active', // Default to active
        phone: authUser.phone || ''
      };

      const { data: insertedData, error: insertError } = await supabase
        .from('users')
        .insert(newProfilePayload)
        .select()
        .single();

      if (insertError) {
        console.error("Failed to auto-provision profile:", JSON.stringify(insertError));
        throw new Error(`Profile creation failed: ${insertError.message}`);
      }

      console.log("Profile auto-provisioned successfully.");
      const appUser = sanitizeUser(insertedData);
      setUser(appUser);
      localStorage.setItem('vexokart-user', JSON.stringify(appUser));
      fetchInbox(appUser);

    } catch (err: any) {
      console.error("Profile sync/provisioning error:", err.message);
      // Ensure user is logged out on any profile error.
      setUser(null);
      localStorage.removeItem('vexokart-user');
      throw err;
    }
  };

  useEffect(() => {
    setIsLoading(true);
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      // On SIGNED_IN or INITIAL_SESSION, fetch the user profile.
      if (session?.user) {
        await fetchProfile(session.user.id);
      } else {
        // On SIGNED_OUT, clear user data.
        setUser(null);
        localStorage.removeItem('vexokart-user');
      }
      setIsLoading(false);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  /**
   * Handles user login using Supabase Auth (email/password).
   * Relies on onAuthStateChange and fetchProfile to update application state.
   */
  const login = async (email: string, pass: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email: email.trim(),
      password: pass,
    });
    // Let the onAuthStateChange listener handle success.
    // Throw error to be caught by the UI form for immediate feedback.
    if (error) throw error;
  };

  /**
   * Handles new user registration.
   * 1. Creates the user in Supabase Auth.
   * 2. On success, inserts a corresponding profile into the `public.users` table.
   */
  const signup = async (name: string, email: string, pass: string) => {
    // 1. Create the user in the secure `auth.users` table.
    const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: pass,
        options: {
            data: { name } // Optional metadata for auth user
        }
    });
    if (error) throw error;
    if (!data.user) throw new Error("Signup successful, but no user data returned.");

    // 2. Create the corresponding public profile in `public.users`.
    const newProfilePayload = {
        auth_id: data.user.id, // Link to the auth user
        email: email.trim(),
        name: name,
        role: 'user',
        status: 'active' // New users are active by default
    };

    const { error: insertError } = await supabase.from('users').insert(newProfilePayload);

    if (insertError) {
        console.error("CRITICAL: Auth user created but profile insert failed:", JSON.stringify(insertError));
        // The auto-provisioning in fetchProfile will act as a fallback on first login.
        throw new Error(`Account created, but profile setup failed. Please try logging in.`);
    }
    // Success is handled by the onAuthStateChange listener which will call fetchProfile.
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    localStorage.removeItem('vexokart-user');
  };

  const updateUserSession = (userData: User) => {
    setUser(userData);
    localStorage.setItem('vexokart-user', JSON.stringify(userData));
  };

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    try {
        const newAddress = { ...address, id: Date.now().toString() };
        const updatedAddresses = [...user.addresses, newAddress];

        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.map(a => a.id === address.id ? address : a);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    try {
        const updatedAddresses = user.addresses.filter(a => a.id !== addressId);
        const { error } = await supabase
            .from('users')
            .update({ addresses: updatedAddresses })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, addresses: updatedAddresses });
    } catch(e) { console.error(e); }
  };

  const addToWishlist = async (productId: number) => {
    if (!user) return;
    if (user.wishlist.includes(productId)) return;
    try {
        const updated = [...user.wishlist, productId];
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    try {
        const updated = user.wishlist.filter(id => id !== productId);
        const { error } = await supabase
            .from('users')
            .update({ wishlist: updated })
            .eq('id', user.id);

        if (!error) updateUserSession({ ...user, wishlist: updated });
    } catch(e) { console.error(e); }
  };

  const isInWishlist = (productId: number) => {
    return user ? user.wishlist.includes(productId) : false;
  };

  const deleteUser = async (email: string) => {
      console.warn("User deletion requires admin privileges via backend.");
  };

  const addUser = async (userData: any) => {
      await signup(userData.name, userData.email, userData.pass || '123456');
  };

  const signupAsVendor = async (name: string, email: string, pass: string, storeName: string, code: string) => {
      const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: pass,
        options: { data: { name } }
      });
      if (error) throw error;

      if (data.user) {
          const newProfilePayload = {
              auth_id: data.user.id,
              email: email.trim(),
              name,
              role: 'vendor',
              status: 'active'
          };

          const { error: profileError } = await supabase.from('users').insert(newProfilePayload);

          if (!profileError) {
              const { data: userData } = await supabase.from('users').select('id').eq('auth_id', data.user.id).single();

              if (userData) {
                  await supabase.from('vendors').insert([{
                      user_id: userData.id,
                      store_name: storeName,
                      owner_name: name,
                      email: email.trim(),
                      status: 'pending',
                      phone: ''
                  }]);
              }
          } else {
              console.error("Vendor profile creation failed:", profileError);
              throw new Error("Failed to create vendor profile.");
          }
      }
  };

  return (
    <AuthContext.Provider value={{ 
      user, users: allUsers, isLoading, isAuthenticated: !!user, 
      login, signup, logout, addUser, addAddress, updateAddress, 
      deleteAddress, deleteUser, addToWishlist, removeFromWishlist, 
      isInWishlist, updateUserSession, fetchUsers, signupAsVendor,
      sendOtp: async (phone: string) => { console.warn("OTP functionality not implemented."); },
      verifyOtp: async (phone: string, token: string) => { console.warn("OTP functionality not implemented."); }
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const LoginPage: React.FC = () => {
  const location = useLocation();
  const defaultTab = location.state?.defaultTab === 'signup' ? 'signup' : 'login';
  const [activeTab, setActiveTab] = useState<'login' | 'signup'>(defaultTab);

  const { login, signup, isAuthenticated, user } = useAuth();
  const navigate = useNavigate();

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (isAuthenticated && user) {
      const from = user.role === 'admin' ? '/admin' : user.role === 'vendor' ? '/vendor' : '/home';
      navigate(from, { replace: true });
    }
  }, [isAuthenticated, user, navigate]);

  const resetForm = () => {
    setName('');
    setEmail('');
    setPassword('');
    setError('');
  };

  const handleTabChange = (tab: 'login' | 'signup') => {
    setActiveTab(tab);
    resetForm();
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError("Please fill in all fields.");
      return;
    }
    setIsSubmitting(true);
    setError('');
    try {
      await login(email.trim(), password);
      // On success, the AuthContext's onAuthStateChange listener will handle redirection.
    } catch (err: any) {
      // Catch specific errors thrown from AuthContext for better user feedback.
      if (err.message && err.message.includes('inactive')) {
        setError('Account inactive. Please contact support.');
      } else {
        // Default error for "Invalid login credentials" from Supabase or other issues.
        setError("Invalid email or password");
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email || !password) {
      setError("All fields are required.");
      return;
    }
    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }
    setIsSubmitting(true);
    setError('');
    try {
      await signup(name.trim(), email.trim(), password);
      // On success, the AuthContext's onAuthStateChange listener will handle login & redirection.
    } catch (err: any) {
      setError(err.message || "Signup failed. The email might already be in use.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const inputClasses = "w-full mt-1 bg-surface border border-border rounded-xl p-3 text-sm font-bold text-text-main placeholder-text-muted outline-none focus:border-accent focus:ring-2 focus:ring-accent/20 transition-all";

  return (
    <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-md">
        <div className="text-center mb-6">
          <h1 className="text-4xl font-black text-text-main italic uppercase tracking-tighter">
            Vexo<span className="text-accent">Kart</span>
          </h1>
          <p className="text-text-muted text-xs font-bold uppercase tracking-[0.3em] mt-1">Secure Portal</p>
        </div>

        <div className="bg-white rounded-3xl shadow-premium border border-border p-6 md:p-8">
          {/* Tab Switcher */}
          <div className="relative mb-8 bg-surface rounded-full p-1 flex">
            <div
              className="absolute top-1 bottom-1 bg-white rounded-full shadow-md transition-all duration-300 ease-in-out"
              style={{
                width: 'calc(50% - 4px)',
                left: activeTab === 'login' ? '4px' : 'calc(50% + 4px)',
              }}
            />
            <button
              onClick={() => handleTabChange('login')}
              className={`relative z-10 w-1/2 py-2 text-center text-xs font-black uppercase tracking-widest transition-colors duration-300 ${activeTab === 'login' ? 'text-text-main' : 'text-text-muted'}`}
            >
              Login
            </button>
            <button
              onClick={() => handleTabChange('signup')}
              className={`relative z-10 w-1/2 py-2 text-center text-xs font-black uppercase tracking-widest transition-colors duration-300 ${activeTab === 'signup' ? 'text-text-main' : 'text-text-muted'}`}
            >
              Sign Up
            </button>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold text-center">
              {error}
            </div>
          )}

          {activeTab === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-5 animate-in fade-in duration-500">
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Email Address</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required className={inputClasses} />
              </div>
              <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-xl font-black uppercase tracking-widest text-sm shadow-lg shadow-accent/20 active:scale-95 transition-all disabled:opacity-50">
                {isSubmitting ? 'Verifying...' : 'Secure Login'}
              </button>
            </form>
          ) : (
            <form onSubmit={handleSignup} className="space-y-5 animate-in fade-in duration-500">
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Full Name</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Email Address</label>
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className={inputClasses} />
              </div>
              <div>
                  <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required placeholder="Min. 6 characters" className={inputClasses} />
              </div>
              <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-white py-4 rounded-xl font-black uppercase tracking-widest text-sm shadow-lg shadow-accent/20 active:scale-95 transition-all disabled:opacity-50">
                {isSubmitting ? 'Creating Account...' : 'Create Account'}
              </button>
            </form>
          )}
          <div className="text-center mt-6">
            <Link to="/forgot-password" className="text-xs font-bold text-text-muted hover:text-accent transition-colors">Forgot Password?</Link>
          </div>
        </div>
        <div className="text-center mt-6">
          <button onClick={() => navigate('/home')} className="text-xs font-bold text-text-muted hover:text-accent transition-colors">
            Continue as Guest
          </button>
        </div>
      </div>
    </div>
  );
};
