import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User, Address } from '../types.ts';
import { supabase } from '../supabase.ts';
import { useNotifications } from './NotificationContext.tsx';

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  login: (email: string, pass: string) => Promise<void>;
  signup: (name: string, email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  addAddress: (address: Omit<Address, 'id'>) => Promise<void>;
  updateAddress: (address: Address) => Promise<void>;
  deleteAddress: (addressId: string) => Promise<void>;
  addToWishlist: (productId: number) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  updateUserSession: (userData: User) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const sanitizeUser = (u: any): User => ({
  ...u,
  id: u.id ? String(u.id) : '',
  auth_uid: u.auth_uid,
  addresses: Array.isArray(u.addresses) ? u.addresses : [],
  wishlist: Array.isArray(u.wishlist) ? u.wishlist : [],
  recentlyViewed: Array.isArray(u.recentlyViewed) ? u.recentlyViewed : [],
  role: u.role || 'user',
});

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const { fetchInbox } = useNotifications();

  /**
   * Fetches the profile from public.users using the auth.users.id
   */
  const fetchProfile = async (authUserId: string) => {
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('auth_uid', authUserId)
        .single();

      if (error) {
        console.error("Profile fetch error:", error.message);
        throw error;
      }

      if (data) {
        const appUser = sanitizeUser(data);
        setUser(appUser);
        fetchInbox(appUser);
      }
    } catch (err) {
      setUser(null);
      throw err;
    }
  };

  useEffect(() => {
    // Check current session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        fetchProfile(session.user.id).finally(() => setIsLoading(false));
      } else {
        setIsLoading(false);
      }
    });

    // Listen for Auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session?.user) {
        await fetchProfile(session.user.id);
      } else {
        setUser(null);
      }
      setIsLoading(false);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  /**
   * Signup: Supabase Auth -> public.users
   */
  const signup = async (name: string, email: string, pass: string) => {
    // 1. Create Auth Account
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email,
      password: pass,
    });

    if (authError) throw authError;
    if (!authData.user) throw new Error("Signup successful, but no identity returned.");

    // 2. Create Public Profile record
    const { error: profileError } = await supabase.from('users').insert({
      auth_uid: authData.user.id,
      name,
      email,
      role: 'user',
      status: 'active'
    });

    if (profileError) {
      console.error("Profile creation failed:", profileError.message);
      // Even if profile fails here, onAuthStateChange/login will try to fetch it later
    }
  };

  /**
   * Login: Simple Supabase Auth call
   */
  const login = async (email: string, pass: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password: pass,
    });

    if (error) throw error;
    // Success is handled by onAuthStateChange listener
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  const updateUserSession = (userData: User) => setUser(userData);

  const addAddress = async (address: Omit<Address, 'id'>) => {
    if (!user) return;
    const newAddress = { ...address, id: Date.now().toString() };
    const updated = [...user.addresses, newAddress];
    const { error } = await supabase.from('users').update({ addresses: updated }).eq('id', user.id);
    if (!error) setUser({ ...user, addresses: updated });
  };

  const updateAddress = async (address: Address) => {
    if (!user) return;
    const updated = user.addresses.map(a => a.id === address.id ? address : a);
    const { error } = await supabase.from('users').update({ addresses: updated }).eq('id', user.id);
    if (!error) setUser({ ...user, addresses: updated });
  };

  const deleteAddress = async (addressId: string) => {
    if (!user) return;
    const updated = user.addresses.filter(a => a.id !== addressId);
    const { error } = await supabase.from('users').update({ addresses: updated }).eq('id', user.id);
    if (!error) setUser({ ...user, addresses: updated });
  };

  const addToWishlist = async (productId: number) => {
    if (!user || user.wishlist.includes(productId)) return;
    const updated = [...user.wishlist, productId];
    const { error } = await supabase.from('users').update({ wishlist: updated }).eq('id', user.id);
    if (!error) setUser({ ...user, wishlist: updated });
  };

  const removeFromWishlist = async (productId: number) => {
    if (!user) return;
    const updated = user.wishlist.filter(id => id !== productId);
    const { error } = await supabase.from('users').update({ wishlist: updated }).eq('id', user.id);
    if (!error) setUser({ ...user, wishlist: updated });
  };

  const isInWishlist = (productId: number) => user?.wishlist.includes(productId) || false;

  return (
    <AuthContext.Provider value={{ 
      user, isLoading, isAuthenticated: !!user, 
      login, signup, logout, addAddress, updateAddress, deleteAddress, 
      addToWishlist, removeFromWishlist, isInWishlist, updateUserSession 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const LoginPage: React.FC = () => {
  const { login, signup, user, isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [activeTab, setActiveTab] = useState<'login' | 'signup'>(location.state?.defaultTab || 'login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [showSecurityUpdate, setShowSecurityUpdate] = useState(false);
  const [loading, setLoading] = useState(false);

  // Redirection Logic based on Role
  useEffect(() => {
    if (isAuthenticated && user) {
      if (user.role === 'admin') navigate('/admin');
      else if (user.role === 'vendor') navigate('/vendor');
      else navigate('/home');
    }
  }, [isAuthenticated, user, navigate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setShowSecurityUpdate(false);
    setLoading(true);

    try {
      if (activeTab === 'signup') {
        if (!name) throw new Error("Name is required");
        await signup(name, email, password);
      } else {
        await login(email, password);
      }
    } catch (err: any) {
      // Catch login failures specifically to show the security update notice
      if (activeTab === 'login') {
        setShowSecurityUpdate(true);
      } else {
        setError(err.message || "Authentication failed. Please try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  const inputClasses = "w-full mt-1 bg-surface border border-border rounded-xl p-3 text-sm font-bold text-text-main placeholder-text-muted outline-none focus:border-accent transition-all";

  return (
    <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-black text-text-main italic uppercase tracking-tighter">
            Vexo<span className="text-accent">Kart</span>
          </h1>
          <p className="text-text-muted text-[10px] font-black uppercase tracking-[0.4em] mt-2">Secure Gateway</p>
        </div>

        <div className="bg-white rounded-3xl shadow-premium border border-border p-8 relative overflow-hidden">

          {/* Security Update Overlay */}
          {showSecurityUpdate && (
            <div className="absolute inset-0 bg-white z-20 flex flex-col items-center justify-center p-8 text-center animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="w-16 h-16 bg-orange-50 rounded-2xl flex items-center justify-center mb-4 text-accent">
                    <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                </div>
                <h3 className="text-xl font-black text-text-main uppercase italic tracking-tight">Security Update</h3>
                <p className="text-gray-500 text-sm mt-3 leading-relaxed">
                    We've upgraded our security systems. <br/>
                    If you created your account earlier, please <b>reset your password</b> once to continue.
                </p>
                <div className="w-full space-y-3 mt-8">
                    <Link 
                        to="/forgot-password" 
                        state={{ email }}
                        className="block w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all"
                    >
                        Reset Password
                    </Link>
                    <button 
                        onClick={() => setShowSecurityUpdate(false)}
                        className="text-gray-400 font-bold uppercase text-[10px] tracking-widest hover:text-gray-600 transition-colors"
                    >
                        Try Login Again
                    </button>
                </div>
            </div>
          )}

          <div className="flex bg-surface p-1 rounded-full mb-8">
            <button
              onClick={() => { setActiveTab('login'); setError(''); setShowSecurityUpdate(false); }}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-full transition-all ${activeTab === 'login' ? 'bg-white text-text-main shadow-sm' : 'text-text-muted'}`}
            >
              Login
            </button>
            <button
              onClick={() => { setActiveTab('signup'); setError(''); setShowSecurityUpdate(false); }}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-full transition-all ${activeTab === 'signup' ? 'bg-white text-text-main shadow-sm' : 'text-text-muted'}`}
            >
              Signup
            </button>
          </div>

          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-xl text-red-500 text-xs font-bold text-center italic">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5">
            {activeTab === 'signup' && (
              <div>
                <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Full Name</label>
                <input
                  type="text"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className={inputClasses}
                  placeholder="e.g. John Doe"
                />
              </div>
            )}
            <div>
              <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Email Address</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className={inputClasses}
                placeholder="name@example.com"
              />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-text-muted tracking-widest ml-2">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={inputClasses}
                placeholder="••••••••"
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-accent text-white py-4 rounded-2xl font-black uppercase tracking-[0.2em] text-[11px] shadow-xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50"
            >
              {loading ? 'Processing...' : activeTab === 'login' ? 'Secure Login' : 'Create Account'}
            </button>
          </form>
        </div>

        <div className="text-center mt-8 space-y-4">
            <Link to="/forgot-password" size="sm" className="text-[10px] font-black uppercase text-text-muted tracking-widest block hover:text-accent transition-colors">
                Forgot Password?
            </Link>
            <button onClick={() => navigate('/home')} className="text-[10px] font-black uppercase text-text-muted tracking-widest border-b border-transparent hover:border-text-muted pb-1 transition-all">
                Continue as Guest
            </button>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { supabase } from '../supabase';
import { ChevronLeftIcon } from '../components/icons/ChevronLeftIcon';

const ForgotPasswordPage: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [email, setEmail] = useState(location.state?.email || '');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleReset = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
        setError("Please enter your email address");
        return;
    }

    setIsSubmitting(true);
    setError('');
    setMessage('');

    // The redirect URL should point to your hosted site's update-password route
    const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/#/update-password`,
    });

    if (resetError) {
        setError(resetError.message);
    } else {
        setMessage("Password reset link sent! Please check your email inbox (and spam folder) to set a new password.");
    }

    setIsSubmitting(false);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 pt-12 animate-in fade-in duration-300">

      <div className="mb-12">
        <button onClick={() => navigate('/login')} className="mb-6 inline-flex items-center gap-2 text-text-muted text-xs font-black uppercase tracking-widest hover:text-text-main transition-colors">
            <ChevronLeftIcon className="w-4 h-4" />
            Back to Login
        </button>
        <h2 className="text-3xl font-black text-text-main italic uppercase tracking-tighter mb-2 leading-none">Recover Access</h2>
        <p className="text-text-muted text-sm font-medium mt-3">Enter your email to receive a secure recovery link.</p>
      </div>

      <div className="flex-1 max-w-md mx-auto w-full">
        {error && (
            <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-2xl text-red-500 text-xs font-bold flex items-center gap-3">
                <div className="w-5 h-5 bg-red-100 rounded-full flex items-center justify-center shrink-0">!</div>
                {error}
            </div>
        )}

        {message && (
            <div className="mb-8 p-6 bg-green-50 border border-green-100 rounded-3xl text-green-600 text-sm font-bold animate-in zoom-in duration-300">
                <div className="flex items-center gap-3 mb-2">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    <span className="uppercase tracking-widest text-[10px]">Email Dispatched</span>
                </div>
                {message}
            </div>
        )}

        <form onSubmit={handleReset} className="space-y-6">
            <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest ml-2 italic">Primary Email Address</label>
                <div className="bg-gray-50 border border-gray-100 rounded-2xl p-2 transition-all focus-within:border-accent focus-within:ring-8 focus-within:ring-accent/5">
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="name@example.com"
                        className="w-full bg-transparent p-4 text-base font-bold text-text-main placeholder-gray-300 outline-none"
                        required
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={isSubmitting || !!message}
                className="w-full bg-accent text-white py-5 rounded-[2rem] font-black uppercase tracking-widest text-[11px] shadow-2xl shadow-accent/20 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none mt-4"
            >
                {isSubmitting ? 'Authenticating...' : 'Dispatch Recovery Link'}
            </button>
        </form>

        {!message && (
            <div className="mt-12 p-6 bg-surface rounded-3xl border border-border text-center">
                <p className="text-[10px] font-black text-text-muted uppercase tracking-widest">Need help?</p>
                <p className="text-xs text-text-secondary mt-2">If you no longer have access to this email, please contact our support desk.</p>
            </div>
        )}
      </div>
    </div>
  );
};

