import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
import { User as Profile } from '../types.ts'; // Renamed to Profile for clarity
import { supabase } from '../supabase.ts';

interface AuthContextType {
  user: Profile | null;
  isLoading: boolean;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<Profile | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Start with loading true
    setIsLoading(true);

    // Check for initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        // If a session exists, fetch the associated profile
        supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single()
          .then(({ data, error }) => {
            if (error) {
              console.error('Error fetching profile on initial load:', error);
              setUser(null);
            } else {
              setUser(data);
            }
          })
          .finally(() => {
            setIsLoading(false);
          });
      } else {
        // No session, not loading
        setIsLoading(false);
      }
    });

    // Set up the listener for auth state changes (login, logout, etc.)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        setIsLoading(true);
        if (event === 'SIGNED_IN' && session) {
          // When a user signs in, fetch their profile from the 'profiles' table
          const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', session.user.id)
            .single();

          if (error) {
            console.error('Error fetching profile on SIGNED_IN:', error);
            setUser(null);
          } else {
            setUser(data);
          }
        } else if (event === 'SIGNED_OUT') {
          // When a user signs out, clear the user state
          setUser(null);
        }
        setIsLoading(false);
      }
    );

    // Cleanup subscription on component unmount
    return () => {
      subscription.unsubscribe();
    };
  }, []);

  // Logout function
  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null); // Instantly clear user state on logout call
  };

  const value = {
    user,
    isLoading,
    logout,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../components/Header.tsx';
import ProductCard from '../components/ProductCard.tsx';
import BannerCarousel from '../components/BannerCarousel.tsx';
import { supabase } from '../supabase.ts';
import { Product, Category, Banner } from '../types.ts';
import { ProductCardSkeleton } from '../components/Skeleton.tsx';

const FETCH_TIMEOUT = 10000; // 10 seconds

const HomePage: React.FC = () => {
  const navigate = useNavigate();
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Ref to prevent state updates on unmounted component
  const isMounted = useRef(true);
  // Ref to track retry attempts
  const retryAttempt = useRef(0);

  const fetchData = useCallback(async (isRetry = false) => {
    if (!isMounted.current) return;

    setIsLoading(true);
    setError(null);

    // Use AbortController for fetch timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => {
      controller.abort();
    }, FETCH_TIMEOUT);

    try {
      // Fetch all data in parallel
      const [productsRes, categoriesRes, bannersRes] = await Promise.all([
        supabase.from('products').select('*').eq('is_active', true).limit(20).order('created_at', { ascending: false }),
        supabase.from('categories').select('*').order('name', { ascending: true }),
        supabase.from('banners').select('*').eq('status', true).order('display_order', { ascending: true })
      ]);

      clearTimeout(timeoutId); // Clear timeout if fetches succeed

      if (!isMounted.current) return;

      // Handle Products
      if (productsRes.error) throw new Error(`Products Fetch Failed: ${productsRes.error.message}`);
      setProducts(productsRes.data || []);

      // Handle Categories (optional, don't throw error if it fails)
      if (categoriesRes.error) console.warn("Could not fetch categories:", categoriesRes.error.message);
      else setCategories(categoriesRes.data || []);

      // Handle Banners (optional)
      if (bannersRes.error) console.warn("Could not fetch banners:", bannersRes.error.message);
      else setBanners(bannersRes.data || []);

    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.name === 'AbortError') {
        setError('Request timed out. Please check your connection.');
      } else {
        setError(err.message || 'Failed to load data.');
      }

      // Retry logic: attempt only once
      if (!isRetry && retryAttempt.current < 1) {
        retryAttempt.current += 1;
        console.log('Fetch failed, retrying once...');
        setTimeout(() => fetchData(true), 2000); // Wait 2s before retry
      }
    } finally {
      if (isMounted.current) {
        setIsLoading(false);
      }
    }
  }, []);

  useEffect(() => {
    isMounted.current = true;
    fetchData();

    // Cleanup function
    return () => {
      isMounted.current = false;
    };
  }, [fetchData]);

  const handleRetry = () => {
    retryAttempt.current = 0; // Reset retry counter
    fetchData();
  };

  return (
    <div className="bg-surface min-h-screen">
      <Header />

      <div className="p-3">
        {banners.length > 0 ? (
           <BannerCarousel banners={banners.map(b => b.image_url)} />
        ) : (
           <div className="w-full h-40 bg-gray-200 rounded-2xl animate-pulse" />
        )}
      </section>

      {categories.length > 0 && (
        <section className="bg-white py-3 my-3 rounded-xl shadow-sm">
          <div className="flex space-x-4 overflow-x-auto px-4 no-scrollbar">
            {categories.map(category => (
                <div 
                    key={category.id}
                    onClick={() => navigate(`/products?category=${category.slug}`)}
                    className="flex-shrink-0 flex flex-col items-center gap-2 cursor-pointer group"
                >
                    <div className="w-16 h-16 rounded-full overflow-hidden border-2 border-border group-hover:border-primary transition-all">
                        <img src={category.image_url || 'https://placehold.co/100x100'} alt={category.name} className="w-full h-full object-cover" />
                    </div>
                    <span className="text-[11px] font-medium text-text-secondary group-hover:text-primary transition-colors">{category.name}</span>
                </div>
            ))}
          </div>
        </section>
      )}

      <section className="p-3">
        <h2 className="text-lg font-bold text-text-main mb-4">New Arrivals</h2>

        {isLoading && products.length === 0 ? (
          <div className="grid grid-cols-2 gap-3">
            {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
          </div>
        ) : error && products.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-2xl shadow-sm">
            <h3 className="font-bold text-red-500">Oops! Something went wrong.</h3>
            <p className="text-sm text-text-muted mt-2">{error}</p>
            <button
              onClick={handleRetry}
              className="mt-6 bg-primary text-white font-bold py-2 px-6 rounded-lg text-sm"
            >
              Retry
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {products.map(product => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
};

export default HomePage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import Header from '../components/Header.tsx';
import ProductCard from '../components/ProductCard.tsx';
import { supabase } from '../supabase.ts';
import { Product, Category } from '../types.ts';
import { ProductCardSkeleton } from '../components/Skeleton.tsx';

const FETCH_TIMEOUT = 10000; // 10 seconds

const ProductsPage: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [searchParams, setSearchParams] = useSearchParams();
  const categorySlug = searchParams.get('category');
  const searchQuery = searchParams.get('q');

  const isMounted = useRef(true);
  const retryAttempt = useRef(0);

  const fetchData = useCallback(async (isRetry = false) => {
    if (!isMounted.current) return;
    setIsLoading(true);
    setError(null);

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), FETCH_TIMEOUT);

    try {
      // Fetch categories first (or in parallel)
      const { data: catData, error: catError } = await supabase.from('categories').select('*');
      if (catError) console.warn("Could not fetch categories:", catError.message);
      if (isMounted.current && catData) setCategories(catData);

      // Build product query
      let query = supabase.from('products').select('*, category:categories(name, slug)').eq('is_active', true);

      if (categorySlug) {
        const targetCategory = (catData || categories).find(c => c.slug === categorySlug);
        if (targetCategory) {
          query = query.eq('category_id', targetCategory.id);
        }
      }

      if (searchQuery) {
        query = query.ilike('name', `%${searchQuery}%`);
      }

      const { data: prodData, error: prodError } = await query;

      clearTimeout(timeoutId);
      if (!isMounted.current) return;

      if (prodError) throw new Error(`Products fetch failed: ${prodError.message}`);
      setProducts(prodData || []);

    } catch (err: any) {
      clearTimeout(timeoutId);
      if (err.name === 'AbortError') {
        setError('Request timed out. Please check your connection.');
      } else {
        setError(err.message || 'Failed to load products.');
      }
      if (!isRetry && retryAttempt.current < 1) {
        retryAttempt.current += 1;
        setTimeout(() => fetchData(true), 2000);
      }
    } finally {
      if (isMounted.current) setIsLoading(false);
    }
  }, [categorySlug, searchQuery]);

  useEffect(() => {
    isMounted.current = true;
    retryAttempt.current = 0;
    fetchData();
    return () => { isMounted.current = false; };
  }, [fetchData]);

  const handleCategorySelect = (slug: string | null) => {
    const newParams = new URLSearchParams(searchParams);
    if (slug) {
      newParams.set('category', slug);
    } else {
      newParams.delete('category');
    }
    setSearchParams(newParams);
  };

  return (
    <div className="bg-surface min-h-screen">
      <Header title="Our Products" showSearch />
      <div className="p-4 max-w-7xl mx-auto space-y-6">
        <div className="flex space-x-2 overflow-x-auto pb-2 no-scrollbar">
          <button
            onClick={() => handleCategorySelect(null)}
            className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap ${!categorySlug ? 'bg-primary text-white' : 'bg-white text-text-secondary'}`}
          >
            All Items
          </button>
          {categories.map(category => (
            <button
              key={category.id}
              onClick={() => handleCategorySelect(category.slug)}
              className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap ${categorySlug === category.slug ? 'bg-primary text-white' : 'bg-white text-text-secondary'}`}
            >
              {category.name}
            </button>
          ))}
        </div>

        {isLoading ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
            {[...Array(8)].map((_, i) => <ProductCardSkeleton key={i} />)}
          </div>
        ) : error ? (
           <div className="text-center py-20 bg-white rounded-2xl shadow-sm">
            <h3 className="font-bold text-red-500">Oops! Something went wrong.</h3>
            <p className="text-sm text-text-muted mt-2">{error}</p>
            <button onClick={() => fetchData()} className="mt-6 bg-primary text-white font-bold py-2 px-6 rounded-lg text-sm">Retry</button>
          </div>
        ) : products.length > 0 ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
            {products.map(product => <ProductCard key={product.id} product={product} />)}
          </div>
        ) : (
          <div className="col-span-full py-32 flex flex-col items-center bg-white rounded-2xl shadow-sm">
            <h3 className="text-xl font-bold text-text-main">No Products Found</h3>
            <p className="text-text-muted mt-2 text-sm">Try adjusting your search or filter.</p>
          </div>
        )}
      </div>
    </div>
  );
};

