    return () => timers.forEach(clearTimeout);
  }, [onFinish]);

  return (
    <div 
      className={`fixed inset-0 z-[9999] flex flex-col items-center justify-center overflow-hidden transition-opacity duration-700 ease-out ${phase === 3 ? 'opacity-0' : 'opacity-100'}`}
