export const generateInvoicePDF = async (order: Order): Promise<jsPDF> => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const subtotal = order.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const gstAmount = subtotal * 0.18;
  const finalTotal = subtotal + gstAmount;
  // Fix: Use correct properties from Order and OrderItem types
  const primarySeller = order.seller_name || order.items[0]?.vendor_name || 'VexoKart Authorized Vendor';

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(22);
  doc.text('TAX INVOICE', 15, 20);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Invoice #: INV-${order.id}`, 195, 20, { align: 'right' });
  doc.text(`Date: ${new Date(order.created_at).toLocaleDateString()}`, 195, 25, { align: 'right' });

  doc.setLineWidth(0.5);
  doc.line(15, 30, 195, 30);

  // Seller and Buyer
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.text('SOLD BY:', 15, 40);
  doc.setFont('helvetica', 'normal');
  doc.text(primarySeller, 15, 45);
  doc.text(['Warehouse Node-A1', 'Industrial Estate', 'GSTIN: 27VEXOK7788A1Z5'], 15, 50);

  doc.setFont('helvetica', 'bold');
  doc.text('BILLED TO:', 110, 40);
  doc.setFont('helvetica', 'normal');
  // Fix: Use correct property 'shipping_address'
  doc.text(order.shipping_address?.fullName || 'Valued Customer', 110, 45);
  doc.text([
    order.shipping_address?.street || '',
    `${order.shipping_address?.city || ''}, ${order.shipping_address?.state || ''} — ${order.shipping_address?.zip || ''}`,
    `Phone: ${order.shipping_address?.phone || ''}`
  ], 110, 50);

  doc.line(15, 75, 195, 75);

  // Table Header
  doc.setFont('helvetica', 'bold');
  doc.text('Description', 15, 82);
  doc.text('Qty', 140, 82, { align: 'center' });
  doc.text('Price (INR)', 195, 82, { align: 'right' });
  doc.line(15, 85, 195, 85);

  // Items
  doc.setFont('helvetica', 'normal');
  let currentY = 92;
  order.items.forEach(item => {
    doc.text(item.name.substring(0, 50), 15, currentY);
    doc.text(String(item.quantity), 140, currentY, { align: 'center' });
    doc.text((item.price * item.quantity).toLocaleString(), 195, currentY, { align: 'right' });
    currentY += 10;
  });

  doc.line(15, currentY, 195, currentY);
  currentY += 10;

  // Totals
  doc.text('Subtotal', 140, currentY);
  doc.text(subtotal.toLocaleString(), 195, currentY, { align: 'right' });
  currentY += 7;
  doc.text('GST (18%)', 140, currentY);
  doc.text(gstAmount.toLocaleString(), 195, currentY, { align: 'right' });
  currentY += 10;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.text('Grand Total', 140, currentY);
  doc.text(`INR ${finalTotal.toLocaleString()}`, 195, currentY, { align: 'right' });

  // Footer
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(150);
  doc.text('This is a computer generated invoice and does not require a signature.', 105, 280, { align: 'center' });
  doc.text('Generated by VexoKart Fulfillment Protocol', 105, 285, { align: 'center' });

  return doc;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useOrders } from '../../context/OrderContext';
import { useVendors } from '../../context/VendorContext';
import { ChevronLeftIcon } from '../../components/icons/ChevronLeftIcon';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { OrderStatus } from '../../types';

const VendorOrderDetailPage: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { getOrderById, updateOrderStatus, generateShippingLabel, isLabelGenerating } = useOrders();
    const { currentVendor } = useVendors();

    const [isProcessing, setIsProcessing] = useState(false);

    const order = useMemo(() => id ? getOrderById(id) : null, [id, getOrderById]);
    const vid = currentVendor ? String(currentVendor.id) : '';

    const vendorItems = useMemo(() => {
        return order?.items?.filter((item: any) => String(item.vendor_id) === vid) || [];
    }, [order, vid]);

    const vendorSubtotal = vendorItems.reduce((sum: number, item: any) => sum + (Number(item.price || 0) * Number(item.quantity || 0)), 0);

    const handleAction = async (newStatus: OrderStatus, note: string) => {
        if (!order || isProcessing) return;
        setIsProcessing(true);
        try {
            await updateOrderStatus(order.id, newStatus, { note });
        } finally {
            setIsProcessing(false);
        }
    };

    if (!order) return null;

    return (
        <div className="min-h-screen bg-[#F8F9FA] pb-32 animate-in fade-in duration-300">
            {/* Header */}
            <div className="sticky top-0 z-40 bg-white border-b border-gray-100 p-4 flex items-center gap-3 shadow-sm">
                <button onClick={() => navigate(-1)} className="p-1 -ml-1">
                    <ChevronLeftIcon className="w-6 h-6 text-gray-800" />
                </button>
                <h1 className="text-base font-black text-gray-900 uppercase tracking-tight italic">Order Workflow</h1>
            </div>

            <div className="p-4 space-y-4">
                {/* ID Card */}
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex justify-between items-end">
                    <div>
                        <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-1">Consignment ID</p>
                        <h2 className="text-xl font-black font-mono text-gray-900">#{order.id?.slice(0, 10)}...</h2>
                    </div>
                    <div className="text-right">
                        <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-full border ${
                            order.status === 'Delivered' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-accent/5 text-accent border-accent/10'
                        }`}>
                            {order.status}
                        </span>
                    </div>
                </div>

                {/* Buyer & Address */}
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm">
                    <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4 italic">Delivery Node</h3>
                    <div className="space-y-3">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-surface rounded-2xl flex items-center justify-center text-gray-400">
                                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                            </div>
                            <div>
                                <p className="text-sm font-black text-gray-900 uppercase italic leading-none">{order.shipping_address?.fullName}</p>
                                <p className="text-[10px] font-bold text-accent mt-1 tracking-tight">PH: {order.shipping_address?.phone?.replace(/(\d{4})$/, '****')}</p>
                            </div>
                        </div>
                        <div className="pt-3 border-t border-gray-50">
                            <p className="text-xs font-bold text-gray-600 uppercase leading-relaxed tracking-tighter">
                                {order.shipping_address?.street}<br/>
                                {order.shipping_address?.city}, {order.shipping_address?.state} — {order.shipping_address?.zip}
                            </p>
                        </div>
                    </div>
                </div>

                {/* Items */}
                <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm">
                    <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4 italic">Managed Items</h3>
                    <div className="space-y-4">
                        {vendorItems.map((item: any, i: number) => (
                            <div key={i} className="flex gap-4 border-b border-gray-50 pb-4 last:border-0 last:pb-0">
                                <img src={item.image} className="w-14 h-14 rounded-xl object-contain bg-gray-50 border border-gray-100" alt="" />
                                <div className="flex-grow">
                                    <p className="text-xs font-black text-gray-900 line-clamp-1 uppercase italic">{item.name}</p>
                                    <div className="flex gap-2 mt-1">
                                        {item.size && <span className="text-[8px] font-black bg-gray-100 px-1.5 py-0.5 rounded text-gray-500 uppercase">S: {item.size}</span>}
                                        {item.color && <span className="text-[8px] font-black bg-gray-100 px-1.5 py-0.5 rounded text-gray-500 uppercase">C: {item.color}</span>}
                                    </div>
                                    <div className="flex justify-between items-end mt-1">
                                        <p className="text-[10px] font-black text-gray-400 uppercase">QTY: {item.quantity}</p>
                                        <p className="text-xs font-black text-gray-900 italic">₹{(item.price || 0).toLocaleString()}</p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Price Breakup */}
                <div className="bg-gray-900 text-white p-6 rounded-[2.5rem] shadow-xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-6 opacity-10">
                        <svg className="w-20 h-20" fill="currentColor" viewBox="0 0 24 24"><path d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </div>
                    <h3 className="text-[10px] font-black uppercase text-gray-500 tracking-widest mb-4">Financial Settlement</h3>
                    <div className="space-y-2">
                        <div className="flex justify-between text-xs font-bold uppercase tracking-tight">
                            <span className="text-gray-400">Merchant Share</span>
                            <span>₹{(vendorSubtotal || 0).toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between text-xs font-bold uppercase tracking-tight">
                            <span className="text-gray-400">Logistics Fee</span>
                            <span className="text-green-400">FREE</span>
                        </div>
                        <div className="pt-4 border-t border-white/10 flex justify-between items-end">
                            <div className="flex flex-col">
                                <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Credited on Delivery</span>
                                <span className="text-2xl font-black italic tracking-tighter">₹{(vendorSubtotal || 0).toLocaleString()}</span>
                            </div>
                            <span className="text-[9px] font-black uppercase bg-white/10 px-2 py-1 rounded-lg italic">{order.payment_method}</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Workflow Actions (Sticky) - FIXED FOR ALL DEVICES */}
            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/95 backdrop-blur-md border-t border-gray-100 flex flex-col gap-3 z-[110] shadow-[0_-10px_30px_rgba(0,0,0,0.08)]">
                 {order.status === 'Placed' && (
                    <button 
                      // Fix: Use capitalized status value
                      onClick={() => handleAction('Confirmed', 'Merchant accepted the commitment.')}
                      disabled={isProcessing}
                      className="w-full h-14 bg-[#F43397] text-white rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-lg shadow-[#F43397]/20 active:scale-95 transition-all flex items-center justify-center"
                    >
                      {isProcessing ? 'SYNCHRONIZING...' : 'ACCEPT ORDER'}
                    </button>
                 )}
                 {order.status === 'Confirmed' && (
                    <button 
                      // Fix: Use capitalized status value
                      onClick={() => handleAction('Packed', 'Items verified and packed.')}
                      disabled={isProcessing}
                      className="w-full h-14 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center justify-center"
                    >
                      {isProcessing ? 'PACKING...' : 'MARK AS PACKED'}
                    </button>
                 )}
                 {['Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(order.status) && (
                    <div className="flex gap-3 h-14">
                        <button 
                            onClick={() => generateShippingLabel(order.id)}
                            disabled={isLabelGenerating}
                            className="flex-1 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50"
                        >
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                            {isLabelGenerating ? 'WAIT...' : 'LABEL'}
                        </button>
                        {order.status === 'Packed' && (
                            <button 
                                // Fix: Use capitalized status value
                                onClick={() => handleAction('Shipped', 'Handed over to logistics partner.')}
                                disabled={isProcessing}
                                className="flex-[1.5] bg-accent text-white rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-lg active:scale-95 transition-all flex items-center justify-center"
                            >
                                {isProcessing ? 'SYNC...' : 'DISPATCH'}
                            </button>
                        )}
                    </div>
                 )}
            </div>
        </div>
    );
};

export default VendorOrderDetailPage;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCategories } from '../../context/CategoryContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
import { SUPABASE_URL, SUPABASE_KEY } from '../../constants';

const AdminCategoryFormPage: React.FC = () => {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { getCategory, addCategory, updateCategory } = useCategories();

  const isEditing = id !== undefined;
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    image_url: '',
  });

  const inputClasses = "w-full mt-1 bg-surface text-text-main border border-gray-600 rounded-lg p-3 transition focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/50 disabled:opacity-50";

  useEffect(() => {
    if (isEditing && id) {
      const categoryToEdit = getCategory(id);
      if (categoryToEdit) {
        setFormData({ name: categoryToEdit.name, image_url: categoryToEdit.image_url || '' });
      }
    }
  }, [id, isEditing, getCategory]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setSelectedFile(file);

      // For local preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, image_url: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  /**
   * Resilient Image Upload
   * Attempts to upload to Supabase Storage. 
   * If the bucket is missing or upload fails, falls back to Base64 to ensure the category can still be saved.
   */
  const uploadImage = async (file: File): Promise<string> => {
    const fileName = `categories/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '_')}`;
    // Using 'assets' as it's a more standard default bucket name than 'category-images'
    const bucket = 'assets'; 
    const uploadUrl = `${SUPABASE_URL}/storage/v1/object/${bucket}/${fileName}`;

    try {
      const response = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
          'Content-Type': file.type
        },
        body: file
      });

      if (response.ok) {
        // Return the public URL if successful
        return `${SUPABASE_URL}/storage/v1/object/public/${bucket}/${fileName}`;
      } else {
        const errorData = await response.json().catch(() => ({}));
        console.warn(`Storage upload to '${bucket}' failed (${response.status}: ${errorData.message || 'Unknown error'}). Falling back to Base64.`);
      }
    } catch (err) {
      console.error("Network error during storage upload, falling back to Base64:", err);
    }

    // FALLBACK: Return as Base64 string if Storage is unavailable or fails
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = () => reject(new Error("Failed to read file for fallback."));
      reader.readAsDataURL(file);
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.image_url && !selectedFile) {
      alert("Please upload an image for the category.");
      return;
    }

    setIsSubmitting(true);
    try {
      let finalImageUrl = formData.image_url;

      // If a new file was selected, attempt upload
      if (selectedFile) {
        finalImageUrl = await uploadImage(selectedFile);
      }

      const submissionData = {
        name: formData.name,
        image_url: finalImageUrl
      };

      if (isEditing && id) {
        await updateCategory({ ...submissionData, id: id, slug: submissionData.name.toLowerCase().replace(/\s+/g, '-') });
        alert("Category updated successfully!");
      } else {
        await addCategory(submissionData);
        alert("Category created successfully!");
      }
      navigate('/admin/categories');
    } catch (err: any) {
      console.error("Category Submit Error:", err);
      alert(err.message || "An error occurred while saving the category.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div>
      <h1 className="text-3xl font-black text-text-main italic tracking-tight uppercase mb-6">
        {isEditing ? 'Edit Category' : 'Add New Category'}
      </h1>
      <GlassmorphicCard className="p-8 max-w-2xl mx-auto">
        <form onSubmit={handleSubmit} className="space-y-6">
            <div>
                <label className="block text-[10px] font-black uppercase text-text-muted mb-1" htmlFor="name">Category Name</label>
                <input 
                    type="text" 
                    id="name"
                    name="name" 
                    value={formData.name} 
                    onChange={handleChange} 
                    required 
                    disabled={isSubmitting}
                    placeholder="e.g., Electronics, Fashion"
                    className={inputClasses} 
                />
            </div>

            <div>
                <label className="block text-[10px] font-black uppercase text-text-muted mb-1">Visual Representation</label>
                <div className="mt-2">
                    <input 
                        type="file" 
                        id="imageUpload" 
                        accept="image/*" 
                        onChange={handleImageChange} 
                        className="hidden" 
                        disabled={isSubmitting}
                    />
                    <label 
                        htmlFor="imageUpload" 
                        className={`cursor-pointer bg-surface text-text-main font-bold py-3 px-6 rounded-xl border border-gray-600 hover:bg-gray-700 transition-all inline-block text-xs uppercase tracking-widest ${isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                        {formData.image_url ? 'Change Image' : 'Select Image File'}
                    </label>
                </div>
                {formData.image_url && (
                    <div className="mt-6 flex flex-col items-center p-4 bg-background/50 border border-dashed border-gray-600 rounded-2xl">
                        <p className="text-[9px] font-black uppercase text-text-muted mb-3">Live Preview</p>
                        <div className="w-40 h-40 rounded-full overflow-hidden border-4 border-white shadow-2xl">
                            <img 
                              src={formData.image_url} 
                              alt="Preview" 
                              className="w-full h-full object-cover"
                              onError={(e) => (e.currentTarget.src = 'https://placehold.co/400x400/F8F9FA/A0A0A0?text=Preview+Error')}
                            />
                        </div>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-4 pt-6 border-t border-border">
                <button 
                    type="button" 
                    onClick={() => navigate('/admin/categories')} 
                    className="px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest text-text-secondary hover:bg-surface transition-all"
                    disabled={isSubmitting}
                >
                    Cancel
                </button>
                <button 
                    type="submit" 
                    disabled={isSubmitting}
                    className="bg-accent text-white px-10 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-accent/30 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50"
                >
                    {isSubmitting ? 'Processing...' : (isEditing ? 'Update Category' : 'Create Category')}
                </button>
            </div>
        </form>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminCategoryFormPage;

