const AdminOrdersPage: React.FC = () => {
  const { orders, updateOrderStatus, generateShippingLabel, isLabelGenerating } = useOrders();
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [isShippingModalOpen, setShippingModalOpen] = useState(false);
  const [isHistoryModalOpen, setHistoryModalOpen] = useState(false);

  const handleStatusChange = (order: Order, status: OrderStatus) => {
    // Fix: Use capitalized status value and check for existing properties
    if (status === 'Shipped' && !order.awb_code && !order.tracking_id) {
      setSelectedOrder(order);
      setShippingModalOpen(true);
    } else {
      updateOrderStatus(order.id, status);
    }
  };

  const handleShippingSubmit = (courierName: string, trackingId: string) => {
    if (selectedOrder) {
      updateOrderStatus(selectedOrder.id, 'Shipped', { courier_name: courierName, tracking_id: trackingId });
    }
    setShippingModalOpen(false);
    setSelectedOrder(null);
  };

  const openHistoryModal = (order: Order) => {
    setSelectedOrder(order);
    setHistoryModalOpen(true);
  }

  const getStatusColor = (status: OrderStatus) => {
      switch(status) {
          // Fix: Use capitalized status values to match OrderStatus type
          case 'Placed': return 'text-gray-300 bg-gray-700/50 border-gray-600/50';
          case 'Confirmed': return 'text-cyan-400 bg-cyan-900/50 border-cyan-600/50';
          case 'Packed': return 'text-indigo-400 bg-indigo-900/50 border-indigo-600/50';
          case 'Shipped': return 'text-blue-400 bg-blue-900/50 border-blue-600/50';
          case 'Out for Delivery': return 'text-yellow-400 bg-yellow-900/50 border-yellow-600/50';
          case 'Delivered': return 'text-green-400 bg-green-900/50 border-green-600/50';
          case 'Cancelled': return 'text-red-400 bg-red-900/50 border-red-600/50';
          default: return 'text-gray-400 bg-gray-700/50 border-gray-600/50';
      }
  }

  return (
    <div>
      {isShippingModalOpen && selectedOrder && (
        <ShippingDetailsModal
          onClose={() => setShippingModalOpen(false)}
          onSubmit={handleShippingSubmit}
        />
      )}
      {isHistoryModalOpen && selectedOrder && (
        <OrderStatusHistoryModal
          history={selectedOrder.status_history || []}
          onClose={() => setHistoryModalOpen(false)}
        />
      )}
      <h1 className="text-3xl font-bold text-text-main mb-6">Manage Orders</h1>
      <GlassmorphicCard>
        <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-gray-700 text-text-muted">
                <th className="p-4 font-semibold">Order ID</th>
                <th className="p-4 font-semibold">Date</th>
                <th className="p-4 font-semibold">Customer</th>
                <th className="p-4 font-semibold">Total</th>
                <th className="p-4 font-semibold">Status</th>
                <th className="p-4 font-semibold">Update Status</th>
                <th className="p-4 font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(order => (
                <tr key={order.id} className="border-b border-gray-800 hover:bg-surface/50">
                  <td className="p-4 text-text-main font-mono">#{order.id}</td>
                  <td className="p-4">{new Date(order.created_at).toLocaleDateString()}</td>
                  <td className="p-4">{order.shipping_address?.fullName || order.user_id}</td>
                  <td className="p-4 font-semibold">₹{(order.total_amount || order.total || 0).toFixed(2)}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${getStatusColor(order.status)}`}>
                        {order.status}
                    </span>
                  </td>
                  <td className="p-4">
                     <select 
                        value={order.status} 
                        onChange={(e) => handleStatusChange(order, e.target.value as OrderStatus)}
                        className="bg-surface border border-gray-600 rounded-md p-1.5 text-text-main focus:ring-accent focus:border-accent text-xs"
                     >
                        {ALL_STATUSES.map(status => (
                            <option key={status} value={status}>{status}</option>
                        ))}
                    </select>
                  </td>
                   <td className="p-4 space-x-3 whitespace-nowrap">
                    <button onClick={() => openHistoryModal(order)} className="text-accent hover:underline text-xs font-semibold">
                      History
                    </button>
                    {/* Fix: Use capitalized status values for comparison */}
                    {['Packed', 'Shipped', 'Out for Delivery', 'Delivered'].includes(order.status) && (
                        <button 
                            onClick={() => generateShippingLabel(order.id)}
                            disabled={isLabelGenerating}
                            className="text-white bg-indigo-600 px-3 py-1 rounded-md text-xs font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50"
                        >
                            {isLabelGenerating ? '...' : 'Label'}
                        </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {orders.length === 0 && <p className="text-center p-8 text-text-muted">No orders have been placed yet.</p>}
        </div>
      </GlassmorphicCard>
    </div>
  );
};

export default AdminOrdersPage;

import React from 'react';
import { OrderStatus, StatusHistory } from '../types';

interface OrderTrackerProps {
  status: OrderStatus;
  history: StatusHistory[];
}

// Fix: Use capitalized status values to match OrderStatus type
const ALL_STATUSES: OrderStatus[] = ['Placed', 'Confirmed', 'Packed', 'Shipped', 'Out for Delivery', 'Delivered'];

const OrderTracker: React.FC<OrderTrackerProps> = ({ status, history }) => {

  // Fix: Use capitalized status value
  if (status === 'Cancelled') {
    const cancelEntry = history.find(h => h.status === 'Cancelled');
    return (
        <div className="p-6 bg-red-50 border border-red-100 rounded-2xl text-center">
            <div className="w-12 h-12 bg-red-100 text-red-500 rounded-full flex items-center justify-center mx-auto mb-3">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </div>
            <p className="font-black text-red-600 uppercase tracking-tight italic">Order Cancelled</p>
            {cancelEntry && <p className="text-[10px] text-red-400 mt-1 uppercase font-bold">{cancelEntry.note || 'Cancelled by User/System'}</p>}
        </div>
    );
  }

  const getStatusTimestamp = (s: OrderStatus) => {
    const entry = [...history].reverse().find(h => h.status === s);
    return entry ? entry.timestamp : null;
  }

  const currentStatusIndex = ALL_STATUSES.indexOf(status);

  return (
    <div className="p-6 bg-white border border-border rounded-2xl">
        <div className="space-y-8">
            {ALL_STATUSES.map((step, index) => {
                const isCompleted = currentStatusIndex > index;
                const isActive = currentStatusIndex === index;
                const timestamp = getStatusTimestamp(step);
                const stepEntry = history.find(h => h.status === step);

                return (
                    <div key={step} className="flex gap-4">
                        <div className="flex flex-col items-center">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 transition-all duration-500 z-10 ${isCompleted ? 'bg-accent border-accent' : isActive ? 'bg-white border-accent shadow-lg shadow-accent/20' : 'bg-surface border-border'}`}>
                                {isCompleted ? (
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                                ) : (
                                    <span className={`w-3 h-3 rounded-full ${isActive ? 'bg-accent animate-pulse' : 'bg-border'}`}></span>
                                )}
                            </div>
                            {index < ALL_STATUSES.length - 1 && (
                                <div className={`w-0.5 flex-grow my-1 transition-all duration-500 ${isCompleted ? 'bg-accent' : 'bg-border'}`}></div>
                            )}
                        </div>
                        <div className={`flex-grow pb-8 ${index === ALL_STATUSES.length - 1 ? 'pb-0' : ''}`}>
                            <div className="flex justify-between items-start">
                                <p className={`text-xs font-black uppercase tracking-widest ${isCompleted || isActive ? 'text-text-main' : 'text-text-muted'}`}>{step}</p>
                                {timestamp && <p className="text-[9px] font-black text-text-muted uppercase tracking-tighter">{new Date(timestamp).toLocaleDateString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</p>}
                            </div>
                            {stepEntry && (
                                <div className="mt-1">
                                    <span className="text-[8px] font-black uppercase text-accent bg-accent/5 px-2 py-0.5 rounded border border-accent/10">{stepEntry.actor || 'System'} Update</span>
                                    {stepEntry.note && <p className="text-[10px] text-text-muted mt-1 italic font-medium leading-tight">"{stepEntry.note}"</p>}
                                </div>
                            )}
                            {isActive && !timestamp && (
                                <p className="text-[9px] text-accent mt-1 font-bold animate-pulse uppercase tracking-widest">In Progress...</p>
                            )}
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default OrderTracker;

import React, { createContext, useState, useEffect, ReactNode, useContext } from 'react';
// Fix: Import newly defined Vendor type
import { Vendor } from '../types';
import { BASE_API_URL, API_HEADERS } from '../constants';

interface VendorContextType {
  vendors: Vendor[];
  currentVendor: Vendor | null;
  isVendorLoading: boolean;
  vendorError: string | null;
  addVendorRecord: (vendorData: Omit<Vendor, 'id' | 'created_at'>) => Promise<void>;
  updateVendorStatus: (vendorId: number, status: Vendor['status'], reason?: string) => Promise<void>;
  updateVendorProfile: (vendorId: number, updates: Partial<Vendor>) => Promise<void>;
  getVendorByUserId: (userId: string) => Vendor | undefined;
  getVendorById: (vendorId: string) => Vendor | undefined;
  getVendorByEmailDirect: (email: string) => Promise<Vendor | null>;
  fetchCurrentVendor: (userId: string, force?: boolean) => Promise<void>;
  refreshVendors: () => Promise<void>;
}

export const VendorContext = createContext<VendorContextType | undefined>(undefined);

// FIXED: Removed 'rejection_reason', 'wallet_balance', 'store_address', 'pending_balance' to match DB schema
const VENDOR_COLUMNS = 'id,user_id,store_name,status,owner_name,email,phone,profile_image';

export const VendorProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [currentVendor, setCurrentVendor] = useState<Vendor | null>(() => {
    const cached = sessionStorage.getItem('dch_vendor_cache');
    return cached ? JSON.parse(cached) : null;
  });
  const [isVendorLoading, setIsVendorLoading] = useState(false);
  const [vendorError, setVendorError] = useState<string | null>(null);

  const fetchVendors = async () => {
    try {
      const res = await fetch(`${BASE_API_URL}/vendors?select=*`, { 
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.message || `Fetch failed (${res.status})`);
      }

      if (Array.isArray(data)) {
          setVendors(data);
      } else {
          console.error("[VendorSync] Response not an array:", data);
      }
    } catch (error: any) {
      console.error("[VendorSync] List Error:", error.message);
    }
  };

  const fetchCurrentVendor = async (userId: string, force = false) => {
    if (!userId) return;

    if (!currentVendor || force) {
        setIsVendorLoading(true);
    }
    setVendorError(null);

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${userId}&select=${VENDOR_COLUMNS}`, {
        headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' } 
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.message || "Connection to vendor service failed.");
      }

      if (Array.isArray(data) && data.length > 0) {
        const profile = data[0];
        if (JSON.stringify(profile) !== JSON.stringify(currentVendor)) {
            setCurrentVendor(profile);
            sessionStorage.setItem('dch_vendor_cache', JSON.stringify(profile));
        }
      } else {
        setCurrentVendor(null);
        setVendorError("Vendor profile not found. Access denied.");
        sessionStorage.removeItem('dch_vendor_cache');
      }
    } catch (error: any) {
      console.error("[VendorSync] Profile Fetch Error:", error.message);
      setVendorError(error.message || "Failed to sync vendor profile.");
    } finally {
      setIsVendorLoading(false);
    }
  };

  useEffect(() => {
    let intervalId: any;
    if (currentVendor) {
        const pollStatus = async () => {
            try {
                const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${currentVendor.id}&select=${VENDOR_COLUMNS}`, {
                    headers: { ...API_HEADERS, 'Cache-Control': 'no-cache' }
                });
                if (res.ok) {
                    const data = await res.json();
                    if (Array.isArray(data) && data.length > 0) {
                        const fresh = data[0];
                        if (JSON.stringify(fresh) !== JSON.stringify(currentVendor)) {
                            setCurrentVendor(fresh);
                            sessionStorage.setItem('dch_vendor_cache', JSON.stringify(fresh));
                        }
                    }
                }
            } catch (e) {
                // Silent failure on poll
            }
        };
        const interval = currentVendor.status === 'pending' ? 4000 : 15000;
        intervalId = setInterval(pollStatus, interval);
    }
    return () => { if (intervalId) clearInterval(intervalId); };
  }, [currentVendor]);

  useEffect(() => {
    fetchVendors();
  }, []);

  const updateVendorProfile = async (id: number, updates: Partial<Vendor>) => {
    const safeUpdates: any = {};
    if (updates.store_name) safeUpdates.store_name = updates.store_name;
    if (updates.status) safeUpdates.status = updates.status;
    if (updates.profile_image) safeUpdates.profile_image = updates.profile_image;
    if (updates.phone) safeUpdates.phone = updates.phone;

    try {
      const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: { ...API_HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify(safeUpdates)
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.message || 'Update failed');
      }

      const updatedData = await res.json();
      if (Array.isArray(updatedData) && updatedData.length > 0) {
          const updatedVendor = updatedData[0];
          if (currentVendor && currentVendor.id === id) {
            setCurrentVendor(updatedVendor);
            sessionStorage.setItem('dch_vendor_cache', JSON.stringify(updatedVendor));
          }
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Update Error:", err.message);
      throw err;
    }
  };

  const addVendorRecord = async (data: Omit<Vendor, 'id' | 'created_at'>) => {
    try {
      const payload = {
        user_id: data.user_id,
        store_name: data.store_name,
        status: data.status || 'pending',
        owner_name: data.owner_name,
        email: data.email,
        phone: data.phone,
        profile_image: data.profile_image
      };

      const res = await fetch(`${BASE_API_URL}/vendors`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          throw new Error(err.message || 'Record creation failed');
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Create Error:", err.message);
      throw err;
    }
  };

  const updateVendorStatus = async (id: number, status: Vendor['status'], reason?: string) => {
    try {
      const payload: any = { status };
      // 'rejection_reason' column is missing in DB, skipping to avoid error
      const res = await fetch(`${BASE_API_URL}/vendors?id=eq.${id}`, {
        method: 'PATCH',
        headers: API_HEADERS,
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          console.error("Status update failed:", err?.message);
      }
      await fetchVendors();
    } catch (err: any) {
      console.error("[VendorSync] Status Error:", err.message);
    }
  };

  const getVendorByEmailDirect = async (email: string): Promise<Vendor | null> => null;
  const getVendorByUserId = (uid: string) => vendors.find(v => String(v.user_id) === String(uid));
  const getVendorById = (id: string) => vendors.find(v => String(v.id) === String(id));

  return (
    <VendorContext.Provider value={{ 
      vendors, currentVendor, isVendorLoading, vendorError,
      addVendorRecord, updateVendorStatus, updateVendorProfile,
      getVendorByUserId, getVendorById, getVendorByEmailDirect,
      fetchCurrentVendor, refreshVendors: fetchVendors 
    }}>
      {children}
    </VendorContext.Provider>
  );
};

export const useVendors = () => {
  const context = useContext(VendorContext);
  if (!context) throw new Error('useVendors missing');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useVendors } from '../../context/VendorContext';
import { useProducts } from '../../hooks/useProducts';
import { useOrders } from '../../context/OrderContext';
import GlassmorphicCard from '../../components/GlassmorphicCard';
// Fix: Import newly defined Vendor type
import { Vendor } from '../../types';
import { SearchIcon } from '../../components/icons/SearchIcon';
import Toast from '../../components/Toast';

const AdminVendorsPage: React.FC = () => {
  const { vendors, updateVendorStatus, refreshVendors } = useVendors();
  const { products } = useProducts();
  const { orders } = useOrders();
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState({ show: false, message: '' });
  const [isRefreshing, setIsRefreshing] = useState(false);

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await refreshVendors();
    setTimeout(() => setIsRefreshing(false), 500);
  };

  useEffect(() => { handleRefresh(); }, []);

  const filteredVendors = vendors.filter(v =>
    v.store_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    v.user_id.toString().includes(searchTerm)
  );

  const getVendorMetrics = (vendorId: string) => {
      const vProds = products.filter(p => String(p.vendor_id) === String(vendorId));
      const vOrders = orders.filter(o => o.vendor_id === vendorId && o.status !== 'Cancelled');
      const totalRev = vOrders.reduce((sum, o) => sum + (o.total || 0), 0);
      return { products: vProds.length, orders: vOrders.length, revenue: totalRev };
  };

  return (
    <div className="space-y-8 pb-20">
      <Toast isVisible={toast.show} message={toast.message} onClose={() => setToast({ ...toast, show: false })} />

      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-black text-gray-900 italic uppercase tracking-tighter leading-none">Vendor<br/><span className="text-accent">Master</span></h1>
          <p className="text-gray-400 font-bold text-sm mt-2">Managing {vendors.length} authorized marketplace nodes.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <input
              type="text"
              placeholder="Filter by Store Name or UID..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="bg-gray-50 border border-gray-100 rounded-2xl p-3 pl-10 transition w-80 text-xs font-bold uppercase tracking-widest placeholder:text-gray-300 focus:bg-white outline-none"
            />
            <SearchIcon className="absolute left-3 top-3 w-4 h-4 text-gray-300" />
          </div>
          <button 
            onClick={handleRefresh} 
            className={`p-3 bg-gray-50 border border-gray-100 rounded-2xl text-gray-400 hover:text-accent transition-all ${isRefreshing ? 'animate-spin' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h5M20 20v-5h-5M22 3A10.03 10.03 0 0112 20a9.93 9.93 0 01-7-3m7 5a10 10 0 01-10-10 9.93 9.93 0 013-7" /></svg>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {filteredVendors.map(vendor => {
          const metrics = getVendorMetrics(String(vendor.id));
          const isPending = vendor.status === 'pending';
          const isApproved = vendor.status === 'approved';

          return (
            <div key={vendor.id} className="bg-white rounded-[2.5rem] border border-gray-100 p-8 shadow-[0_8px_30px_rgb(0,0,0,0.01)] hover:shadow-[0_20px_50px_rgb(0,0,0,0.03)] transition-all flex flex-wrap lg:flex-nowrap items-center gap-10">
              <div className="flex items-center gap-6 shrink-0">
                  <div className="relative">
                    <img 
                        src={vendor.profile_image || `https://ui-avatars.com/api/?name=${encodeURIComponent(vendor.store_name)}&background=F8F9FA&color=1A1A1A&font-size=0.35&bold=true`} 
                        className="w-20 h-20 rounded-3xl object-cover bg-gray-50 border border-gray-100 shadow-sm"
                        alt=""
                    />
                    <div className={`absolute -bottom-1 -right-1 w-6 h-6 rounded-full border-4 border-white flex items-center justify-center ${isApproved ? 'bg-green-500' : 'bg-yellow-500 shadow-lg animate-pulse'}`}>
                        {isApproved ? (
                            <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                        ) : (
                            <span className="text-[10px] text-white font-black italic">!</span>
                        )}
                    </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-black text-gray-900 italic tracking-tighter uppercase leading-none">{vendor.store_name}</h3>
                    <p className="text-[10px] font-black text-accent uppercase tracking-widest mt-2">UID: DCH-VND-{vendor.id}</p>
                    <p className="text-[9px] font-bold text-gray-400 mt-1 uppercase">Merchant: {vendor.owner_name}</p>
                  </div>
              </div>

              <div className="flex-grow grid grid-cols-3 gap-6 border-x border-gray-50 px-10">
                  <div>
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Catalog Size</p>
                     <p className="text-xl font-black text-gray-900 italic">{metrics.products} Items</p>
                  </div>
                  <div>
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Bookings</p>
                     <p className="text-xl font-black text-gray-900 italic">{metrics.orders} Orders</p>
                  </div>
                  <div>
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Gross Yield</p>
                     <p className="text-xl font-black text-green-600 italic">₹{metrics.revenue.toLocaleString()}</p>
                  </div>
              </div>

              <div className="shrink-0 flex gap-2">
                  {isPending ? (
                      <>
                        <button 
                            onClick={() => updateVendorStatus(vendor.id, 'approved')}
                            className="bg-black text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-black/10 active:scale-95 transition-all"
                        >Authorize Partner</button>
                        <button 
                            onClick={() => updateVendorStatus(vendor.id, 'rejected')}
                            className="bg-red-50 text-red-500 border border-red-100 px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all"
                        >Reject</button>
                      </>
                  ) : (
                      <>
                        <button className="bg-gray-50 border border-gray-100 text-gray-900 px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm active:scale-95 transition-all">Audit</button>
                        <button 
                            onClick={() => updateVendorStatus(vendor.id, vendor.status === 'suspended' ? 'approved' : 'suspended')}
