import { useAuth } from './AuthContext';

interface ReviewContextType {
  getReviewsByProduct: (productId: number) => Promise<Review[]>;
  addReview: (reviewData: Partial<Review>) => Promise<void>;
  hasUserReviewedOrder: (orderId: string) => Promise<boolean>;
  isSubmitting: boolean;
}

const ReviewContext = createContext<ReviewContextType | undefined>(undefined);

export const ReviewProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const getReviewsByProduct = async (productId: number): Promise<Review[]> => {
    try {
      const res = await fetch(`${BASE_API_URL}/product_reviews?select=*,user:users(name)&product_id=eq.${productId}&order=created_at.desc`, {
        headers: API_HEADERS
      });
      if (!res.ok) return [];
      const data = await res.json();
      return Array.isArray(data) ? data : [];
    } catch (e) {
      console.error("Failed to fetch reviews", e);
      return [];
    }
  };

  const hasUserReviewedOrder = async (orderId: string): Promise<boolean> => {
    if (!user) return false;
    try {
      // Use order_id as the primary filter for uniqueness check
      const res = await fetch(`${BASE_API_URL}/product_reviews?order_id=eq.${orderId}&select=id`, {
        headers: API_HEADERS
      });
      const data = await res.json();
      return Array.isArray(data) && data.length > 0;
    } catch (e) {
      return false;
    }
  };

  const addReview = async (reviewData: Partial<Review>) => {
    if (!user || !user.auth_uid) {
      throw new Error("You must be logged in to submit a review, and your account must have a valid security ID.");
    }

    setIsSubmitting(true);
    try {
      // CRITICAL FIX: Directly use the auth_uid from the user context.
      // This removes the inefficient and error-prone database lookup.
      const resolvedUuid = user.auth_uid;

      const payload = {
        product_id: Number(reviewData.product_id),
        order_id: Number(reviewData.order_id), 
        rating: Number(reviewData.rating),
        review_text: reviewData.review_text || '',
        images: Array.isArray(reviewData.images) ? reviewData.images : [],
        video_url: reviewData.video_url || null, 
        user_id: resolvedUuid, // Use the correct UUID from the authenticated session
        created_at: new Date().toISOString()
      };

      const res = await fetch(`${BASE_API_URL}/product_reviews`, {
        method: 'POST',
        headers: { ...API_HEADERS, 'Prefer': 'return=minimal' },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        console.error(`[ReviewContext] Database Rejection:`, res.status, JSON.stringify(errData, null, 2));

        if (res.status === 403 || res.status === 409) {
            throw new Error("Action restricted: You may have already reviewed this purchase.");
        }

        throw new Error(errData.message || "Failed to submit review. Database constraint violation.");
      }
    } catch (err: any) {
        console.error("[ReviewContext] Submit Fail:", err.message);
        throw err;
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <ReviewContext.Provider value={{ getReviewsByProduct, addReview, hasUserReviewedOrder, isSubmitting }}>
      {children}
    </ReviewContext.Provider>
  );
};

export const useReviews = () => {
  const context = useContext(ReviewContext);
  if (!context) throw new Error("useReviews missing provider");
  return context;
};

import React, { useState, useRef } from 'react';
import { OrderItem } from '../types';
import { useReviews } from '../context/ReviewContext';

interface RateProductModalProps {
  item: OrderItem;
  orderId: string;
  onClose: () => void;
  onSubmit: () => void;
}

const RateProductModal: React.FC<RateProductModalProps> = ({ item, orderId, onClose, onSubmit }) => {
  const { addReview, isSubmitting } = useReviews();
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');
  const [hoverRating, setHoverRating] = useState(0);
  const [images, setImages] = useState<string[]>([]);
  const [videoUrl, setVideoUrl] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const labels = ["Very Bad", "Bad", "Ok-Ok", "Good", "Very Good"];

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('image/')) {
          const reader = new FileReader();
          reader.onloadend = () => {
            setImages(prev => [...prev, reader.result as string].slice(0, 5));
          };
          reader.readAsDataURL(file);
        } else if (file.type.startsWith('video/')) {
          const url = URL.createObjectURL(file);
          setVideoUrl(url);
        }
      });
    }
  };

  const removeImage = (idx: number) => {
    setImages(prev => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await addReview({
        // Fix: Ensure product_id is a number
        product_id: Number(item.id),
        order_id: Number(orderId), // Ensure it's a number for the DB
        rating,
        review_text: comment,
        images,
        video_url: videoUrl || undefined // Use video_url string property
      });
      onSubmit();
      onClose();
    } catch (err: any) {
      alert(err.message || "Failed to submit review");
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="w-full max-w-md bg-white rounded-3xl overflow-hidden shadow-2xl scale-in-center max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-white sticky top-0 z-10">
          <h2 className="text-sm font-black uppercase tracking-widest text-gray-800 italic">Rate Product</h2>
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-800 transition-colors">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-8 overflow-y-auto">
          <div className="flex items-center gap-4 bg-gray-50 p-4 rounded-2xl border border-gray-100">
            <img src={item.image} alt={item.name} className="w-12 h-12 rounded-lg object-cover border border-white shadow-sm" />
            <p className="text-xs font-bold text-gray-700 line-clamp-1 italic uppercase tracking-tight">{item.name}</p>
          </div>

          <div className="text-center">
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 mb-4 italic">Overall Satisfaction</p>
            <div className="flex justify-center gap-2">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  type="button"
                  onMouseEnter={() => setHoverRating(star)}
                  onMouseLeave={() => setHoverRating(0)}
                  onClick={() => setRating(star)}
                  className="transition-transform active:scale-90"
                >
                  <svg 
                    className={`w-10 h-10 transition-colors ${
                      (hoverRating || rating) >= star ? 'text-yellow-400' : 'text-gray-100'
                    }`} 
                    fill="currentColor" 
                    viewBox="0 0 20 20"
                  >
                    <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                  </svg>
                </button>
              ))}
            </div>
            <p className="mt-3 text-xs font-black text-accent uppercase italic tracking-widest">{labels[(hoverRating || rating) - 1]}</p>
          </div>

          <div>
             <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3 block italic">Add Photos & Video (Optional)</label>
             <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-20 h-20 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl flex flex-col items-center justify-center shrink-0 active:bg-gray-100"
                >
                  <svg className="w-6 h-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                  <span className="text-[8px] font-black text-gray-400 mt-1 uppercase">Add Media</span>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,video/*" multiple onChange={handleFileChange} />

                {images.map((img, idx) => (
                  <div key={idx} className="relative w-20 h-20 shrink-0">
                    <img src={img} className="w-full h-full object-cover rounded-2xl border border-gray-100" />
                    <button type="button" onClick={() => removeImage(idx)} className="absolute -top-1 -right-1 bg-red-500 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold shadow-sm">×</button>
                  </div>
                ))}

                {videoUrl && (
                  <div className="relative w-20 h-20 shrink-0">
                     <video src={videoUrl} className="w-full h-full object-cover rounded-2xl border border-gray-100" />
                     <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" /></svg>
                     </div>
                     <button type="button" onClick={() => setVideoUrl('')} className="absolute -top-1 -right-1 bg-red-500 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold shadow-sm">×</button>
                  </div>
                )}
             </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2 block italic">Add Detailed Feedback</label>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Tell us about the quality, fit, or look..."
              className="w-full bg-gray-50 text-gray-800 border border-gray-100 focus:border-accent rounded-2xl p-4 text-xs h-24 transition-all resize-none shadow-inner font-medium outline-none"
            />
          </div>

          <div className="flex items-center gap-2 bg-[#E7F7F0] p-3 rounded-xl border border-[#D1F7E6]">
             <svg className="w-4 h-4 text-[#34BE82]" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 01-2.812-2.812 3.066 3.066 0 00-.723-1.745 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
             <span className="text-[9px] font-black text-[#34BE82] uppercase tracking-widest">Verified Purchase Badge will be added</span>
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full bg-accent text-white font-black uppercase tracking-widest text-[11px] py-4 rounded-2xl shadow-xl shadow-accent/20 hover:-translate-y-1 active:translate-y-0 transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'Submitting...' : 'Submit Verified Review'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default RateProductModal;

import React, {
  createContext,
  useState,
  useEffect,
  ReactNode,
  useContext,
} from "react";
// Fix: Import newly added Vendor type
import { Order, OrderStatus, Address, PaymentStatus, Vendor } from "../types.ts";
import { useAuth } from "./AuthContext.tsx";
import { useNotifications } from "./NotificationContext.tsx";
import { BASE_API_URL, API_HEADERS } from "../constants.ts";

interface OrderContextType {
  orders: any[];
  isLoading: boolean;
  isLabelGenerating: boolean;
  activeOrderForLabel: any | null;
  addOrder: (orderData: any) => Promise<string>;
  updateOrderStatus: (
    orderId: string,
    status: OrderStatus,
    details?: any
  ) => Promise<void>;
  createShipment: (orderId: string, vendorData: any) => Promise<void>;
  generateShippingLabel: (orderId: string) => void;
  closeLabelPreview: () => void;
  refreshOrders: () => Promise<void>;
  getOrderById: (orderId: string) => any | undefined;
  getOrderByToken: (token: string) => any | undefined;
  updateOrderByToken: (
    token: string,
    status: OrderStatus,
    note?: string
  ) => Promise<{ success: boolean; message: string }>;
}

const OrderContext = createContext<OrderContextType | undefined>(undefined);

export const OrderProvider: React.FC<{ children: ReactNode }> = ({
  children,
}) => {
  const { user } = useAuth();
  const { fetchInbox, createAppNotification } = useNotifications();
  const [orders, setOrders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [activeOrderForLabel, setActiveOrderForLabel] = useState<any | null>(null);

  const refreshOrders = async () => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    // FIX: Skip fetch for guest users (ID starts with 'guest-') to avoid DB type errors
    if (user.id.toString().startsWith('guest-')) {
        setOrders([]);
        setIsLoading(false);
        return;
    }

    try {
      setIsLoading(true);
      // Simplified join syntax for better compatibility
      let selectString = `*,vendor:vendors(*)`;
      let filter = `order=created_at.desc`;

      if (user.role === "user") {
        // Use auth_id (UUID) to query orders, ensuring consistency with how reviews are linked.
        filter += `&user_id=eq.${user.auth_uid}`;
      } else if (user.role === "vendor") {
        const vRes = await fetch(`${BASE_API_URL}/vendors?user_id=eq.${user.id}&select=id`, { headers: API_HEADERS });
        if (!vRes.ok) {
           const errText = await vRes.text();
           console.error("[OrderContext] Vendor profile fetch failed:", errText);
           throw new Error("Vendor profile unreachable");
        }
        const vData = await vRes.json();
        if (Array.isArray(vData) && vData.length > 0) {
            filter += `&vendor_id=eq.${vData[0].id}`;
        } else {
            setOrders([]);
            setIsLoading(false);
            return;
        }
      }

      const res = await fetch(`${BASE_API_URL}/orders?select=${selectString}&${filter}`, {
        headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({ message: res.statusText }));
        console.warn("[OrderContext] Primary fetch failed, trying fallback. Error:", errData.message);

        const fallbackRes = await fetch(`${BASE_API_URL}/orders?select=*&${filter}`, {
            headers: { ...API_HEADERS, "Cache-Control": "no-cache" },
        });

        if (fallbackRes.ok) {
            const data = await fallbackRes.json();
            processOrders(data);
            return;
        } else {
            const fallbackErr = await fallbackRes.json().catch(() => ({ message: fallbackRes.statusText }));
            console.error("[OrderContext] Fallback fetch failed:", fallbackErr.message);
            // Don't throw here to avoid crashing the UI loop, just log
            setOrders([]); 
            return;
        }
      }

      const data = await res.json();
      processOrders(data);
    } catch (e: any) {
      console.error("[OrderContext] Fatal Sync Error:", e.message);
      setOrders([]);
    } finally {
      setIsLoading(false);
    }
  };

  const processOrders = (data: any[]) => {
    if (Array.isArray(data)) {
      setOrders(
        data.map((o: any) => {
          /**
           * Robust Address Extraction:
           * Retrieve the snapshot from the status_history entry where it was saved.
           */
          const addressSource = (o.status_history?.[0]?.address_snapshot) ||
                                (typeof o.metadata === 'object' && o.metadata?.address ? o.metadata.address : null) ||
                                (typeof o.address === 'object' ? o.address : null) || 
                                (typeof o.shipping_address === 'object' ? o.shipping_address : null) || 
                                null;

          return {
            ...o,
            id: o.id.toString(),
            total: Number(o.total_amount || o.total || 0),
            discount_amount: Number(o.discount_amount || 0),
            statusHistory: o.status_history || [],
            qrToken: o.qr_token,
            date: o.created_at,
            seller_name: o.vendor?.store_name || "DAR CYCLE HUB Direct",
            shippingAddress: addressSource,
          };
        })
      );
    }
  };

  useEffect(() => {
    if (user) {
        refreshOrders();
        // Only fetch inbox if it's a real user, guests usually don't have DB notifications
        if (!user.id.toString().startsWith('guest-')) {
            fetchInbox(user);
        }
    } else {
        setOrders([]);
        setIsLoading(false);
    }
  }, [user]);

  const generateShippingLabel = (orderId: string) => {
    const order = orders.find(o => o.id === orderId);
    if (order) {
      setActiveOrderForLabel(order);
    }
  };

  const closeLabelPreview = () => {
    setActiveOrderForLabel(null);
  };

  const addOrder = async (orderData: any): Promise<string> => {
    if (!user) throw new Error("Authentication required.");
    const timestamp = new Date().toISOString();
    const qrToken = Math.random().toString(36).substring(2, 15);

    const addressSnapshot = {
      fullName: orderData.shippingAddress?.fullName || 'Customer',
      street: orderData.shippingAddress?.street || '',
      city: orderData.shippingAddress?.city || '',
      state: orderData.shippingAddress?.state || '',
      zip: orderData.shippingAddress?.zip || '',
      phone: orderData.shippingAddress?.phone || '',
    };

    const rawVendorId = orderData.items[0]?.vendor_id;
    let vendorIdValue: any = null;
    if (rawVendorId) {
      vendorIdValue = isNaN(Number(rawVendorId)) ? rawVendorId : Number(rawVendorId);
    }

    // CRITICAL FIX: Use the auth_id (UUID) as the user_id foreign key.
    // This aligns with how reviews are stored and assumes orders.user_id is a UUID.
    const userIdValue = user.auth_uid ? user.auth_uid : null;

    const payload: any = {
      user_id: userIdValue,
      vendor_id: vendorIdValue,
      items: orderData.items,
      total_amount: Number(orderData.total),
      discount_amount: Number(orderData.discount_amount || 0), // Store UPI discount
      payment_mode: orderData.payment_method,
      payment_status: orderData.payment_method === "Cash on Delivery" ? "cod_pending" : "paid",
      status: "Placed" as OrderStatus,
      qr_token: qrToken,
      status_history: [{ 
        status: "Placed", 
        timestamp, 
        actor: "User", 
        note: "Order placed",
        address_snapshot: addressSnapshot 
      }],
      created_at: timestamp
    };

    const res = await fetch(`${BASE_API_URL}/orders`, {
      method: "POST",
      headers: { ...API_HEADERS, "Prefer": "return=representation" },
      body: JSON.stringify(payload),
    });

    if (!res.ok) {
      const errorBody = await res.json().catch(() => ({}));
      console.error("[OrderContext] Database Rejection Details:", res.status, JSON.stringify(errorBody));
      throw new Error(errorBody.message || `Order placement failed (Status: ${res.status})`);
    }

    const result = await res.json();
    const orderId = result[0].id.toString();

    // Only attempt notifications if we have a valid user ID, otherwise client-side only
    if (userIdValue) {
        try {
            await createAppNotification({
                user_id: userIdValue,
                role: 'user',
                title: 'Order Confirmed',
                message: 'Your order has been placed successfully.',
                type: 'order_status'
            });

            if (vendorIdValue) {
                await createAppNotification({
                    vendor_id: vendorIdValue,
                    role: 'vendor',
                    title: 'New Order Received',
                    message: `You have received a new order (#${orderId.slice(-6)}). Please pack it.`,
                    type: 'order_alert'
                });
            }
        } catch (notifErr) {
            console.warn("Background notification trigger failed", notifErr);
        }
    }

    refreshOrders();
    // Only refresh inbox if valid user
    if (userIdValue && user) fetchInbox(user);

    return orderId;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus, details: any = {}) => {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;

    const history = order.statusHistory || [];
    const newHistory = [...history, {
        status,
        timestamp: new Date().toISOString(),
        actor: user?.role === "vendor" ? "Vendor" : user?.role === "admin" ? "Admin" : "System",
        note: details.note || `Order status transitioned to ${status}`,
    }];

    const updatePayload: any = { status, status_history: newHistory };
    if (details.courier_name) updatePayload.courier_name = details.courier_name;
    if (details.tracking_id) updatePayload.tracking_id = details.tracking_id;

    const res = await fetch(`${BASE_API_URL}/orders?id=eq.${orderId}`, {
      method: "PATCH",
      headers: { ...API_HEADERS },
      body: JSON.stringify(updatePayload),
    });

    if (res.ok) {
        // Notifications only for non-guest users usually, but logic exists inside createAppNotification
        try {
            if (order.user_id && !order.user_id.toString().startsWith('guest-')) {
// Fix: Use capitalized status values to match the OrderStatus type
                if (status === 'Packed') {
                    await createAppNotification({
                        user_id: order.user_id,
                        role: 'user',
                        title: 'Order Packed',
                        message: 'Your order has been packed and will be shipped soon.',
                        type: 'order_status'
                    });
// Fix: Use capitalized status values to match the OrderStatus type
                } else if (status === 'Shipped') {
                    await createAppNotification({
                        user_id: order.user_id,
                        role: 'user',
                        title: 'Order Shipped',
                        message: 'Your order is on the way. Tracking updates will be available soon.',
                        type: 'order_status'
                    });
// Fix: Use capitalized status values to match the OrderStatus type
                } else if (status === 'Delivered') {
                    await createAppNotification({
                        user_id: order.user_id,
                        role: 'user',
                        title: 'Order Delivered',
                        message: 'Your order has been delivered successfully. Please rate the product.',
                        type: 'order_status'
                    });
                    if (order.vendor_id) {
                        await createAppNotification({
                            vendor_id: order.vendor_id,
                            role: 'vendor',
                            title: 'Payment Credited',
                            message: `Order #${orderId.slice(-6)} has been delivered. Amount has been added to your wallet.`,
                            type: 'wallet_update'
                        });
                    }
                }
            }
        } catch (notifErr) {
            console.warn("Status notification trigger failed", notifErr);
        }

        await refreshOrders();
        if (user && !user.id.toString().startsWith('guest-')) await fetchInbox(user);
    }
  };

  const createShipment = async (orderId: string, vendorData: any) => {
    // Fix: Use capitalized status to match OrderStatus type
    await updateOrderStatus(orderId, 'Confirmed', { note: 'Shipment manifest processing started.' });
  };

  const getOrderById = (id: string) => orders.find((o) => o.id === id);
  const getOrderByToken = (token: string) => orders.find((o) => o.qrToken === token || o.qr_token === token);

  const updateOrderByToken = async (token: string, status: OrderStatus, note?: string) => {
    const order = getOrderByToken(token);
    if (!order) return { success: false, message: "Invalid token." };
    await updateOrderStatus(order.id, status, { note });
    return { success: true, message: `Status updated to ${status}` };
  };

  return (
    <OrderContext.Provider
      value={{
        orders,
        isLoading,
        isLabelGenerating: false,
        activeOrderForLabel,
        addOrder,
        updateOrderStatus,
        createShipment,
        generateShippingLabel,
        closeLabelPreview,
        refreshOrders,
        getOrderById,
        getOrderByToken,
        updateOrderByToken,
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export const useOrders = () => {
  const context = useContext(OrderContext);
  if (!context) throw new Error("OrderContext missing.");
  return context;
};

